The reduction in \cref{thm:erlinesrank3} produces a linear hypergraph without two degree-1 vertices being part of the same hyperedge. Hence, applying a standard point-line duality transformation to a line representation $H$ results in a representation of its max-degree-$3$ dual hypergraph and vice versa. This is enough to show that $\exists\RR$-hardness also holds for max-degree-$3$ hypergraphs.
\begin{corollary}\label{thm:erlinesdeg3}
    It is $\exists\RR$-hard to decide whether a max-degree-3 hypergraph has a line representation.
\end{corollary}


\subparagraph*{Solvable cases.}
By definition, non-linear hypergraphs do not have line representations. However, every rank-2 hypergraph (which is linear) and every linear max-degree-2 hypergraph has a strict line representation by starting with points or lines in general position, respectively.
%
\begin{observation}\label{obs:linerank-2}
    Every rank-2 hypergraph and every linear max-degree-2 hypergraph has a line representation.
\end{observation}
\subsection{Complexity results for line segments}\label{section:representationslinesegments}

\subparagraph*{Hardness results.}
The first result is that deciding whether a hypergraph has a segment representation is $\exists\RR$-hard, even for hypergraphs of constant rank and constant maximum degree.
\begin{theorem}\label{thm:erlinesgmentsrank3}
    It is $\exists\RR$-hard to decide whether a rank-$3$ max-degree-$6$ hypergraph has a segment representation.
\end{theorem}
\begin{proof}
    We reduce from \textsc{pseudoline stretchability}~\cite{s-csgtp-09}.
    Given an instance $I$ of \textsc{pseudoline stretchability},
    we construct a hypergraph~$H$ by taking intersection points as vertices. For each pseudoline with the intersection points $v_1, v_2,\dots,v_t$ in this order, we construct hyperpaths consisting of the hyperedges $\{v_1,v_2,v_3\},\{v_2,v_3,v_4\}, \dots,\{v_{t-2}, v_{t-1}, v_t\}$ (\cref{fig:nonstrHard}(a)--(b)).

    By the construction of $H$, a solution to the \textsc{pseudoline stretchability} instance corresponds to a representation with straight line segments (\cref{fig:nonstrHard}(c)): We assume that $H$ has a representation with straight line segments. Observe that then the union of hyperedges forming the hyperpaths as above appear together as one single line segment with the vertices in the correct order.
    Conversely, if $I$ is stretchable, then $H$ has a segment representation.
\end{proof}

\begin{figure}
    \centering    \includegraphics[width=\linewidth]{./graphics/nonstricthardness.pdf}
    \caption{(a) A pseudoline arrangement. (b) Illustration of the hyperedges corresponding to a pseudoline as in the proof of \cref{thm:erlinesgmentsrank3}.  (c) A corresponding segment representation. (d)--(f) Illustration for the reduction of \cref{thm:erlinesgmentsmdeg2}. }
    \label{fig:nonstrHard}
\end{figure}

We show later that the problem becomes tractable for rank $2$ instead of rank~$3$. Surprisingly, this is not the case for maximum degree $2$ even for constant rank, as shown with a similar but more involved reduction.

\begin{theorem}\label{thm:erlinesgmentsmdeg2}
    It is $\exists\RR$-hard to decide whether a rank-$5$ max-degree-$2$ hypergraph has a segment representation.%
\end{theorem}
\begin{proof}
    We reduce from \textsc{pseudoline stretchability}~\cite{s-csgtp-09}. Let $I$ be an instance of \textsc{pseudoline stretchability} with at least five lines. To construct a hypergraph $H$, we first add to $H$ all the intersection points of $I$ as vertices.
    For each pseudoline with the intersection points $v_1, v_2,v_3,v_4,\dots,v_{t-2},v_{t-1},v_t$ in this order, we introduce the further vertices $v_{i,1},v_{i,2}$ for all $1\le i\le t-1$. We then add the hyperedges $\{v_1,v_{1,1},v_{1,2}\}$, $\{v_t,v_{t-1,1},v_{t-1,2}\}$, and $\{v_i,v_{i-1,1},v_{i-1,2},v_{i,1},v_{i,2}\}$ for all $2\le i\le t-1$. By the construction of $H$, in any representation $v_1,v_2,\dots,v_t$ must be collinear and appear in the correct order (\cref{fig:nonstrHard}(d)--(f)).
\end{proof}
\begin{figure}[ht]
    \centering    \includegraphics[width=.6\linewidth]{./graphics/strictlinesegmentreduction.pdf}
    \caption{A strict segment representation of the hypergraph resulting from the reduction in \cref{thm:erstrictlinesegments} applied to the pseudoline arrangement in \cref{fig:nonstrHard}(a).}
    \label{fig:erstrictlinesegments}
\end{figure}
