  \begin{pmatrix}
    \boldsymbol{p}_S(t) \\[6pt]
    \boldsymbol{p}_R(t)
  \end{pmatrix},
\]
where \(\mathbf{A}_{SS}\) and \(\mathbf{A}_{RR}\) represent transitions within \(S\) and \(R\), respectively, while \(\mathbf{A}_{SR}\) and \(\mathbf{A}_{RS}\) represent transitions between these sets, as illustrated in Figure~\ref{fig:transitions}.
\end{remark}

