\section{Proposed Approach: RoboMonkey}
\vspace{-0.12in}
\begin{figure*}[h!]
    \centering    \includegraphics[width=1.0\textwidth]{images/new_pipeline.pdf}
    \vspace{-0.1in}
    \caption{
    \textbf{Stage 1: Training the Action Verifier.} Given an imitation learning dataset, we sample $N$ candidate actions per state from a generalist robot policy, and apply clustering to reduce them to $K$ representative actions. We construct $\binom{K}{2}$ synthetic action comparisons and assign preferences based on the RMSE between each sampled action and the ground-truth action. This synthetic preference dataset is then used to fine-tune a VLM-based action verifier.
    \textbf{Stage 2: Scaling Test-Time Compute.} At deployment, we sample $\hat{N}$ initial actions from the generalist robot policy based on the given task instruction and observation. We fit a Gaussian distribution $\mathcal{N}(\mu, \sigma)$ to the translation and rotation components $(\Delta x,\ \Delta y,\ \Delta z,\ \Delta u,\ \Delta v,\ \Delta w)$ of these actions, as introduced in \Cref{sec:prelim}, and use majority voting to determine the gripper state. This creates an action proposal distribution from which we can efficiently sample candidate actions with negligible overhead. Finally, we use the fine-tuned VLM-based verifier to evaluate these $\hat{K}$ candidate actions and select the optimal action.}
    \label{pipeline}
    \vspace{-0.1in}
\end{figure*}

\subsection{Motivation}
After establishing the potential for scaling test-time compute for robotics in Section~\ref{sec:scaling}, we now present RoboMonkey, a framework that leverages a learned action verifier to scale test-time compute. We first describe our method for curating a synthetic action preference dataset, followed by reward modeling and inference-time techniques used within RoboMonkey's generate-then-verify pipeline.

\subsection{Synthetic Data Generation Pipeline}\label{section:synthetic}
In this section, we outline our approach for generating synthetic action comparisons, which leverages an existing demonstration dataset $\mathcal{D}$ to produce action pairs with high-quality preference labels without the need for human annotation. Specifically, for each tuple $(s_t,\ a_t^*,\ I)$ from our auxiliary dataset $\mathcal{D}_{\text{buf}}$, we use a reference robot policy to generate $N$ candidate actions. To ensure diversity among the samples, we apply clustering algorithms, reducing these candidates to $K$ representative actions. Subsequently, we construct $\binom{K}{2}$ pairwise comparisons and compute the RMSE between each sampled action, $\{a_t^1,\ a_t^2,\ \dots,\ a_t^K\}$, and the ground-truth action, $a_t^*$. Then, the ``winning" action, $a_t^W$, and the ``losing" action, $a_t^L$, between any two actions $a_t^i$ and $a_t^j$ are determined as follows:
\[
(a_t^W, \ a_t^L) = 
\begin{cases}
    (a_t^i,\ a_t^j), & \text{if } \text{RMSE}(a_t^i,\ a_t^*) < \text{RMSE}(a_t^j,\ a_t^*), \\[6pt]
    (a_t^j,\ a_t^i), & \text{otherwise.}
\end{cases}
\]

% where $\Delta_{ij}^* = \text{RMSE}(\hat{a}_i, a^*) - \text{RMSE}(\hat{a}_j, a^*)$. Intuitively, $\Delta_{ij}^*$ quantifies how much better the preferred action is relative to the alternative. During training, we randomly sample batches of pairwise comparison results, specifically pairs of actions ($a^W, a^L$) from identical initial conditions ($s$, $I$). 

We use this procedure to instantiate our action preference dataset $\mathcal{D}_{\text{comp}}$ consisting of tuples $(a_t^W,\ a_t^L,\ a_t^*,\ s_t,\ I)$. Following Ouyang et.al~\cite{ouyang2022traininglanguagemodelsfollow}, we take all $\binom{K}{2}$ pairwise comparisons from identical initial conditions $(s_t,\ I)$ and group these together as a single batch for training.

\subsection{Reward Modeling} \label{sec:rm}
The loss function for training the reward model follows the Bradley-Terry model~\cite{touvron2023llama} with additional modifications to account for preference levels. Formally, we define the ground truth preference level as $\Delta_t^* = \left| \text{RMSE}(a_t^W,\ a_t^*) - \text{RMSE}(a_t^L,\ a_t^*) \right| $ and the predicted preference level from our action verifier $R_{\phi}: A\times S\times\mathcal{I}\rightarrow\mathbb{R} \text{, parameterized by } \phi \in \mathbb{R}^{|\phi|}$, as $\hat{\Delta}_t = \left| R_\phi(a_t^W,\ s_t,\ I) - R_\phi(a_t^L,\ s_t,\ I)\right|$. These components are then integrated into our loss function for training the reward model:
\[
\mathcal{L}(\phi;\ \mathcal{D}_\text{comp}) = -\mathbb{E}_{(a_t^W,\ a_t^L,\ a_t^*,\ s_t,\ I) \sim D_{\text{comp}}} 
\left[ 
\log\ \sigma \left( R_\phi(a_t^W,\ s_t,\ I) - R_\phi(a_t^L,\ s_t,\ I)
- \alpha \left\| \Delta_t^* - \hat{\Delta}_t \right\|^2_2
\right) \right],
\]
where $\sigma : \mathbb{R} \rightarrow [0,\ 1]$ is the sigmoid function and $\alpha\in\mathbb{R}$ is a hyperparameter to control the magnitude of the preference level. We find that including the margin component $\left\| \Delta_t^* - \hat{\Delta}_t \right\|^2_2$ improves the accuracy, particularly when distinguishing between clearly different actions. For more detailed analysis and ablation studies, please refer to Appendices~\ref{E} and~\ref{F}. The action verifier uses LLaVA-7B~\cite{liu2023llava, sun2023aligninglargemultimodalmodels} as the backbone and replaces its final unembedding layer with a reward head. The architecture integrates ViT-Large~\cite{radford2021learningtransferablevisualmodels} as the vision encoder and uses a MLP to map the visual features into the same dimensionality as the word embedding space of the language model.

\subsection{Action Sampling and Verification}\label{sec:robomonkey}

A visualization of the pipeline is shown in Figure~\ref{pipeline}. Formally, at each timestep $t$ during deployment under instruction $I$, RoboMonkey first samples $\hat{N}$ candidate actions from a VLA model $\pi_\theta(a \mid s_t,\ I;\ \mathcal{T})$ with a positive temperature $\mathcal{T}$, yielding a set of candidate actions $\hat{A} = \{\hat{a}_t^1,\ \ldots,\ \hat{a}_t^{\hat{N}}\} \in \mathbb{R}^{m \times \hat{N}}$. Given these samples, we determine the gripper action $g_t$ via majority voting over the discrete gripper component: $g_t = \text{mode}(\{g_t^i\}_{i=1}^{\hat{N}})$. We then fit a Gaussian distribution $\mathcal{N}(\mu_t, \Sigma_t)$ to both the translational components $\{[\Delta \hat{x}_t^i,\ \Delta \hat{y}_t^i,\ \Delta \hat{z}_t^i]'\}_{i=1}^{\hat{N}}$ and rotational components $\{[\Delta \hat{u}_t^i,\ \Delta \hat{v}_t^i,\ \Delta \hat{w}_t^i]'\}_{i=1}^{\hat{N}}$. RoboMonkey then samples $\hat{K}$ new actions from this proposal distribution and appends the fixed gripper state $g_t$ to each, forming a refined action set $\tilde{A} = \{\tilde{a}_t^1,\ \ldots,\ \tilde{a}_t^{\hat{K}}\} \in \mathbb{R}^{m \times \hat{K}}$. Finally, each action $\tilde{a}_t^i$ is scored using our reward model $R_\phi(\tilde{a}_t^i,\ s_t,\ I)$ from which we select the action with the highest reward for execution $a_t = \arg\max_{\tilde{a}_t^i \in \{\tilde{a}_t^1,\ \ldots,\ \tilde{a}_t^{\hat{K}}\}} R_\phi(\tilde{a}_t^i,\ s_t,\ I)$. Below, \Cref{alg:RoboMonkey} presents our detailed test-time scaling pipeline.

\begin{algorithm}
\caption{RoboMonkey Execution}
\label{alg:RoboMonkey}
\KwIn{Generic VLA model $\pi_\theta: \mathcal{S} \times \mathcal{I}\rightarrow A$, reward model $R_\phi: A\times  \mathcal{S} \times\mathcal{I}\rightarrow\mathbb{R}$, initial state $s_0 \in \mathcal{S}$, task instruction $I \in\mathcal{I}$, temperature $\mathcal{T}\in\mathbb{R}_{++}$, time horizon $T\in\mathbb{N}_+$, number of VLA samples $\hat{N}\in\mathbb{N}_+$, number of Gaussian samples $\hat{K}\in\mathbb{N}_+.$}
\For{$t = 0, 1, \ldots, T$}{
    Sample $\hat{A}_t = \{\hat{a}_t^i\}_{i=1}^{\hat{N}} \sim \pi_\theta(a \mid s_t,\ I;\ \mathcal{T})$ \\
    Compute gripper state $g_t \gets \text{mode}(\{\hat{g}_t^i\}_{i=1}^{\hat{N}})$ \\
    Fit Gaussian distribution $\mathcal{N}(\mu_t,\ \Sigma_t)$ on $\{[\Delta \hat{x}_t^i,\ \Delta \hat{y}_t^i,\ \Delta \hat{z}_t^i,\ \Delta \hat{u}_t^i,\ \Delta \hat{v}_t^i,\ \Delta \hat{w}_t^i]'\}_{i=1}^{\hat{N}}$ \\
    Sample $\tilde{A}_t = \{\tilde{a}_t^i\}_{i=1}^{\hat{K}} \sim \mathcal{N}(\mu_t,\ \Sigma_t)$ \\
    Set $\tilde{a}_t^i \gets [\Delta \tilde{x}_t^i,\ \Delta \tilde{y}_t^i,\ \Delta \tilde{z}_t^i,\ \Delta \tilde{u}_t^i,\ \Delta \tilde{v}_t^i,\ \Delta \tilde{w}_t^i,\ g_t]'$ for all $i\in\{1,\ 2,\ \ldots,\ \hat{K}\}$ \\
    Select action $a_t \gets \arg\max_{\tilde{a}_t^i \in \{\tilde{a}_t^1,\ \ldots,\ \tilde{a}_t^{\hat{K}}\}} R_\phi(\tilde{a}_t^i,\ s_t,\ I)$ \\
    Execute $a_t$ and observe $s_{t+1}$ \\
}
\end{algorithm}

