\end{figure}

If two elements are enclosed in the same bracket, any ordering between them is associated with the same tree. 
Therefore, the distance between the trees in this case is equal to zero (as in \autoref{fig:trees1}a and b). 
Given a sequence $p$ described in the Newick format, the \emph{length of $p$} is defined as the number of integers represented in $p$. 
The distance between two trees is denoted by $d(T_p, T_q)$.


\defproblema{Distance between trees}
{Two trees, $T_p$ and $T_q$, with associated Newick format sequences $p$ and $q$, of the same length, and an integer $k$.}
{is $d(T_p, T_q) \leq k$?}


To establish a distance calculation between trees, the following steps are taken. 

\begin{observation}\label{obs:morethan1}
It can be assumed that a pair of brackets contains at least two elements. 
\end{observation}


As a direct consequence of constructing trees based on the Newick format, we have \autoref{prop:internalnodes}.

\begin{proposition}\label{prop:internalnodes}
The number of internal nodes of a tree is equal to the number of bracket pairs. 
\end{proposition}


To determine the distance between $T_p$ and $T_q$, we need to find the minimum number of operations over a tree to take $T_p$ and transform into $T_q$. 
An \emph{operation over a tree} $T_p$ is defined as moving a subtree from its level to one step above or below in $T_p$. 
Such a subtree is either an internal node with all its descendants or a unique leaf node of $T_p$. 



\section{Distance between trees}\label{sec:distances}

Now we determine distance between trees by first considering trees with limited height and then defining a distance based on the subjacent problem we define as {\sc Maximum common subtree}. 

\subsection{Distance based on tree height}\label{sec:h2}

The height of a tree, denoted as $h(T)$, is defined as the number of edges in the longest path between the root and a leaf. 
To determine the distance between trees, we consider cases where $h(T)$ is bounded by fixed values. Specifically, we relate this metric to the swap distance between permutations when $h(T)=2$~\cite{cunha2020computational}.

\begin{proposition}[$\star$]\label{prop:equal0}
For any pair of trees $T_p$ and $T_q$ associated with Newick sequences $p$ and $q$ of the same length, if both $h(T_p)$ and $h(T_q)$ are both equal to~$1$, then $d(T_p,T_q) = 0$.
\end{proposition}
% \begin{proof}
% Since the height of each tree is equal to $1$, it follows from \autoref{obs:morethan1} that there is a unique bracket pair of the corresponding sequences. 
% Thus, all elements belong to the same bracket, and then, any order of those integers associates to an equal tree, by construction.
% \qed\end{proof}

% \medskip

As a consequence of \autoref{prop:equal0}, every pair of permutations $\pi, \sigma \in S_n$ satisfies $d(T_\pi, T_\sigma) = 0$, where $S_n$ is the symmetric group of permutations of length $n$. 

% \medskip

Permutations can also be represented by each element followed by its image. For example, given a set $\{1, 2, 3\}$, the sequence $(1\ 2\ 3)$ maps $1$ to $2$, $2$ to $3$, and $3$ to $1$, corresponding to the permutation $[2 \ 3\ 1]$.
This representation is not unique; for example, $(2\ 3\ 1)$ and $(3\ 1\ 2)$ are equivalent.
Permutations are composed of one or more algebraic cycles, where each \emph{algebraic cycle of a permutation} $\pi$ is a representation of a domain $i$, followed by its image $\pi(i)$, followed by taking the image of $\pi(i)$ as the next element, i.e., $\pi(\pi(i))$, and so on. 
We continue this process until we reach a repeated element, 
which defines the permutation. 
We denote by $c(\pi)$ the number of algebraic cycles of $\pi$. 
For example, 
given $\pi = [3\ 2 \ 4 \ 1] = (1\ 3 \ 4)(2)$, we have $c(\pi) =2$. 
In general, when comparing two distinct permutations $\pi$ and $\sigma$ we may also compute the algebraic cycle in a same matter. 
An \emph{algebraic cycle of a permutation $\pi$ with respect to a permutation} $\sigma$ is a representation of a domain $\sigma(i)$, followed by its image in $\pi$, continuing until we reach a repeated element. 
For example, given $\sigma = [2 \ 4\ 1\ 3]$ and $\pi = [3 \ 2 \ 4 \ 1]$, we have the following algebraic cycle $c(\pi,\sigma) = (2 \ 3 \ 1 \ 4)$. 
Hence, $c(\pi) = c(\pi,\iota)$, where $\iota$ is the \emph{identity permutation} $\iota = [1\ 2\ \cdots n]$. 


An exchange of elements involving elements $a$ and $b$ such that $a$ and $b$ are in the same cycle is an exchange that \emph{breaks} the cycle in two, whereas if $a$ and $b$ belong to different cycles, the exchange of these elements \emph{merges} the two cycles~\cite{fertin2009combinatorics}.
Thus, when considering the \emph{swap} operation, which is an exchange of a pair of elements of a permutation, the \emph{swap} distance between $\pi$ and $\sigma$ of length $n$ is determined as $d_{\sf swap}(\pi,\sigma) = n - c(\pi,\sigma)$, where $c(\pi,\sigma)$ is the number of algebraic cycles of $\pi$ with respect to $\sigma$, and it can be computed in linear time.


\begin{lemma}[$\star$]\label{lm:h2}
Given a tree $T_p$ of Newick the sequence $p$ of length $n$, $h(T_p) \leq 2$ if and only if $p$ is an algebraic cycle of a permutation of length $n$. 
\end{lemma}
% \begin{proof}
% On one hand, based on the hierarchy of the rooted tree $T_p$, the number of children the root has is the number of parenthesis pairs within the most external pair associated with the root node. 
% Furthermore, each child of the root has a unique pair of brackets associated with it. 
% Therefore, if $h(T_p) \leq 2$, then all leaves with the same parent correspond to an algebraic cycle. 
% On the other hand, every algebraic cycle is associated with a subtree which is composed of a unique internal node and all others are leaves corresponding to the elements of the cycle. 
% Therefore all cycles are children of a same internal node, and then $h(T_p) \leq 2$. 
% \qed\end{proof}


Given a tree $T_p$ with $h(T_p) = 2$, we denote $\pi_p$ the permutation whose algebraic cycle is $p$. 

\begin{theorem}[$\star$]\label{thm:h2=swap}
If $h(T_p) = h(T_q) = 2$, then $d(T_p,T_q) = d_{swap}(\pi_p,\pi_q)$.
\end{theorem}
% \begin{proof}
% Since the heights of $T_p$ and $T_q$ are equal to $2$, any operation on a tree has the effect of breaking one bracket pair or merging two brackets, as well as the effect of any swap operation in the corresponding algebraic cycles. 
% Moreover, since two nodes can be children of the same node with any label, it is always possible to apply a viable swap in the corresponding order between $p$ and $q$.
% \qed\end{proof}



\subsection{Distance between trees according to common subtrees}\label{sec:mcat}

Given a Newick sequence $p$ and its tree $T_p$, 
we have a subtree of $T_p$ as $B^p_i$, which is called a \emph{bracket set}. 
All such sets are elements of $\mathcal{B}^p$. 
For convenience, we list the elements of a bracket set from top to bottom of a given tree $T_p$. 
For example, $p = ((1,2)((4,3)5))$ has $\mathcal{B}^p = \{B^p_1, B^p_2, B^p_3, B^p_4\}$, where $B^p_1 = \{B^p_2, B^p_3\}, B^p_2 = \{1,2\}, B^p_3 = \{B^p_4, 5\}, B^p_4 = \{4,3\}$. 


\begin{observation}
For any two bracket sets $B^p_i$ and $B^p_j$ that satisfy $B^p_i = \{B^p_j\}$, the bracket set $B^p_j$ can be kept in $p$ and $B^p_i$ removed from $p$, which implies removing a bracket pair from~$p$. 
\end{observation}


% \subparagraph{Isomorphic trees}
\paragraph{Isomorphic trees.}

Given two sequences $p$ and $q$, 
if there are bracket sets where $B^p_i = B^q_j$, then they correspond to the same subtree of $T_p$ and $T_q$. 
Therefore, we say that $d(B^p_i, B^q_j) = 0$ since those subtrees of $T_p$ and $T_q$ are equal.


\begin{theorem}[$\star$]\label{thm:dist0}
Given $T_p$ and $T_q$, it can be decided in polynomial time whether $d(T_p, T_q)~=~0$. 
\end{theorem}
