\section{Proofs deferred from \autoref{sec:distances}}\label{sec:appA}

\noindent
\autoref{prop:equal0}.
\emph{
For any pair of trees $T_p$ and $T_q$ associated with Newick sequences $p$ and $q$ of the same length, if both $h(T_p)$ and $h(T_q)$ are both equal to 1, then $d(T_p,T_q) = 0$.
}
\begin{proof}
Since the height of each tree is equal to $1$, it follows from \autoref{obs:morethan1} that there is a unique bracket pair of the corresponding sequences. 
Thus, all elements belong to the same bracket, and then, any order of those integers associates to an equal tree, by construction.
\qed\end{proof}


\noindent
\autoref{lm:h2}.
\emph{
Given a tree $T_p$ of Newick the sequence $p$ of length $n$, $h(T_p) \leq 2$ if and only if $p$ is an algebraic cycle of a permutation of length $n$. 
}
\begin{proof}
On one hand, based on the hierarchy of the rooted tree $T_p$, the number of children the root has is the number of parenthesis pairs within the most external pair associated with the root node. 
Furthermore, each child of the root has a unique pair of brackets associated with it. 
Therefore, if $h(T_p) \leq 2$, then all leaves with the same parent correspond to an algebraic cycle. 
On the other hand, every algebraic cycle is associated with a subtree which is composed of a unique internal node and all others are leaves corresponding to the elements of the cycle. 
Therefore all cycles are children of a same internal node, and then $h(T_p) \leq 2$. 
\qed\end{proof}


\noindent
\autoref{thm:h2=swap}.
\emph{
If $h(T_p) = h(T_q) = 2$, then $d(T_p,T_q) = d_{swap}(\pi_p,\pi_q)$.
}
\begin{proof}
Since the heights of $T_p$ and $T_q$ are equal to $2$, any operation on a tree has the effect of breaking one bracket pair or merging two brackets, as well as the effect of any swap operation in the corresponding algebraic cycles. 
Moreover, since two nodes can be children of the same node with any label, it is always possible to apply a viable swap in the corresponding order between $p$ and $q$.
\qed\end{proof}



\noindent
\autoref{thm:dist0}.
\emph{
Given $T_p$ and $T_q$, it can be decided in polynomial time whether $d(T_p, T_q) = 0$. 
}
\begin{proof}
In order to prove that we show the following lemma:

\begin{lemma}\label{lm:dist0}
Let $f$ be a function where $f: \mathcal{B}^p \rightarrow \mathcal{B}^q$. 
The function $f$ is a bijection where $f(B^p_i) = B^q_j$ 
if and only if 
$d(T_p, T_q) = 0$.
\end{lemma}
\begin{proof}
If there is a bijection $f: \mathcal{B}^p \rightarrow \mathcal{B}^q$ where $f(B^p_i) = B^q_j$, then every subtree of $p$ is related to an equal subtree of $q$ with the same elements, then for every $B^p_i$ there is $B^q_j$ where $d(B^p_i, B^p_j) = 0$. This implies that $d(T_p, T_q) = 0$. 
Conversely, if $d(T_p, T_q) = 0$ implies that every internal node $i$ of $p$ has a corresponding internal node $j$ of $q$, where $B^p_i = B^q_j$. 
So this correspondence is a bijection where $f(B^p_i) = B^q_j$. 
\qed\end{proof}

As a consequence of \autoref{thm:dist0}, if $d(T_p,T_q)=0$, then $T_p \approx T_q$, i.e. the corresponding trees are isomorphic. 
If this is the case, we should analyze whether every bracket set of $p$ is equal to a bracket set of $p$. 
Since isomorphism of trees is determined in linear time~\cite{campbell1991tree}, and finding two equal sets can also be determined in linear time, this concludes the proof. 
\qed\end{proof}




\noindent
\autoref{thm:distance}.
\emph{
Given $T_p$ and $T_q$, $d(T_p,T_q)$ can be determined in polynomial time.
}
\begin{proof}
We determine the distance between $T_p$ and $T_q$ by obtaining $H$ being the solution of MCAT$(T_p,T_q)$. Hence: 

\vspace{-.6cm}
\begin{equation}\label{eq:distance}
 d(T_p,T_q) = d(T_p[H],T_q[H]) + d(T_p / H,T_q / H) + |n(T_p) - n(T_q)|,   
\end{equation}
\vspace{-.6cm}

\noindent
where $n(T_p)$ (analogously $n(T_q)$) is the number of nodes in $T_p$ (in $T_q$), 
$G/H_v$ is the resulting graph after contracting $H_v$. 
Since the set of leaves of $T_p[H]$ is equal to the set of leaves of $T_q[H]$, then 
\autoref{eq:distance} calls \autoref{eq:dist1} to compute $d(T_p[H],T_q[H])$, and then we compute recursively the distance between $T_p / H$ and $T_q / H$. 
In each call of the MCAT problem, a solution subtree $H$ is an almost $v$-tree, which is common in both trees, hence with the same number of leaves and internal nodes. 
Thus, as a consequence of the MCAT problem, when the recursive call reaches a base case, there are $|n(T_p) - n(T_q)|$ internal nodes contained in $T_p$ (in $T_q$) that are not contained in $T_q$ (in $T_p$). 
For each of these nodes, it is necessary to perform an extra operation, removing one internal node in each of them (as illustrated in \autoref{fig:final}). 

\vspace{-.6cm}
\begin{figure}[H]
    \centering
    \includegraphics[width=8cm]{final.pdf}

    \caption{Base case of recursion considering $T_p$ in $(i)$ and $T_q$ in $(ii)$. After contracting $H$, there remains one internal node in $(i)$ and three internal nodes in $(ii)$, and then $2$ operations must be applied. \label{fig:final}}
\end{figure}

\vspace{-.5cm}
Since a solution of MCAT can be determined in quadratic time and the recursion calls a MCAT solution at most $n(T_p)$ times, then we can compute the distance between the input trees in cubic running time, in worst case.
\qed\end{proof}




\section{Proof deferred from \autoref{sec:closest}}\label{sec:appB}


\noindent
\autoref{thm:breakpointRestriction}.
\emph{
{\sc Breakpoint-Median$_3$} is \NP-complete, even for instances that do not contain two consecutive breakpoints. 
}
\begin{proof}
{\sc Breakpoint-Median$_3$} is \NP-complete, proved independently by Bryant~\cite{bryant1998complexity} and Pe'er and Shamir~\cite{pe1998median}. 
Now, we prove that this problem remains \NP-complete if the input consists of three permutations that do not contain two consecutive breakpoints, which is done by a reduction from {\sc Breakpoint-Median$_3$}. 
Let $\pi_1, \pi_2, \pi_3$ be permutations of length $n$ which are input for {\sc Breakpoint-Median$_3$}. 
For each permutation, we define an extension operation of such permutation by transforming it into another one by the following process: between any two consecutive elements $\pi_x[i], \ \pi_x[i+1]$ add the pair of new elements $n+i, \ n+i+1$, for $i = 1, \ldots, n-1$ and $x\in \{1,2,3\}$. 

Each one of the three created has length $3n-2$ and we have added $n-1$ new adjacencies of the form $n+i, \ n+i+1$, for $i = 1, \ldots, n-1$. 
As proved by Bryant~\cite{bryant1998complexity}, if an adjacency occurs in all of the input permutations, it occurs also in a solution of the {\sc Breakpoint Median} problem, 
hence we have that the solution of {\sc Breakpoint-Median$_3$} will contain all of these new adjacencies we have just added. 
Moreover, a pair $\pi_x[i], \ \pi_x[i+1]$ is a breakpoint for $x \in \{1,2,3\}$ if and only if $\pi_x[i], \ n+1$ and $\pi_x[i+1], \ n+i+1$ are breakpoints in the extended permutations of $\pi_x$. 
Otherwise, if $\pi_x[i], \ n+1$ is an adjacency it implies that there is a pair $\pi_y[i], \ n+1$, for $y \neq x$, and then it must also have $\pi_y[i+1], \ n+i+1$, since $n+1$ and $n+i+1$ are placed together in the construction for all input permutations. 
Hence, any two permutations $\pi_x$ and $\pi_y$ has $d_{\sf BP}(\pi_x, \pi_y) = k$ if and only if its extended permutations $\pi'_x$ and $\pi'_y$ has $d_{\sf BP}(\pi'_x, \pi'_y) = 2k$. 
Based on that, we have that $\sigma$ is a solution of {\sc Breakpoint-Median$_3$} with input $\pi_1, \pi_2, \pi_3$ if and only if its extended permutation $\sigma'$ is a solution of {\sc Breakpoint-Median$_3$} of the input being obtained by extending the permutations $\pi_1, \pi_2, \pi_3$. 
\qed\end{proof}



