  \begin{tabular}{lccc}
    \toprule
    Method & $L_Q$ & $L_K$ & Per-Head Cost \\
    \midrule
    TTT       & $k\ell$ & $k\ell$ & $O\left((k\ell)^2\right)$ \\
    CT-Prompt & $k\ell$ & $k\ell$ & $O\left((k\ell)^2\right)$ \\
    CT-KV     & $\ell$  & $k\ell$ & $O\left(k\,\ell^2\right)$ \\
    \bottomrule
  \end{tabular}
  \caption{
    \looseness=-10000
