\section{Proofs}\label{appendix:proofs}

Recall that all proofs are developed in continuation value space. Unless necessary to avoid confusion, we drop the dependence of reachable histories $h^{+k}_q(\sigma)$ on the policy $\sigma$.

\subsection*{Proof of \Cref{lemma:terminal or ordered}.}

Because $h$ is non-terminal, $\sigmalr(h) = 1 - l_h + 1 - \phi(l_h)$. We consider two cases. 

\medskip
\noindent

\textit{Case 1:} $q(\sigmalr(h)) \geq \phi(l_{h})$.
Then, 
$$S_{h^{+1}_q} = [1-l_h, \sigmalr(h) - 1 + q(\sigmalr(h))] \cup [\sigmalr(h) + 1 -q(\sigmalr(h)), 1],$$
where, by the assumption in this case, \begin{align*}
    \sigmalr(h) - 1 + q(\sigmalr(h)) &\geq \sigmalr(h) - 1 + \phi(l_h)\\ &= 1-l_h + 1 - \phi(l_h) - 1  + \phi(l_h)\\ &= 1-l_h.
\end{align*}
Therefore, $h^{+1}_q$ is not an ordered search history. Let $n = N(c,l_h)$. Then, the length of the search window is
\begin{align*}\label{equation:relationship lengths}
\begin{split}
   l_{h^{+1}_q} &> q(\sigmalr(h)) - \sigmalr(h) \\ &= 2(\phi(l_h)) - 2 + l_h \\
   &= \frac{n-1}{n}l_{h} - (n-1)c.
   \end{split}
\end{align*}
Because $\phi(\cdot)$ is decreasing, $\phi(l_{h^{+1}_q}) <  \phi\big(\frac{n-1}{n}l_{h} - (n-1)c\big)$. By Equation \ref{eq:N(c,a)}, $n(n-1)c \leq l_h < n(n+1)c$. This implies that $(n-1)(n-2)c \leq \frac{n-1}{n}l_{h} - (n-1)c < (n-1)nc$. Therefore, 
\begin{align*}
    \phi\Big(\frac{n-1}{n}l_{h} - (n-1)c\Big) &= 1 - \frac{1}{2(n-1)}\Big(\frac{n-1}{n}l_{h} - (n-1)c\Big) - \frac{n-2}{2}c \\
    &= 1 - \frac{l_h}{2n} - \frac{n-1}{2}c + c\\
    &= \phi(l_h) + c.
\end{align*}
Therefore, $$\phi(l_{h^{+1}_q}) -c < \phi(l_h) \leq q(\sigmalr(h)).$$ Because $\sigmalr$ ignores past discoveries, this directly implies that $h^{+1}_q$ is terminal according to \Cref{definition:opt_policy}.

\medskip
\noindent

\textit{Case 2:}
Suppose instead that $q(\sigmalr(h)) < \phi(l_{h})$. Then, $$S_{h^{+1}_q} = [\sigmalr(h) + 1 - q(\sigmalr(h)), 1],$$ so $h^{+1}_q$ is an ordered search history. 
By assumption 
$l_{h^{+1}_q} < \frac{n-1}{n}l_{h} - (n-1)c$, so $\phi(l^{+1}_h) > \phi(l_h) + c$. 
Then, combining, we get $q(\sigmalr(h)) < \phi(l_{h}) < \phi(l^{+1}_h) - c$, therefore $h^{+1}_q$ is not a terminal history.  \hfill \openbox

\subsection*{Proof of \Cref{prop:sigmalr is simple}}

    First, the left-to-right policy is \emph{threshold} by definition. Next, the threshold depends on the history only through the length of the search window $l_h$, so $\sigmalr$ is \emph{index}.

    Third, note that by equation \ref{eq:N(c,a)},
    \begin{align*}
    \phi(l) = 1-\frac{l}{2N(c,l)} - \frac{N(c,l)-1}{2}c &\leq 1-\frac{N(c,l) (N(c,l)-1)}{2} - \frac{N(c,l)-1}{2}c \\
    &= 1-(N(c,l)-1)c \leq 1
    \end{align*}
    as long as $N(c,l) > 0$. If $h^{+1}_q$ is not a terminal node, then $l_{h^{+1}_q} \leq l_h - 2(1-\phi(l_h))$, so 
    \begin{align*}
        \sigmalr(h^{+1}_q) > 1 - l_{h^{+1}_q} &\geq 1 - l_{h} +  (2 - \phi(l_h))\\ &> 1 - l_{h} + 1 - \phi(l_h) = \sigmalr(h),
    \end{align*}
    where the last inequality follows from the fact that $\phi(l) \leq 1$ for any $l$. Therefore, the left-to-right policy is \emph{directional}.

    Finally, \Cref{lemma:terminal or ordered} implies that if $h^{+1}_q$ is not a terminal history, it is an ordered search history. The search window shrinks from $h$ to $h^{+1}_q$ for any $q\in \Omega_h$ where the discovery has quality below the target, i.e., $l_{h^{+1}_q} < l_h$. Because $\phi(\cdot)$ is decreasing, $\phi(l_{h^{+1}_q}) > \phi(l_h)$, so the stopping threshold increases between $h$ to $h^{+1}_q$. Increasing stopping thresholds imply that the left-to-right policy \emph{ignores past discoveries}.


\subsection*{Proof of \Cref{thm:opt}}
To show that $\sigmalr$ is optimal, we must consider three kinds of deviations:
\begin{enumerate}
    \item Stopping when $\sigmalr$ recommends continuing, 
    \item Continuing when $\sigmalr$ recommends stopping, 
    \item Searching an item other than $\sigmalr(h)$.
\end{enumerate}
\Cref{lemma:threshold_is_worst} shows that deviations of the first or second kind do not strictly improve the agent's worst-case eventual payoff. \Cref{lemma:no better with other sigma} shows that deviations of the third kind also do not strictly improve the agent's worst-case eventual payoff. \openbox



\subsection*{Proof of \Cref{lemma:threshold_is_worst}}


Let $h\in H^{\sigmalr}$ be a non-terminal history and $q\in Q_h$.  


\medskip
\noindent
\textit{Base Case:} $N(c,l_h) = 1$. Because $h$ is non-terminal, $S_h = [a,1]$ for some $a\in(0, 1]$, so $\sigmalr(h) = a + \frac{l_h}{2}$. The threshold $\phi(l_h)$ is $1-\frac{l_h}{2}$. There is no feasible $\tilde{q} \in Q_h$ such that $\tilde{q}(\sigmalr(h)) < \phi(l_h)$, because such a $\tilde{q}$ does not attain a value of $1$ anywhere. Therefore, $q(\sigmalr(h)) \geq \phi(l_h)$, so $\sigmalr$ stops, so $\phi(l_h)-c\leq V_q^{\sigmalr}(h)$.

\medskip
\noindent
\textit{Induction Hypothesis:} Suppose that for any $h'\in H^{\sigmalr}$ such that $N(c,l_{h'}) \leq n-1$ and for all $q\in\Omega_{h'}$, $$\phi(l_{h'}) - c \leq V_{q}^{\sigmalr}(h').$$

\medskip
\noindent
\textit{Inductive Step:} $N(c,l_h) = n$. The case where $q(\sigmalr(h)) \leq \phi(l_h)$ is trivial, so suppose that $q(\sigmalr(h)) < \phi(l_h)$.
Then, $$S_{h^{+1}_{q}} = [\sigmalr(h) + 1 - q(\sigmalr(h)), 1].$$ Then
\begin{align*}
    l_{h^{+1}_{q}} = q(\sigmalr(h)) - \sigmalr(h)  &< \phi(l_h) - \sigmalr(h) \\ 
    &= \phi(l_h) - (1 - l_h + 1 - \phi(l_h)) \\
    &= 2\phi(l_h) + l_h - 2 \\
    &= \frac{n-1}{n}(l_h - nc) \\
    & < n(n-1)c,
\end{align*}
where the last inequality is because $l_h < n(n+1)c$ by Equation \ref{eq:N(c,a)}. This implies that $N(c,l_{h^{+1}}(q)) = n-k$, for some $1\leq k < n$. By the inductive hypothesis, $$V_q^{\sigmalr}(h^{+1}_{q}) \geq \phi(l_{h^{+1}_{q}}) -c.$$ Moreover, $l_{h^{+1}_{q}} < (n-k)(n-k + 1)c$ by Equation \ref{eq:N(c,a)}. Because $\phi$ is decreasing, \begin{align*}
    \phi(l_{h^{+1}_{q}}) - c \geq \phi\big((n-k)(n-k+1)c\big) - c &= 1-\frac{(n-k)(n-k+1)c}{2(n-k)} - \frac{(n-k-1)}{2}c -c\\
    &= 1 - (n-k)c - c
\end{align*}
Finally, because $l_h \geq n(n-1)c$ by Equation \ref{eq:N(c,a)}, 
\[\phi(l_h) \leq 1-\frac{n(n-1)}{2n}c - \frac{n-1}{2}c = 1 - (n-1)c \leq 1 - (n-k)c - c.\]
Therefore, $V_q^{\sigmalr}(h^{+1}_{q}) \geq \phi(l_h)$. Because $h$ is non-terminal, $V_q^{\sigmalr}(h) = V_q^{\sigmalr}(h^{+1}_{q}) - c$, so $$V_q^{\sigmalr}(h) \geq \phi(l_h) -c.$$ \hfill \openbox

\subsection*{Proof of \Cref{lemma:no better with other sigma}}


For $k=0, 1, 2, 3\ldots$ define history $h^{+k}$ as follows:

$$h^{+k} \equiv
\begin{cases*}
    h, \text{ if } k=0\\
    h^{+(k-1)}, \text{ if } \sigma(h^{+(k-1)}) = \emptyset\\
    h^{+(k-1)} \cup \big(\sigma(h^{+(k-1)}\big), \ z^*(h^{+k})\big), \text{ otherwise,}
\end{cases*}$$
where,
$$z^*(h^{+k}) = \min \Big\{ \phi(l_h) + (k-1)c, \max_{q \in Q_{h^{+(k-1)}}} q\big(\sigma(h^{+(k-1)})\big) \Big\}$$.


For all $k\geq 1$, the best item at $h^{+k}$ has quality at most $\phi(l_h) + (k-1)c$. The agent had to pay $kc$ to reach history $h^{+k}$ from $h$. 
Therefore, letting $\bar{k}$ be such that $h^{+\bar{k}}$ is a terminal history, for any $\tilde{q} \in Q_{h^{+\bar{k}}}$,
\[V^\sigma_{\tilde{q}}(h) \leq \phi(l_h) + (k-1)c - kc = \phi(l_h) - c.\]

It remains to be shown that there exists some $\tilde{q}\in Q_{h^{+\bar{k}}}$. For this, it suffices to show that (i) for any two $(x', z'), (x'', z'') \in h^{+\bar{k}}$, $\frac{z''-z'}{x''-x'}\leq L$, and (ii) $S_{h^{+\bar{k}}}$ is nonempty. The former follows directly by construction of $h^{+\bar{k}}$, so next we argue the latter.


Let $n = N(c,l_h)$. Note that $S_{h^{+k}} =  S_{h^{+(k-1)}}$ if $z^*(h^{+k}) < \phi(l_h) + (k-1)c$. 
Therefore, for $k>n$, either  
\begin{align*}z^*(h^{+k}) = \phi(l_h) + kc > \phi(l_h) + nc &= 1 - \frac{l_h}{2n} - \frac{n-1}{2}c + nc \\&> 1 - \frac{n(n+1)}{2n} - \frac{n-1}{2}c + nc = 1,\end{align*} which would imply that $S_k$ is nonempty,
or $S_{h^{+k}} =  S_{h^{+(k-1)}}$. 

Then, by induction, $h^{+\bar{k}}$ is nonempty if $\bar{k}>n$ and $S_{h^{+n}}$ is nonempty. Otherwise, if $\bar{k} < n$, $S_{h^{+n}} \subseteq S_{h^{+\bar{k}}}$. Therefore, to show that $h^{+\bar{k}}$ is nonempty, it suffices to show that $S_{h^{+n}}$ is nonempty. 


From the $h^{+(k-1)}$ to $h^k$, the search window shrinks by at most an open ball of radius $1-z^*(h^{+k})$, denoted by $B(h^{+k})$. 
The measure of the search window $S_{h^{+n}}$ must then be
\begin{align*}
    \mu(S_{h^{+n}}) \geq \mu\bigg(S_h \setminus \cup_{k=0}^{n-1} B(h^{+k})\bigg) &\geq \mu(S_h) - \sum_{k=0}^{n-1} 2\big(1-z^*(h^{+k})\big) \\
    &\geq l_h - \sum_{k=0}^{n-1} 2\big(1-\phi(l_h) - kc\big) \\
    &= l_h - \sum_{k=0}^{n-1} 2\Big(
    \frac{l_h}{n} + \frac{n-1}{2}c - kc\Big) \\
    &= l_h - l_h + \frac{n(n-1)}{2}c - \frac{n(n-1)}{2}c = 0.
\end{align*}

The search window at history $h^{+n}$ has always weakly positive measure. If the  measure is strictly positive, $S_{h^{+n}}$ is nonempty. Otherwise, note that since each ball $B(h^{+k})$ is an open set, the search window must contain at least an isolated point.\hfill \openbox




