\subsubsection{Modular Lattices}
\begin{definition}[Modular Lattices]
    A ranked lattice $\cL$ is modular if for any two flats $F,G\in \cL$ we have 
    $$ \rk(F)+\rk(G)=\rk(F\vee G)+\rk(F\wedge G).$$
\end{definition}

%Given a ranked lattice $\cL$ and $F,G\in \cL$ with $F<G$, the {\bf sub-lattice}  $\cL_{[F,G]}$ is the ranked lattices which contains all flats $H$ with $F<H<G$.

\begin{definition}[Typical Modular Lattices]
Given a modular lattice $\cL$, we say $\cL$ is typical if it satisfies the following:
    For any interval sub-lattice $\cL_{[F,G]}$ with $\rk(G)=\rk(F)+3$, the bipartite graph $G=({\cal F}_1,{\cal F}_2,E)$ between rank 1 and rank 2 flats of $\cL_{[F,G]}$ either has no vertex of degree 1 in the ${\cal F}_1$ side or no vertex of degree 1 in the ${\cal F}_2$ side, or exactly one degree 1 vertex in both of ${\cal F}_1,{\cal F}_2$ sides.
\end{definition}
It is not hard to see that any distributive lattice is modular. 
\begin{theorem}\label{thm:modularlattice}
    Let $X$ be the complex of all chains of a modular lattice and 
    let $\mu$ be the uniform distribution over the facets of $X$, i.e., maximal chains of  $\cL$.
    The path complex $(X,\mu)$ is a $1/2$-top link expander iff $\cL$ is typical. Consequently,   the down-up walk on the maximal chains of a typical modular lattice $\cL$ mixes in time $O(d^{3}\log |X(d)|)$.
\end{theorem}


\subsection{Applications to Log-Concave Sequences}\label{sec:introcolor}
\paragraph{Colored (Top-Link) Path Complexes.}
%We generalize the definition of a path complex $(X,\mu)$ as follows:
Given a (top-link) path complex $(X,\mu)$ with types $T_1,\dots, T_d$, for $\{F,G\}\in X(2)$, we write $F<G$ if $F\in T_i,G\in T_j$ and $i<j$. Otherwise we write $G<F$. If $\{F,G\}\notin X(2)$ we say they are incomparable. We also assume $\hat{0}<F<\hat{1}$ for any $F\in X(1)$.

We color elements of $X(1)$ with a strictly order-preserving map.
Let $\phi:X(1)\cup \{\hat{0},\hat{1}\} \to\R_{>0}$ be a  strictly order-preserving map, i.e., $F<G$ implies $\phi(F)<\phi(G)$. We call the triplet $(X,\mu,\phi)$ a colored path complex.

%\textcolor{blue}{(JL: I am pretty sure something is off about the definition of $D$)}

\begin{definition}
    We say a colored top-link path complex $(X,\mu,\phi)$ is a top-link expander if, for any $\tau$ of $\codim(\tau)=2$ where $\tau\cap T_i=\tau\cap T_{i+1}=\varnothing$ for some $i\in [d-1]$ we have 
    $$ A_\tau\preceq D_{\phi,\tau} +\mathbf{ww}^T,$$
    for some real vector $\mathbf{w}$ and  as before $A_\tau$ is the (weighted) adjacency matrix of $G_\tau$, and $D_{\phi,\tau}$ is the diagonal matrix where the $(F,F)$ entry is $\sum_{G: F<G} \frac{\phi(L)-\phi(G)}{\phi(L)-\phi(F)}\mu(\tau\cup\{F,G\})$ for any $F\in T_i$ and the $(G,G)$-entry is $\sum_{F:F<G} \frac{\phi(F)-\phi(K)}{\phi(G)-\phi(K)}\mu(\tau\cup\{F,G\})$. Here $K, L$ are the elements in $\tau$ satisfying $K \prec F$ and $G \prec L$ for all $F \in T_i$ and $G \in T_j$.
\end{definition}
For example, if for $F\in T_i$ we set $\phi(F)=i$, then the top-link expansion of $(X,\mu,\phi)$ is the same as $1/2$-top link expansion of $(X,\mu)$. We call this the trivial coloring.

We prove the following log-concavity theorem for colored top-link path complexes:
\begin{theorem}[Log-Concavity theorem for Colored Top-Link Path Complexes] \label{thm:log-concavity-colored-complex}
    For any connected $d$-dimensional colored top-link path complex $(X,\mu,\phi)$, if it is a top-link expander then the sequence $c_0,c_1,\dots,c_d$ is log-concave, where
    \[
        c_k = \frac{1}{\phi(\hat{1}) - \phi(\hat{0})} \sum_{\tau \in X(d)} \mu(\tau) \cdot \frac{\prod_{i=0}^d (\phi(\tau_{i+1}) - \phi(\tau_i))}{\prod_{i=1}^k (\phi(\tau_i) - \phi(\tau_0)) \prod_{i=k+1}^d (\phi(\tau_{d+1}) - \phi(\tau_i))},
    \]
    where $\tau_0 = \hat{0}$ and $\tau_{d+1} = \hat{1}$.
    %\textcolor{red}{Sh: I like this version, just the first constant coefficient $\frac{1}{\phi(1)-\phi(0)}$ can be dropped.} \textcolor{blue}{JL: The one upside to this term is that it makes $c_k$ homogeneous in $\phi$.}
\end{theorem}
Note that if $\phi$ is the trivial coloring,  the above theorem is trivial; it just corresponds to the log-concavity of the binomial coefficients: namely the log-concavity of the sequence $\binom{d}{0}, \binom{d}{1},\dots,\binom{d}{d}$.


In \cref{sec:coloredpathcomplexes} we give the following applications of the above theorem:
\paragraph{A  proof of the Heron-Rota-Welsh conjecture.} Let $M=([n], {\cal I})$ be a matroid over $[n]$ of rank $d+1$. Recall that a set $F\subseteq [n]$ is a {\bf flat} if $F=\textup{span}(F)$. A {\bf flag} of flats of $M$ is a sequence $F_1\subsetneq F_2\subsetneq \dots\subsetneq F_\ell$. A maximal of flat of flat is a flag of flat of length $d$.
We let $X$ be the simplicial complex of all flag of proper flats of $M$ and $\mu$ be the uniform distribution over facets of $X$, i.e., all maximal flag of flats of $M$. We prove the following lemma.
\begin{lemma}\label{lem:toplinkexpansionmatroid}
    For $\phi(F)=|F|$, the colored path complex $(X,\mu,\phi)$ is a top-link expander.
\end{lemma}
Then, we invoke \cref{thm:log-concavity-colored-complex} to give  prove the Heron-Rota-Walsh conjecture on the log-concavity of the coefficients of the characteristic polynomial of a matroid (see \cref{thm:Heron-Rota-Welsh}). We remark that although this proof is similar to \cite{BL21} in spirit, it is conceptually simpler and more direct. 

\paragraph{A generalization of the Stanley's log-concavity theorem.} Given a Poset $P$ with $d+1$ elements and the corresponding distributive lattice $\cL$ and the path complex $(X,\mu)$ where $\mu$ is the uniform distribution on maximal chains of flats of $\cL$. 
Chan and Pak raised the following conjecture which generalizes Stanley's log-concavity theorem (given by the $|A| = 1$ case).
%we prove the following lemma.

\begin{conjecture}[{\cite[Conj 1.5]{CP22,CP23}}]\label{conj:CP}
    For any $A\subseteq P$, we have
$$ \P[\ell_{\min}(A)=k]^2 \geq \P[\ell_{\min}(A)=k-1]\cdot\P[\ell_{\min}(A)=k+1],$$
where $\ell$ is a u.r. linear extension of $P$ and $\ell_{\min}(A)=\min\{\ell(a): a\in A\}$.
\end{conjecture}

Given $A\subseteq P$, consider the following coloring: Let $\phi_M(F)=\I[A\cap F\neq \varnothing]\cdot M+|F|$. We observe that the conclusion of \cref{thm:log-concavity-colored-complex} for $\phi_M$  implies the above conjecture when $M\to\infty$.

Unfortunately, $(X,\mu,\phi_M)$ is not necessarily a top link expander. Surprisingly, our counter example also gives a counter example to the above conjecture:
\begin{lemma}
    \cref{conj:CP} doesn't necessarily hold for $A\subseteq P$ arbitrary. 
\end{lemma}
\begin{proof}
Consider a Poset with $4$ elements, $b<c<d$ and an incomparable $a$. The conjecture fails for $A=\{a,d\}$ and $k=2$.     
\end{proof}

Furthermore, we show that if we limit the set $A$, we get a top-link expander and we prove the conjecture for such sets. 
\begin{definition}[$P$-consistent sets]
    We say a set $A\subseteq P$ is $P$-consistent if for any triple $a,b,c\in P$ with $b\prec c$ such that $a,c\in A, b\notin A$ we have $a$ is comparable to (at least) one of $b$ and $c$.
\end{definition}
\begin{lemma}\label{lem:toplinkexpansioncolorlattice}
For any function $\phi:P\to \R_{>0}$, and $\phi(F)=\sum_{a\in F} \phi(a)$, the colored path complex $(X,\mu,\phi)$ is a top-link expander.

In addition, for any $A\subseteq P$ that is $P$-consistent,
     and for any $M\in \R_{>0}$, $(X,\mu,\phi_M)$ is a top-link expander where $\phi_M(F)=\I[F\cap A\neq\emptyset]\cdot M+|F|$ 
\end{lemma}
Having this, we invoke \cref{thm:log-concavity-colored-complex} to prove the following theorem:
\begin{theorem} \label{thm:P-consistent-ext-Stanley}
For any $P$-consistent $A\subseteq P$ and any $2\leq k<d$, we have
$$ \P[\ell_{\min}(A)=k]^2 \geq \P[\ell_{\min}(A)=k-1]\cdot\P[\ell_{\min}(A)=k+1],$$
\end{theorem}
We remark that in the special case $A=\{a\}$ for some $a\in P$, the above theorem re-proves Stanley's log-concavity theorem \cite{Sta81}.
