\begin{lemma}\label{lem:muPXY}
    Let $G=(X,Y)$ be a bipartite graph and $P$ be the simple random walk matrix with stationary distribution $\mu$. Let $P_{X\to Y}$ be the sub-matrix of $P$ corresponding to transitions from $X\to Y$ and $P_{Y\to X}$ is defined similarly. Then, $\tilde{\mu}(x)=\frac{\mu(x)}{\sum_{z\in X} \mu(z)}$ for any $x\in X$ is the stationary distribution of $P_{X\to Y} P_{Y\to X}$.
\end{lemma}
\begin{proof} Let $Z=\sum_{z\in X}\mu(x)$.
    We just check the reversibility condition. For any $x,z\in X$ we have
    \begin{align*} \tilde{\mu}(x)(P_{X\to Y}P_{Y\to X})(x,z)  &= \frac{\mu(x)}{Z} \sum_{y\in Y} P(x,y)P(y,z)\\
    &=\frac{1}{Z}\sum_{y\in Y} \mu(y) P(y,x) P(y,z)\\
    &=\frac{1}{Z}\sum_{y\in Y} \mu(z) P(z,y)P(y,x)
    =\tilde{\mu}(z)(P_{X\to Y}P_{Y\to X})(z,x)
    \end{align*}
    where we used reversibility of $P$ twice. 
\end{proof}
