\begin{lemma}[One positive eigenvalue bound]\label{lem:oneposeigval}
    For $A \in \R^{n\times n}$ that is self-adjoint w.r.t. $\langle .,.\rangle_\mu$ and has one positive eigenvalue and for any vector $v \in \R^n$ such that $\langle v,Av\rangle_\mu > 0$, we have  for any $x\in \R^n$,
    $$\langle x,Ax\rangle_\mu \leq \frac{\langle x, Av\rangle^2_\mu}{\langle v,Av\rangle_\mu,}$$
%where we write $A\preceq_\mu B$ to denote $\langle x,Ax\rangle_\mu\leq \langle x,Bx\rangle_\mu$ for all $x$.
\end{lemma}
\begin{proof}
Let $D$ be a diagonal matrix corresponding to $\mu$, i.e., $D(i,i)=\mu_i$. Note that $DA$ is symmetric (as it is self-adjoint w.r.t. ordinary inner product).
    Let $x \in \R^n$ be arbitrary and set $B \in \R^{n \times 2}$ to $B = \begin{bmatrix}v, x \end{bmatrix}$. Then $$B^T DAB = \begin{bmatrix} \langle v,Av\rangle_\mu & \langle v,Ax\rangle_\mu\\ \langle x,Av\rangle_\mu & \langle x,Ax\rangle_\mu\end{bmatrix}$$ is a $2\times 2$ matrix with the first diagonal entry being non-negative so it has at least one non-negative eigenvalue. By Cauchy interlacing \cref{lem:AB}, $BDAB^T$ has at most one positive eigenvalue. Thus, the product of the eigenvalues is non-positive and so the determinant is non-positive meaning $\langle v,Av\rangle_\mu \cdot \langle x,Ax\rangle_\mu - \langle x,Av\rangle_\mu^2 \leq 0.$ Rearranging we obtain lemma's statement. %we get $$\langle x,Ax\rangle_\mu \leq \left\langle x,\left(\frac{(Av)(Av)^T}{\langle v,Av\rangle_\mu}\right)x\right\rangle$$ As $x$ was arbitrary we are done.
\end{proof}
\begin{lemma}[Eigenvalues of Bipartite graphs]\label{lem:eigenvaluebipartite}
Let $G=(X,Y)$ be a (weighted) bipartite graph, $A\in\R^{(X+Y)\times (X+Y)}$ be the adjacency matrix of $G$, $P$ be the transition probability matrix of the simple random walk on $G$, and $D$ be the diagonal matrix of vertex degrees, i.e., $P=D^{-1}A$. Let $S, \bar{S}\in \R^{(X+Y)\times (X+Y)}$ be diagonal matrices such that $S(x,x)=s_X, S(y,y)=s_Y$ for all $x\in X, y\in Y$ and $\bar{S} = \sqrt{s_Xs_Y} \cdot I_{X+Y}$. Then the following are equivalent:
\begin{enumerate}
    \item $D^{-1/2} A D^{-1/2}\preceq S+vv^T$ for some vector $v\in \R^{X+Y}$,
    \item $D^{-1/2} A D^{-1/2}\preceq \bar{S}+ww^T$ for some vector $w \in \R^{X+Y}$,
    \item $\lambda_2(P) \leq \sqrt{s_X s_Y}$,
    \item $\lambda_2(P-S) \leq 0$.
\end{enumerate}
\end{lemma}
\begin{proof}
$(1) \to (2)$: Let $Z\in \R^{(X+Y)\times (X+Y)}$ be a diagonal matrix with $Z(x,x)=z_X$ and $Z(y,y)=z_Y$ where $z_X,z_Y\geq 0$ and $z_X\cdot z_Y=1$. Assuming the first condition, we have
$$ D^{-1/2}AD^{-1/2} = Z(D^{-1/2} A D^{-1/2})Z %\underset{Z\succeq 0} 
    \preceq ZSZ + vv^T,$$
for some $v\in \R^{X+Y}$.
The first identity uses that $D^{-1/2}AD^{-1/2}$ has only two non-zero blocks corresponding to transitions from $X\to Y, Y\to X$ and that $z_X\cdot z_Y=1$.
Taking $z_X=\sqrt[4]{s_Y/s_X}, z_Y=1/z_X$, we get that $ZSZ=\sqrt{s_X s_Y}I = \bar{S}$. 


$(2) \to (1)$: The same proof as for $(1) \to (2)$ works, but instead we take $z_X =\sqrt[4]{s_X/s_Y}$ and $z_Y=1/z_X$.

$(2)\to (3)$: By \cref{lem:AB}, $$\lambda_2(P)=\lambda_2(D^{-1}A)=\lambda_2(D^{-1/2}AD^{-1/2}) \leq \lambda_1(\bar{S}) = \sqrt{s_Xs_Y}.$$ 

$(1)\to (4)$: By \cref{lem:AB}, 
$$ \lambda_2(P-S)=\lambda_2(D^{-1}A-S) = \lambda_2(D^{-1/2}AD^{-1/2}-S)\leq 0.$$

$(3)\to (2)$: First, $\lambda_2(P- \bar{S})=\lambda_2(D^{-1/2}AD^{-1/2} - \bar{S}) \leq 0$, so $P-\bar{S}$ has at most one positive eigenvalue. Thus $D^{-1/2}AD^{-1/2} - \bar{S} \preceq ww^T$ where $w$ is the first eigenvector of $D^{-1/2}AD^{-1/2} - \bar{S}$. $(4)\to (1)$ can be shown similarly. 
\end{proof}




\subsection{Basic Properties of (Homogeneous) Polynomials}
A polynomial $p\in \R[t_1,\dots,t_n]$ is $d$-homogeneous, if for any $\lambda\in \R$,
$$ p(\lambda t_1,\dots,\lambda t_n)=\lambda^d p(t_1,\dots,t_n).$$

\begin{definition}[Irreducible Matrices]A matrix $A \in \R^{n\times n}$  is called {\bf irreducible} if for all distinct $i,j\in [n]$ there is a sequence $i = i_0,i_1,i_2,\dots,i_\ell = j$ such that $i_{k-1} \neq  i_k$ for all $1 \leq k \leq \ell$, and $A(i_0,i_1)\cdot A(i_1,i_2)\dots A(i_{\ell-1},i_\ell) \neq 0$.
\end{definition}


For a vector $v\in \R^n$, we write
$$ \nabla_{\bm{v}} p(\bm{t}) :=\sum_{i=1}^n v_i \cdot \partial_{t_i}p(\bm{t}).$$

\begin{lemma}[Euler's formula] \label{lem:Eulers-formula}
    If $p \in \R[t_1,\ldots,t_n]$ is a $d$-homogeneous polynomial, then we have that 
    $$d \cdot p(\bm{t}) = \sum_{i=1}^n t_i \cdot \partial_{t_i} p(\bm{t}).$$
\end{lemma}


\begin{lemma}[Chain rule] \label{lem:chain-rule}
    If $f \in \R[t_1,\ldots,t_n]$ is a polynomial, $L: \R^m \to \R^n$ is a linear map, and $\bm{v} \in \R^m$ then
    \[
        \nabla_{\bm{v}}[f(L(\bm{t}))] = [\nabla_{L(\bm{v})}f](L(\bm{t})).
    \]
\end{lemma}
\begin{proof}
    Considering $L$ as an $n \times m$ matrix, let $\ell_{ij}$ be the entries of $L$. By the chain rule for multivariate functions, we have
    \[
        \partial_{t_j}[f(L(\bm{t}))] = \partial_{t_j}[f(L(\bm{t})_1, L(\bm{t})_2, \ldots, L(\bm{t})_n)] = \sum_{i=1}^n \ell_{ij} [\partial_{t_i} f](L(\bm{t})) = [\nabla_{L(\bm{e}_j)} f](L(\bm{t})).
    \]
    Therefore,
    \[
