    \]
    as desired.
\end{proof}


\begin{lemma}[Lem.~3.2 of \cite{BL21}] \label{lem:Euler-expression}
    Suppose $p \in \R[t_1,\ldots,t_n]$ is a $d$-homogeneous polynomial and
    \[
        d \cdot p(\bm{t}) = \sum_{i=1}^n t_i \cdot Q_i(\bm{t})
    \]
    for some $(d-1)$-homogeneous polynomials $Q_1,\ldots,Q_n$. If $\partial_{t_i} Q_j(\bm{t}) = \partial_{t_j} Q_i(\bm{t})$ for all $i,j$, then $Q_i = \partial_{t_i} p(\bm{t})$ for all $i$.
\end{lemma}


\subsection{Log-concave Polynomials}

\begin{definition}[$\cC$-Lorentzian polynomials; Defn. 2.1 of \cite{BL23}] \label{def:C-Lorentzian}
    Let $p \in \R[t_1,\ldots,t_n]$ be a $d$-homogeneous polynomial for $d \geq 2$, and let $\cC \subset \R^n$ be a non-empty open convex cone. We say that $p$ is \textbf{$\cC$-Lorentzian} if
    \begin{enumerate}
        \item[(P)] $\nabla_{\bm{v}_1} \cdots \nabla_{\bm{v}_d} p(\bm{t}) > 0$ for all $\bm{v}_1,\ldots,\bm{v}_d \in \cC$, and
        \item[(Q)] the Hessian of $\nabla_{\bm{v}_1} \cdots \nabla_{\bm{v}_{d-2}} p(\bm{t})$ has at most one positive eigenvalue for all $\bm{v}_1,\ldots,\bm{v}_{d-2} \in \cC$.
    \end{enumerate}
    Note that (P) implies any Hessian in (Q) also has at least one positive eigenvalue.

    Additionally, any linear form for which (P) holds is defined to be $\cC$-Lorentzian of degree $d=1$, and any positive constant is defined to be $\cC$-Lorentzian of degree $d=0$. %Finally, we consider the zero polynomial to be $\cC$-Lorentzian of every degree $d$.
\end{definition}

