Once we prove our polynomial is $\cC$-Lorentzian, we will use the following theorem part (1) to prove that the path complex $(X,\mu)$ is a local spectral expander, and we will use part (2) to get  our log-concavity statements (see proof of \cref{thm:log-concavity-colored-complex}).

\begin{lemma} \label{lem:main-purpose-lemma}
    Let $p$ be a $d$-homogeneous polynomial on $\R^n$, and let $\cC \subset \R^n$ be a non-empty open convex cone. If $p$ is $\cC$-Lorentzian and $\bm{u},\bm{w},\bm{v}_1,\ldots,\bm{v}_{d-2} \in \overline{\cC}$ (the closure of $\cC$), then:
    \begin{enumerate}
        \item the Hessian of $\nabla_{\bm{v}_1} \cdots \nabla_{\bm{v}_{d-2}} p$ has at most one positive eigenvalue, and
        \item the coefficients of $f(x) = p(\bm{u} \cdot x + \bm{w})$ form an ultra log-concave sequence.
    \end{enumerate}
\end{lemma}
\begin{proof}
    For (1), let $(\bm{v}_1(i),\ldots,\bm{v}_{d-2}(i))_{i=1}^\infty$ be a sequence of vectors in $\cC$ which approach $(\bm{v}_1,\ldots,\bm{v}_{d-2})$. Thus the Hessian of $\nabla_{\bm{v}_1(i)} \cdots \nabla_{\bm{v}_{d-2}(i)} p$ has at most one positive eigenvalue for all $i \geq 1$. Therefore the limit of these Hessian matrices also has at most one positive eigenvalue.

    The statement of (2) follows from Remark 2.4 of \cite{BL23}.
\end{proof}



