\subsection{Markov Chains and Mixing 
Time}
\label{sec:markovmixing}
%Given a $d$-partite path complex $(X,\mu)$ the down-up Markov chain is defined as follows: Given a facet $\sigma=(F_1,\dots,F_d)\in X(d)$, where $F_i\in T_i$ choose $i\in [d]$ uniformly at random, and for any $F\in T_i$ such that $F_{i-1} <F < F_{i+1}$ move to $\sigma'=(F_1,\dots,F_{i-1},F,F_{i+1},\dots,F_d)$ w.p. proprotional to $\mu(\sigma')$. We let $P^\vee_d$ be the transitional probability matrix of this chain.

%We remark that in the special case $(X,\mu)$ is the (uniform) distribution over maximal chains of a distributive lattice $\cL$, the down-up Markov chain is essentially the same as the Karzanov-Khachiyan's studied before \cite{KK91}.

%It is not hard to see (assuming connectivity of $X$) that $\mu$ is the unique stationary distribution of the chain, i.e., $\mu P^\vee_d=\mu$. So, to generate samples from $\mu$, we just need to study its mixing time.

Recall that for a Markov chain with transition probability matrix $P^\vee_d$ and stationary distribution $\mu$ 
the {\bf total variation mixing time} started at a state $\tau$ is defined as follows:
	\[ t_{\tau}(\epsilon)=\min\left\{t\in \Z_{\geqslant 0}: \norm{{P^\vee_d}^t(\tau,\cdot)-\mu}_1 \leqslant \epsilon\right\},\]
 	%where $P^t(\tau,\cdot)$ is the distribution of the chain started at $\tau$ at time $t$.

For a function $f:X(d)\to\R$ let
\begin{equation}\label{eq:var} \Var_\mu(f) :=\E_{\sigma\sim \mu}(f(\sigma)-\E_\mu f)^2 = \langle f,f\rangle_\mu-\langle f,\b1\rangle_\mu^2. 
\end{equation}
be the variance of $f$ w.r.t. $\mu$.

The Poincar\'e constant/spectral gap of $P^\vee_d$ is defined as,
$$ \lambda(P^\vee_d):=\inf_{f:X(d)\to\R} \frac{\cE_{P^\vee_d}(f,f)}{\Var_\mu(f)}.$$
The following is classical:
\begin{theorem}
    For any $\tau\in X(d)$,
    $$ t_\tau(\eps) \leq \frac{\log(\eps^{-1}\cdot \frac{1}{\mu(\tau)})}{\lambda(P^\vee_d)}.$$
\end{theorem}







The following theorem is re-proved multiple times (see e.g., \cite{CLV21}). Here, we include the proof for completeness.
\begin{theorem}\label{thm:eigPemptytoVar}
    Suppose that for a $d$-dimensional path complex $(X,\mu)$ we have $\lambda_2(P_\varnothing)\leq \alpha$ for some $\alpha\geq 0$. Then, for any function $f:X(d)\to\R$, we have
        \begin{equation}\label{eq:totalvargoal1} \Var_\mu(f) \leq \frac{d}{d-1}\cdot \frac{1}{1-\alpha} \cdot \E_{i\sim [d]} \E_{F_i\sim\mu^i} \Var_{\mu_{F_i}}(f) \end{equation}
\end{theorem}
%\textcolor{red}{Sh: We should move this proof to the appendix}
\begin{proof}
   For a function $f:X(d)\to\R$, let $f^1:[d]\times X(1)\to\R$ defined as
$$f^1(i,F) = \E_{\sigma\sim\mu}[f(\sigma) | \sigma_i=F].$$
We also let $\mu^1(i,F):=\frac1{d}\P[\sigma_i=F].$ Note that $\mu^1$ defines a probability distribution as $\sum_{i,F} \mu^1(i,F)=1$.
 \begin{fact}[Law of Total Variance]
    $\Var_\mu(f) = \Var_{\mu^1}(f^1) + \E_{i\sim[d]}\E_{F_i\sim\mu^i} \Var_{\mu_{F_i}}(f) $
 \end{fact}
 Having this, to prove the theorem it is enough to show that 
 \begin{equation}\label{eq:totalvargoal2}
\forall f:X(d)\to \R:\quad     \frac{(d-1)\alpha+1}{d}\cdot \Var_\mu(f) \geq \Var_{\mu^1}(f^1).
 \end{equation}
 In particular, this (together with the law of total variance)  implies that 
 $$\frac{(d-1)\alpha+1}{(d-1)(1-\alpha)}\cdot \E_{i\sim[d]}\E_{F_i\sim\mu^i} \Var_{\mu_{F_i}}(f) \geq \Var_{\mu^1}(f^1) $$
Adding $\E_{i\sim[d]}\E_{F_i\sim\mu^i}\Var_{\mu_{F_i}}(f)$ to both sides proves \eqref{eq:totalvargoal1}.

So, in the rest of the proof we show \eqref{eq:totalvargoal2}.

For any $i\in [d]$ and $F\in F_i$, define a function $\mu_{i,F}: X(d) \to\R$ where 
$$\mu_{i,F}(\sigma)=\begin{cases} \frac{\mu(\sigma)}{\P_\tau[\tau_i=F]} &\text{if } \sigma_i=F\\ 0 &\text{otherwise}\end{cases}.$$ 
Similarly, let $\b1_{i,F} = \I[\sigma_i=F]$.
Then, observe that
%$$ f^1(i,s)=\langle \pi_{i,s},f\rangle $$
%Let $P$ be an operator that $Pf= \sum_{i,s} \frac{1_{i,s}}{n\P{\sigma_i=s}}\langle 1_{i,s},f\rangle_{\pi}$
\begin{align*} \Var_{\mu^1}(f^1) &= \sum_{i,F} \mu^1(i,F) f^1(i,F)^2 - \langle f^1,\b1\rangle_{\mu^1}^2\\
&=	f^\top\left(\sum_{i,s} \mu^1(i,s) \mu_{i,s}\mu_{i,s}^\top \right)f - \langle f,\b1\rangle^2_{\mu}=:\langle Pf,f\rangle_\mu - \langle f,\bone\rangle_\mu^2,
\end{align*}
where in the second identity  we used that $$\langle f^1,\b1\rangle_{\mu^1}=\sum_{i,F}\frac1d \P[\sigma_i=F]\cdot \E_{\sigma\sim\mu}[f(\sigma)|\sigma_i=F]=\E_{\sigma\sim\mu]}[f(\sigma)]=\langle f,\b1\rangle_\mu.$$ 
Furthermore, the matrix  $P$ on the RHS is defined as $P:=\sum_{i,F} \frac1d \b1_{i,F}\mu_{i,F}^\top$. Note that $P$ is a stochastic matrix. 
Therefore, by \eqref{eq:var} we have
\begin{align*}
\max_f \frac{\Var_{\mu^1}(f^1)}{\Var(f)} = \max_f \frac{\langle Pf,f\rangle_\mu - \langle f,\b1\rangle_\mu^2}{\langle f,f\rangle_\mu - \langle f,\b1\rangle_\mu^2}	=\lambda_2(P)
\end{align*}
The second identity uses the Rayleigh quotient and that $P$ is stochastic and self-adjoint w.r.t. $\mu(.)$. (so its first eigenvalue is 1).
So, to prove \eqref{eq:totalvargoal2} it is enough to show that $\lambda_2(P)\leq \frac{(d-1)\alpha+1}{d}$.
The observation is that $P$ is a low-rank matrix. In particular, let $U$ be the matrix with columns $\frac1d \b1_{i,F}$ and $R$ be the matrix with rows $\mu_{i,F}$ (for $i\in [d]$). Then, $P=UR$. But, by \cref{lem:AB}, $\lambda_2(P)=\lambda_2(UR)=\max\{0,\lambda_2(RU)\}$.
First, notice $RU\in \R^{X(1)\times X(1)}$. In particular, for $i,j\in [d]$ and $F\in T_i,G\in T_j$, 
\begin{align*} RU(F,G) &= \frac1d \sum_\sigma \frac{\mu(\sigma)}{\P_{\sigma\sim\mu}[\sigma_i=F]} \I[\sigma_i=F,\sigma_j=G] \\
&= \frac{\P[\sigma_i=F,\sigma_j=G]}{d\cdot \P[\sigma_i=F]} = \frac{1}{d}\cdot \P_{\sigma\sim\mu}[\sigma_j=G | \sigma_i=F]
\end{align*}
But this is exactly the (off-diagonal) entries of the simple random walk matrix on the link of the empty set (up to a normalization). Note that $RU(F,F)=1/d$ for any $F\in X(1)$, and thus $RU=\frac{d-1}{d} P_\varnothing + \frac{1}{d} I$. Therefore, $$\lambda_2(P)=\lambda_2(UR)\leq \max\{0,\lambda_2(RU)\}\leq \max\left\{0,\frac{d-1}{d}\lambda_2(P_\varnothing)+\frac{1}{d}\right\}\leq \frac{(d-1)\alpha+1}{d}$$
as desired.
\end{proof}

We end this section by the following factorization of variance lemma for independent distribution (See \cite[Lemma 4.1]{Cap22}  for a proof).
\begin{lemma}[Factorization of Variance]\label{lem:varfactorization}Let $\nu_1, \nu_2$ be probability measures on (finite) state spaces $A_1,A_2$ respectively. Let
     $\mu=\nu_1 \times \nu_2$ be the  product distribution on $A_1 \otimes A_2$ defined as $\mu(a_1,a_2)=\nu_1(a_1)\cdot \nu_2(a_2)$ for $a_1\in A_1,a_2\in A_2$.
     For a function $f:A_1\times A_2$ and $a_1\in A_1$, let $f^{a_1}(.)=f(a_1,.)$ and $f^{a_2}=f(.,a_2)$. Then, for any function $f:A_1 \otimes A_2\to\R$ we have
    $$ \Var_\mu(f) \leq \E_{a_1\sim \nu_1}\Var(f^{a_1}) +  \E_{a_2\sim \nu_2}\Var(f^{a_2}).$$
\end{lemma}
%\href{http://www.mat.uniroma3.it/users/caputo/entropy.pdf}this Lemma 4.1 for a proof.


\section{Local-to-Global Theorems for Path Partite Complexes}\label{sec:localtoglobalpath}
In this section we prove the following theorem.
\begin{theorem}\label{thm:localtoglobal}
    Given a $d$-dimensional $d$-partite path complex $(X,\mu)$ that is an $\alpha$-local spectral expander for some $\alpha\leq 1/2$. %Suppose that for $X$ (and any of partite path links of $X$ \textcolor{blue}{(JL: do you mean the links?)}) \textcolor{red}{Sh:Not just links, the links which form a path complex} we have the following: For any function $f:X(d)\to \R$,
    Then, the spectral gap of the down-up walk is at least $\frac{4}{d(d+1)^2}$. % where $\gamma \geq 3$ such that $\gamma\geq \frac{2}{1-\alpha}(1-2^{-\gamma})$.
\end{theorem}
Before proving this theorem we use it to prove \cref{thm:mainalg}.
\begin{proof}[Proof of \cref{thm:mainalg}]
If the path complex $(X,\mu)$ is a $1/2$-top-link expander then by \cref{thm:main}, $X$ is a $1/2$-local spectral expander. Therefore, by the above theorem the Poincar\'e constant of the down-up walk is at least $\frac{4}{d(d+1)^2}$%\geq \frac{1}{d^{4.447}}.$ 
 as desired.
\end{proof}
%{\color{Sepia}
 Given a function $f:X(d)\to \R$, we prove the following inequality
    \begin{equation}\label{eq:localtoglobal1} \Var_\mu(f) \leq \sum_{i\in[d]} i\cdot (d+1-i)\E_{F_1,\dots,F_{i-1},F_{i+1},\dots,F_d\sim \mu^{-i}} \Var_{\mu_{F_1,\dots,F_{i-1},F_{i+1},\dots,F_d}}(f)
    \end{equation}
