    &+\E_{j\in i+[d-i]} (j-i)\cdot (d+1-j)\E_{F_1,\dots,F_{j-1},F_{j+1},\dots,F_d} \Var_{\mu_{F_1,\dots,F_{j-1},F_{j+1},\dots,F_d}}(f)\Big)%\\
