\begin{definition}[Commutative $\pi$ maps] \label{def:pi-maps}
    Let $\bm\pi = \{\pi_{\sigma+\tau}: \R^{X_\sigma(1)} \to \R^{X_{\sigma \cup \tau}(1)}\}_{\sigma \in X,\tau \in X_\sigma}$ be a family of linear maps having the following property:
    \[
        \text{$\pi_{\sigma+\tau}(\bm{t})_H = t_H - L\big((t_F)_{F \in \tau}\big)$, for all  $H \in X_{\sigma \cup \tau}(1)$, where $L = L_{\sigma,\tau,H}$ is some linear functional.}
    \]
    We will also use the shorthands $\pi_{\sigma+F} := \pi_{\sigma+\{F\}}$ and $\pi_\sigma := \pi_{\varnothing+\sigma}$.

    We say that $\bm\pi$ is \textbf{commutative} if for all $\sigma \in X$, $\tau \in X_\sigma$, $\omega \in X_{\sigma \cup \tau}$, we have:
    \[
        \text{$\pi_{\sigma+(\tau \cup \omega)}(\bm{t}) = \pi_{(\sigma \cup \tau) + \omega}(\pi_{\sigma+\tau}(\bm{t}))$.}
    \]
    % \begin{enumerate}
    %     % \item $\pi_{\sigma+\tau}(\bm{t})$ only depends on $t_F$ for $F \in \tau \cup X_{\sigma \cup \tau}(1)$,
    %     % \item $\pi_{\sigma+\tau}(\bm{t})$ is the identity map when restricted to $\R^{X_{\sigma \cup \tau}(1)} \subset \R^{X_\sigma(1)}$, and
    %     \item $\pi_{\sigma+\tau}(\bm{t})_H = t_H - L\big((t_F)_{F \in \tau}\big)$ for all $H \in X_{\sigma \cup \tau}(1)$, where $L = L_{\sigma,\tau,H}$ is some linear map, and
    %     \item $\pi_{\sigma+(\tau \cup \omega)}(\bm{t}) = \pi_{(\sigma \cup \tau) + \omega}(\pi_{\sigma+\tau}(\bm{t}))$.
    % \end{enumerate}

\end{definition}

For the rest of this section, we fix a commutative family of linear maps $\bm\pi = \{\pi_{\sigma+\tau}\}_{\sigma \in X,\tau \in X_\sigma}$.

\begin{definition}[Polynomials associated to $X$] \label{def:polys-X}
    We inductively define a family of polynomials $p_\sigma(\bm{t})$ on $\R^{X_\sigma(1)}$ of degree $d-|\sigma|$ associated to every $\sigma \in X$. If $\sigma$ is a facet of $X$ (so that $|\sigma| = d$) we define $p_\sigma(\bm{t}) = \mu(\sigma)$, and if $|\sigma| < d$ we define $p_\sigma(\bm{t})$ via
    \[
        (d-|\sigma|) \cdot p_\sigma(\bm{t}) = \sum_{F \in X_\sigma(1)} t_F \cdot p_{\sigma \cup \{F\}}(\pi_{\sigma+F}(\bm{t})).
    \]
    In particular, if $|\sigma| = d-1$ then $p_\sigma$ is the linear form given by
    \begin{equation}\label{eq:linearpcase}
        p_\sigma(\bm{t}) = \sum_{F \in X_\sigma(1)} t_F \cdot \mu(\sigma \cup \{F\}).
    \end{equation}
\end{definition}
\noindent See \cref{sec:coloredpathcomplexes} for examples of $\bm\pi$ maps and the associated polynomials.

We now prove that the definition of $p_\sigma(\bm{t})$ is precisely what one would obtain from Euler's formula for homogeneous polynomials (\cref{lem:Eulers-formula}) by showing that the partial derivatives of $p_\sigma(\bm{t})$ have a nice description.

\begin{lemma}[cf. Lem.~3.3 of \cite{BL21}] \label{lem:derivs-expression}
    Given $\sigma \in X$ and $F \in X_\sigma(1)$, we have
    \[
        \partial_{t_F} p_\sigma(\bm{t}) = p_{\sigma \cup \{F\}}(\pi_{\sigma+F}(\bm{t})).
    \]
    Further, for $F,G \in X_\sigma(1)$ with $F \neq G$, we have
    \[
        \partial_{t_G} \partial_{t_F} p_\sigma(\bm{t}) = \begin{cases}
            p_{\sigma \cup \{F,G\}}(\pi_{\sigma+\{F,G\}}(\bm{t})), & \{F,G\} \in X_\sigma(2) \\
            0, & \text{otherwise}.
        \end{cases}
    \]
\end{lemma}
\begin{proof}
    We prove the first statement by induction on $\codim(\sigma)$, noting that the result is clear for $\codim(\sigma) = 1 \iff |\sigma| = d-1$. By \cref{def:polys-X} and \cref{lem:Euler-expression}, we now just need to show that 
    $$\partial_{t_G} p_{\sigma \cup \{F\}}(\pi_{\sigma+F}(\bm{t})) = \partial_{t_F} p_{\sigma \cup \{G\}}(\pi_{\sigma+G}(\bm{t}))$$
     for all $F,G \in X_\sigma(1)$. 

    First, consider the case that $\{F,G\} \not\in X_\sigma(2)$. Then by the definition of the $\pi$ maps, the polynomial $p_{\sigma\cup \{F\}}(\pi_{\sigma+F}(\bm{t}))$ does not depend on $t_G$ (recall that the linear map $\pi_{\sigma+F}$ only depends on $\sigma, F$ and $H\in X_{\sigma\cup\{F\}}(1)$). Similarly, $ p_{\sigma \cup \{G\}}(\pi_{\sigma+G}(\bm{t}))$ does not depend on $t_F$. So, both sides of the above equation are 0 and we are done.

    %note that both expressions are $0$ if $\{F,G\} \not\in X_\sigma(2)$ since $\bm\pi$ hereditary implies $\pi_{\sigma+F}(\bm{t})$ does not depend on $t_G$ and vice versa. 
    Now, suppose $\{F,G\} \in X_\sigma(2)$. Then by induction %the chain rule (\cref{lem:chain-rule}), and the fact that $\bm\pi$ is commutative, we have that
    we have
    \begin{align*}
        \partial_{t_F} p_{\sigma \cup \{G\}}(\pi_{\sigma+G}(\bm{t})) &\underset {\text{\cref{lem:chain-rule}}}{=} \left[\nabla_{\pi_{\sigma+G}(\bm{1}_F)} p_{\sigma \cup \{G\}}\right](\pi_{\sigma+G}(\bm{t})) \\
        &\underset{\text{def. of } \bm\pi}{=}\left[\partial_{t_F} p_{\sigma \cup \{G\}}\right](\pi_{\sigma+G}(\bm{t})) \\
        &\underset{\text{induction}}{=} p_{\sigma \cup \{F,G\}}(\pi_{(\sigma \cup \{G\})+F}(\pi_{\sigma+G}(\bm{t}))) 
        \underset{\text{ commutativity of } \bm\pi}{=} p_{\sigma \cup \{F,G\}}(\pi_{\sigma+\{F,G\}}(\bm{t}))
    \end{align*}
    Similarly, $
        \partial_{t_G} p_{\sigma \cup \{F\}}(\pi_{\sigma+F}(\bm{t}))= p_{\sigma \cup \{F,G\}}(\pi_{\sigma+\{F,G\}}(\bm{t})),$
    and thus they are equal. %$\partial_{t_G} p_{\sigma \cup \{F\}}(\pi_{\sigma+F}(\bm{t})) = \partial_{t_F} p_{\sigma \cup \{G\}}(\pi_{\sigma+G}(\bm{t}))$.

    For the second statement, note that the first statement and the above arguments imply
    \[
        \partial_{t_F} \partial_{t_G} p_\sigma(\bm{t}) = \partial_{t_F} p_{\sigma \cup \{G\}}(\pi_{\sigma+G}(\bm{t})) = p_{\sigma \cup \{F,G\}}(\pi_{\sigma+\{F,G\}}(\bm{t}))
    \]
    whenever $\{F,G\} \in X_\sigma(2)$, and $\partial_{t_F} \partial_{t_G} p_\sigma(\bm{t}) = 0$ otherwise.
\end{proof}

