We now construct a family of cones for the polynomials defined above.

\begin{definition}[Cone of positive vectors] \label{def:pos-vector}
    Given $\sigma \in X$, we say that a vector $\bm{v} \in \R^{X_\sigma(1)}_{>0}$ is \textbf{$\bm\pi$-positive}  if $\pi_{\sigma+\tau}(\bm{v}) \in \R^{X_{\sigma \cup \tau}(1)}_{>0}$ for all $\tau \in X_\sigma$. We also say $\bm{v}$ is \textbf{$\bm\pi$-non-negative} if the inequalities are not strict.  We further define $\cC_\sigma$ to be the set of all $\bm\pi$-positive vectors. By definition of $\bm\pi$, it follows that $\cC_\sigma$ is an open convex (possibly empty) cone.
\end{definition}

\begin{proposition}[Properties of the cones] \label{prop:cones}
    For all $\sigma \in X$ and $\tau \in X_\sigma$, we have:
    \begin{enumerate}
        \item $\pi_{\sigma+\tau}(\cC_\sigma) \subseteq \cC_{\sigma \cup \tau}$,
        \item $\nabla_{\bm{v}_1} \nabla_{\bm{v}_2} \cdots \nabla_{\bm{v}_{d-|\sigma|}} p_\sigma > 0$ for all $\bm{v}_1,\bm{v}_2,\ldots,\bm{v}_{d-|\sigma|} \in \cC_\sigma$, and
        \item if $\cC_\sigma$ is non-empty, then the closure $\overline{\cC}_\sigma$ is the set of all $\bm\pi$-non-negative vectors in $\R^{X_\sigma(1)}$.
    \end{enumerate}
\end{proposition}
\begin{proof}
    First, $(1)$ is a straightforward computation from the definitions. We next prove $(2)$ by induction on $d-|\sigma|$. Note that if $d-|\sigma| = 0$ (so that $\sigma$ is a facet), we have $p_\sigma = \mu(\sigma) > 0$. For $|\sigma| < d$, let $\bm{u} = \bm{v}_{d-|\sigma|}$. By induction we have
    \begin{align*}
        \nabla_{\bm{v}_1} \cdots \nabla_{\bm{v}_{d-|\sigma|}} p_\sigma &\underset{\text{\cref{lem:derivs-expression}}}{=} \nabla_{\bm{v}_1} \cdots \nabla_{\bm{v}_{d-|\sigma|-1}} \sum_{F \in X_\sigma(1)} u_F \cdot p_{\sigma \cup \{F\}}(\pi_{\sigma+F}(\bm{t})) \\
            &= \sum_{F \in X_\sigma(1)} u_F \cdot \nabla_{\bm{v}_1} \cdots \nabla_{\bm{v}_{d-|\sigma|-1}} p_{\sigma \cup \{F\}}(\pi_{\sigma+F}(\bm{t})) \\
            &\underset{\text{\cref{lem:chain-rule}}}{=} \sum_{F \in X_\sigma(1)} u_F \cdot \left[\nabla_{\pi_{\sigma+F}(\bm{v}_1)} \cdots \nabla_{\pi_{\sigma+F}(\bm{v}_{d-|\sigma|-1})} p_{\sigma \cup \{F\}}\right](\pi_{\sigma+F}(\bm{t})) \\
            &\underset{\text{induction}}{>} 0
    \end{align*}
    where in the last inequality we used that for all $1\leq i\leq d-|\sigma|-1$, the vector $\pi_{\sigma+F}(\bm{v}_i)$ is in $\cC_{\sigma \cup \{F\}}$ by $(1)$ and that $\bm{v}_i\in \cC_{\sigma}$.

    %, and $(2)$ follows from $(1)$, the chain rule (\cref{lem:chain-rule}), and \cref{lem:derivs-expression}. 
    For $(3)$, note that if $\bm{u}$ is $\bm\pi$-non-negative and $\bm{v} \in \cC_\sigma$, then $\bm{u} + \epsilon \cdot \bm{v} \in \cC_\sigma$ for all $\epsilon > 0$.
\end{proof}

With the polynomials and associated cones defined, we can now state the main result of this section. It is a standard type of result in the Lorentzian polynomials literature, which says that a connectivity condition along with Lorentzianness of the quadratic $p_\sigma(\bm{t})$, for $\sigma\in X$ of co-dimension 2, implies all $p_\sigma(\bm{t})$ are Lorentzian. This result follows from the same proof as \cite[Thm. 3.8]{BL23}. First we need a lemma.

\begin{lemma} \label{lem:induct-Lorentzian}
    Fix $\sigma \in X$ and $\tau \in X_\sigma$. If $p_{\sigma \cup \tau}(\bm{t})$ is $\cC_{\sigma \cup \tau}$-Lorentzian, then $p_{\sigma \cup \tau}(\pi_{\sigma+\tau}(\bm{t}))$ is $\cC_\sigma$-Lorentzian.
\end{lemma}
\begin{proof}
    For any $\bm{v}_1,\ldots,\bm{v}_k \in \cC_\sigma$, the chain rule (\cref{lem:chain-rule}) implies
    \[
        \nabla_{\bm{v}_1} \cdots \nabla_{\bm{v}_k} p_{\sigma\cup\tau}(\pi_{\sigma+\tau}(\bm{t})) = \left[\nabla_{\pi_{\sigma+\tau}(\bm{v}_1)} \cdots \nabla_{\pi_{\sigma+\tau}(\bm{v}_k)} p_{\sigma\cup\tau}\right](\pi_{\sigma+\tau}(\bm{t})).
    \]
    We now use this to prove (P) and (Q) in \cref{def:C-Lorentzian}. Let $d$ be the homogeneous degree of $p_{\sigma \cup \tau}(\bm{t})$. Setting $k=d$, since $\pi_{\sigma+\tau}(\bm{v}_i) \in \cC_{\sigma\cup\tau}$ for all $i$ by \cref{prop:cones} (1), the fact that $p$ is $\cC_{\sigma\cup\tau}$-Lorentzian implies
    \[
        \left[\nabla_{\pi_{\sigma+\tau}(\bm{v}_1)} \cdots \nabla_{\pi_{\sigma+\tau}(\bm{v}_d)} p_{\sigma\cup\tau}\right](\pi_{\sigma+\tau}(\bm{t})) > 0.
    \]
    Thus (P) is satisfied. Setting $k=d-2$, since $\pi_{\sigma+\tau}(\bm{v}_i) \in \cC_{\sigma\cup\tau}$ for all $i$, the fact that $p$ is $\cC_{\sigma\cup\tau}$-Lorentzian implies the Hessian of
    \[
        \nabla_{\pi_{\sigma+\tau}(\bm{v}_1)} \cdots \nabla_{\pi_{\sigma+\tau}(\bm{v}_{d-2})} p_{\sigma\cup\tau}(\bm{t})
    \]
    has at exactly one positive eigenvalue. Denote this Hessian by $H$. Now since $\pi_{\sigma+\tau}$ is a linear map, the Hessian of $\left[\nabla_{\pi_{\sigma+\tau}(\bm{v}_1)} \cdots \nabla_{\pi_{\sigma+\tau}(\bm{v}_{d-2})} p_{\sigma\cup\tau}\right](\pi_{\sigma+\tau}(\bm{t}))$ is equal to $M^\top H M$, where $M$ is the matrix associated to $\pi$ (by \cref{lem:chain-rule}). Thus by \cref{lem:AB}, the Hessian of $\left[\nabla_{\pi_{\sigma+\tau}(\bm{v}_1)} \cdots \nabla_{\pi_{\sigma+\tau}(\bm{v}_{d-2})} p_{\sigma\cup\tau}\right](\pi_{\sigma+\tau}(\bm{t}))$ has at most one positive eigenvalue. Thus (Q) is satisfied, and therefore $p_{\sigma\cup\tau}(\pi_{\sigma+\tau}(\bm{t}))$ is $\cC_\sigma$-Lorentzian.
\end{proof}

\begin{theorem}[Connected + Quadratics $\implies$ Lorentzian] \label{thm:conn+quad=Lor}
    Suppose $(X,\mu)$ is a $d$-dimensional connected simplicial complex and $\cC_\varnothing$ is non-empty. If the Hessian of $p_\sigma$ has at most one positive eigenvalue for all $\sigma \in X(d-2)$\footnote{Note that $p_\sigma$ is a quadratic, so $\nabla^2 p_\sigma$ is just a matrix}, then $p_\sigma$ is $\cC_\sigma$-Lorentzian for all $\sigma \in X$.
\end{theorem}
\begin{proof}
    Let $\sigma\in X$. First note that by \cref{prop:cones} (2), the (P) condition of the definition of $\cC_\sigma$-Lorentzian (\cref{def:C-Lorentzian}) is satisfied, and thus we only need to prove the (Q) condition.

    Note that if co-dimension of $\sigma$ is 1 then the polynomial is linear, and if it is 2 then the result follows immediately from the Hessian condition of the theorem.

    Now we assume $\codim(\sigma)>2$, and we prove the result by induction.
    We will apply \cref{thm:Lor-from-derivs}. First note that condition (1) of \cref{thm:Lor-from-derivs} is already verified. Next, we check condition (3). By \cref{lem:derivs-expression} we have
    \[
        \partial_{t_F} p_\sigma(\bm{t}) = p_{\sigma \cup \{F\}}(\pi_{\sigma+F}(\bm{t})),
    \]
    and by induction $p_{\sigma \cup \{F\}}$ is $\cC_{\sigma \cup \{F\}}$-Lorentzian. Thus $\partial_{t_F} p_\sigma(\bm{t}) = p_{\sigma \cup \{F\}}(\pi_{\sigma+F}(\bm{t}))$ is $\cC_\sigma$-Lorentzian by \cref{lem:induct-Lorentzian}. Thus we have verified condition (3) of \cref{thm:Lor-from-derivs}.

