Combining the following lemma with the above theorem, to check that our polynomials $p_\sigma$ are $\cC$-Lorentzian it is enough to check that the matrix $A+D$ for a link of co-dimension 2 has at most one positive eigenvalue. 
\begin{lemma} \label{lem:quadratic-entries}
    Fix $\sigma \in X(d-2)$, and let $A$ be the adjacency matrix of the $1$-skeleton of $X_\sigma$, weighted according to $\mu$. That is, for all $\{F,G\} \in X_\sigma(2)$ the entry $A(F,G)$ is $\mu(\sigma \cup \{F,G\})$. Further, let $D$ be the diagonal matrix with entries given by
    \[
        D(F,F) = \sum_{G \in X_{\sigma \cup \{F\}}(1)} A(F,G) \cdot \partial_{t_F} \pi_{\sigma+F}(\bm{t})_G = \nabla\left[A \cdot \pi_{\sigma+F}(\bm{t})\right]_F.
    \]
    Then the Hessian of $p_\sigma$ is $A+D$.
\end{lemma}
\begin{proof}
    % By \cref{lem:derivs-expression} we have
    % \[
    %     \partial_{t_F} p_\sigma(\bm{t}) = p_{\sigma \cup \{F\}}(\pi_{\sigma+F}(\bm{t})).
    % \]
    % If $\{F,G\} \not\in X_\sigma(2)$, then $\partial_{t_G} \partial_{t_F} p_\sigma(\bm{t}) = 0$ since $p_{\sigma \cup \{F\}}(\pi_{\sigma+F}(\bm{t}))$ does not depend on $t_G$. % (recall that the linear map $\pi_{\sigma+F}$ only depends on $\sigma, F$ and $H\in X_{\sigma\cup\{F\}}(1)$). 
    % Otherwise $\{F,G\} \in X_\sigma(2)$, and we have
    % \[
    %     \partial_{t_G} p_{\sigma \cup \{F\}(1)}(\pi_{\sigma+F}(\bm{t})) \underset{\text{\cref{lem:derivs-expression}}}{=} p_{\sigma \cup \{F,G\}}(\pi_{(\sigma \cup \{F\}) + G}(\pi_{\sigma+F}(\bm{t}))) = \mu(\sigma \cup \{F,G\}).
    % \]
    By \cref{lem:derivs-expression} we have
    \[
        \partial_{t_G} \partial_{t_F} p_\sigma(\bm{t}) = \begin{cases}
            p_{\sigma \cup \{F,G\}}(\pi_{\sigma+\{F,G\}}(\bm{t})), & \{F,G\} \in X_\sigma(2) \\
            0, & \text{otherwise},
        \end{cases}
    \]
    and if $\{F,G\} \in X_\sigma(2)$, then we further have
    \[
        \partial_{t_G} \partial_{t_F} p_\sigma(\bm{t}) = p_{\sigma \cup \{F,G\}}(\pi_{\sigma+\{F,G\}}(\bm{t})) = \mu(\sigma \cup \{F,G\}).
    \]
    Thus the off-diagonal entries of the Hessian of $p_\sigma$ and of $A$ coincide. For the diagonal entries, we have
    \begin{align*}
        \partial_{t_F}^2 p_\sigma(\bm{t}) = \partial_{t_F} p_{\sigma \cup \{F\}}(\pi_{\sigma+F}(\bm{t})) &\underset{\text{\cref{lem:chain-rule}}}{=} \left[\nabla_{\pi_{\sigma+F}(\bm{1}_F)} p_{\sigma\cup\{F\}}\right](\pi_{\sigma+F}(\bm{t})) \\
        &\underset{\text{linearity of $\pi_{\sigma+F}$}, \eqref{eq:linearpcase}}{=} \left[\sum_{G \in X_{\sigma \cup \{F\}}(1)} (\partial_{t_F} \pi_{\sigma+F}(\bm{t})_G) \cdot \mu(\sigma\cup\{F,G\})\right](\pi_{\sigma+F}(\bm{t})) \\
        &= \sum_{G \in X_{\sigma \cup \{F\}}(1)} (\partial_{t_F} \pi_{\sigma+F}(\bm{t})_G) \cdot A(F,G).
    \end{align*}
\end{proof}


\section{Conic Lorentzian Polynomials for Top-Link Path Complexes}
\label{sec:lorentzianpolynomials-path}

In the rest of the paper we mainly focus on $d$-dimensional top-link path complexes $(X,\mu)$ with parts $T_1,\ldots,T_d$ and we employ \cref{thm:conn+quad=Lor} to study their properties. 
In this section, we give a method for determining a family of $\pi$ maps with the commutativity property.
Armed with such a family of $\pi$ maps, we invoke \cref{thm:conn+quad=Lor} to conclude that $p_\varnothing$ is $\cC_\varnothing$-Lorentzian.
We will conclude the section by showing that this implies a log-concavity inequality associated to $X$ and an eigenvalue bound on the induced weighted subgraph $G_{k,k+1}$ of the 1-skeleton of $X_\varnothing$ for all $1\leq k\leq d-1$.
%and we also do some explicit computations which yield general eigenvalue bounds and log-concavity statements. From now on, we will assume that $X$ is a path complex.



As alluded to in the introduction, one of our main examples of a top-link path  complex is the set of chains of a lattice, and thus we will use some suggestive notation. Specifically, fix $\{K,L\} \in X(2)$ with $K \in T_i$ and $L \in T_j$ for $i < j$. Since $i < j$ we write $K < L$, and if $j = i+1$ then we write $K \prec L$. We also write $(K,L)$ for %\textcolor{red}{Sh: Added below}
$$ (K,L):=\{F\in X(1): K<F<L\}.$$
%the set $X_{\{K,L\}}(1) \cap (T_{i+1} \cup \cdots \cup T_{j-1})$, 
and we write $[K,L]$ for the set $(K,L) \cup \{K,L\}$.

% Let $\cL$ be a ranked bounded lattice with minimal and maximal elements $\hat{0}$ and $\hat{1}$ respectively. Given $K,L \in \cL$ with $K \leq L$, we denote by $[K,L]$ and $(K,L)$ the closed and open intervals in $\cL$, respectively. We further denote the rank difference between $K$ and $L$ as $r_K^L$ and define $d_K^L := r_K^L-1$. Whenever $K$ is covered by $L$, we denote this by $K \prec L$. As described in Fact, the chains in $\cL$ are the faces of a pure partite path complex $X$.

Finally, we abuse notation by defining $T_0 = \{\hat{0}\}$ and $T_{d+1} = \{\hat{1}\}$. The elements $\hat{0}$ and $\hat{1}$ will not actually be a part of any face in $X$, but we will sometimes allow them to replace elements of $X(1)$ in certain contexts. For example, we will denote $(\hat{0},\hat{1}) = X(1)$ and denote $(\hat{0},F)$ to be the set of all $K \in X_{\{F\}}(1)$ such that $K < F$.
% As another example, if $F \in T_k$ then we will denote $r_{\hat{0}}^F = k$ and $r_F^{\hat{1}} = r-k$ as expected. 


\begin{definition} \label{def:alpha-beta}
    Let $\bm\alpha = \{\alpha_K^L: (K,L) \to \R_{\geq 0}\}_{K<L \text{ in } X(1)}$ and $\bm\beta = \{\beta_K^L: (K,L) \to \R_{\geq 0}\}_{K<L \text{ in } X(1)}$ be families of maps, where we allow $K = \hat{0}$ and/or $L = \hat{1}$. We say that these maps are \textbf{commutative} if for all $K < F < G < L$ in $X(1)$, we have:
    \begin{enumerate}
        \item $\alpha_K^L(F) = \alpha_K^G(F) \cdot \alpha_K^L(G)$,
        \item $\beta_K^L(G) = \beta_F^L(G) \cdot \beta_K^L(F)$,
        \item $\alpha_F^L(G) = \alpha_K^L(G) - \beta_F^L(G) \cdot \alpha_K^L(F)$,
        \item $\beta_K^G(F) = \beta_K^L(F) - \alpha_K^G(F) \cdot \beta_K^L(G)$.
    \end{enumerate}
    We will sometimes abuse notation and consider $\alpha_K^L$ and $\beta_K^L$ to be vectors in $\R^{X(1)}$ which are defined to be $0$ outside of $(K,L)$. Finally, we will often suppress $\hat{0}$ and/or $\hat{1}$ in the notation; e.g. $\alpha := \alpha_{\hat{0}}^{\hat{1}}$, $\alpha_F := \alpha_F^{\hat{1}}$, $\beta^F := \beta_{\hat{0}}^F$, and so on.
\end{definition}

\begin{proposition} \label{prop:pi-maps-from-alpha-beta}
    Given a commutative family of maps $\bm\alpha$ and $\bm\beta$, we define a family of maps $\bm\pi$ as follows. Given $\sigma = \{F_1,F_2,\ldots,F_{i-1},F_{i+1},\ldots,F_m\} \in X$ and $F_i \in X_\sigma(1)$ such that $F_1 < F_2 < \cdots < F_m$, define
    \begin{equation} \label{eq:pi-def-from-alpha-beta}
        \pi_{\sigma+F_i}(\bm{t})_H = \begin{cases}
            t_H - \alpha_{F_{i-1}}^{F_i}(H) \cdot t_{F_i}, & H \in (F_{i-1},F_i) \\
            t_H - \beta_{F_i}^{F_{i+1}}(H) \cdot t_{F_i}, & H \in (F_i,F_{i+1}) \\
            t_H, & \text{otherwise},
        \end{cases}
    \end{equation}
    where we denote $F_0 = \hat{0}$ and $F_{m+1} = \hat{1}$.
    %The more general maps $\pi_{\sigma+\tau}$ for $\tau \in X_\sigma$ are then defined inductively using the commutativity property of $\bm\pi$ and any ordering of $\tau$.
    More generally, for $\tau = \{G_1,\ldots,G_k\} \in X_\sigma$, we define
    \[
        \pi_{\sigma+\tau} = \pi_{(\sigma\cup\{G_1,\ldots,G_{k-1}\})+G_k} \circ \cdots \circ \pi_{(\sigma\cup\{G_1,G_2\})+G_3} \circ \pi_{(\sigma\cup\{G_1\})+G_2} \circ \pi_{\sigma+G_1}
    \]
    for any ordering of $\tau$. Then $\bm\pi$ is commutative.
\end{proposition}
\begin{proof}
    To show that $\bm\pi$ is commutative, we only need to show that the definition of $\pi_{\sigma+\tau}$ given above is independent of the choice of ordering of $\tau$. We will do this by showing
    \begin{equation} \label{eq:commutativity-proof-condition}
        \pi_{(\sigma \cup F_i) + F_j}(\pi_{\sigma+F_i}(\bm{t})) = \pi_{(\sigma \cup F_j) + F_i}(\pi_{\sigma + F_j}(\bm{t}))
    \end{equation}
    for any $\sigma \in X$ and $\{F_i,F_j\} \in X_\sigma(2)$.

    Fix $\sigma = \{F_1,F_2,\ldots,F_{i-1},F_{i+1},\ldots,F_{j-1},F_{j+1},\ldots,F_m\} \in X$ and $\{F_i,F_j\} \in X_\sigma(2)$ such that $F_k < F_{k+1}$ for all $k$, where $j > i$ and possibly $j = i+1$. Note that \eqref{eq:commutativity-proof-condition} is clear whenever $j > i+1$, since the individual $\pi$ maps $\pi_{\sigma+F_i}(\bm{t})$ and $\pi_{\sigma+F_j}(\bm{t})$ affect disjoint parts of the vector $\bm{t}$.

    For $j = i+1$, we define $K = F_{i-1}$, $F = F_i$, $G = F_{i+1}$, and $L = F_{i+2}$, where $F_0 = \hat{0}$ and $F_{m+1} = \hat{1}$. For $H \not\in (K,L)$, \eqref{eq:commutativity-proof-condition} follows from $\pi_{(\sigma \cup F) + G}(\pi_{\sigma+F}(\bm{t}))_H = t_H = \pi_{(\sigma \cup G) + F}(\pi_{\sigma + G}(\bm{t}))_H$. 

    Case 1: $H \in (K,F)$ we have
    \[
    \begin{split}
        \pi_{(\sigma \cup G)+F}(\pi_{\sigma+G}(\bm{t}))_H &= \pi_{\sigma+G}(\bm{t})_H - \alpha_K^F(H) \cdot \pi_{\sigma+G}(\bm{t})_F \\
            &= \left(t_H - \alpha_K^G(H) \cdot t_G\right) - \alpha_K^F(H) \cdot \left(t_F - \alpha_K^G(F) \cdot t_G\right) \\
            &= \pi_{\sigma+F}(\bm{t})_H - t_G \cdot \left(\alpha_K^G(H) - \alpha_K^F(H) \cdot \alpha_K^G(F)\right)
            \\
            &\underset{\text{(1) of \cref{def:alpha-beta}}}{=} \pi_{\sigma+F}(\bm{t})_H=
            \pi_{(\sigma \cup F) + G}(\pi_{\sigma+F}(\bm{t}))_H.
            %&= \pi_{(\sigma \cup F)+G}(\pi_{\sigma+F}(\bm{t}))_H - t_G \cdot \left(\alpha_K^G(H) - \alpha_K^F(H) \cdot \alpha_K^G(F)\right),
    \end{split}
    \]
    Note that in the last identity we use the fact that $\pi_{(\sigma \cup F) + G}(\bm{s})_H = s_H$ since $H < F < G$. %$\pi_{\sigma+F}(\bm{t})_G=$

    Case 2: $H \in (G,L)$:
    \[
    \begin{split}
        \pi_{(\sigma \cup F)+G}(\pi_{\sigma+F}(\bm{t}))_H &= \pi_{\sigma+F}(\bm{t})_H - \beta_G^L(H) \cdot \pi_{\sigma+F}(\bm{t})_G \\
            &= \left(t_H - \beta_F^L(H) \cdot t_F\right) - \beta_G^L(H) \cdot \left(t_G - \beta_F^L(G) \cdot t_F\right) \\
            &= \pi_{\sigma+G}(\bm{t})_H - t_F \cdot \left(\beta_F^L(H) - \beta_G^L(H) \cdot \beta_F^L(G)\right) \\
            &\underset{\text{(2) of \cref{def:alpha-beta}}}{=} \pi_{\sigma+G}(\bm{t})_H=\pi_{(\sigma \cup G)+F}(\pi_{\sigma+G}(\bm{t}))_H.
            %- t_F \cdot \left(\beta_F^L(H) - \beta_G^L(H) \cdot \beta_F^L(G)\right).
    \end{split}
    \]
    Note that in the last identity we use the fact that $\pi_{(\sigma \cup G) + F}(\bm{s})_H = s_H$ since $F < G < H$.

    Case 3: $H \in (F,G)$:
    \[
    \begin{split}
            \pi_{(\sigma \cup F)+G}(\pi_{\sigma+F}(\bm{t}))_H &= \pi_{\sigma+F}(\bm{t})_H - \alpha_F^G(H) \cdot \pi_{\sigma+F}(\bm{t})_G \\
            &= \left(t_H - \beta_F^L(H) \cdot t_F\right) - \alpha_F^G(H) \cdot \left(t_G - \beta_F^L(G) \cdot t_F\right) \\
            &= t_H - t_F \cdot \left(\beta_F^L(H) - \alpha_F^G(H) \cdot \beta_F^L(G)\right) - t_G \cdot \left(\alpha_F^G(H)\right)
    \end{split}
    \]
    and
    \[
    \begin{split}
        \pi_{(\sigma \cup G)+F}(\pi_{\sigma+G}(\bm{t}))_H &= \pi_{\sigma+G}(\bm{t})_H - \beta_F^G(H) \cdot \pi_{\sigma+G}(\bm{t})_F \\
            &= \left(t_H - \alpha_K^G(H) \cdot t_G\right) - \beta_F^G(H) \cdot \left(t_F - \alpha_K^G(F) \cdot t_G\right) \\
            &= t_H - t_F \cdot \left(\beta_F^G(H)\right) - t_G \cdot \left(\alpha_K^G(H) - \beta_F^G(H) \cdot \alpha_K^G(F)\right).
    \end{split}
    \]
    The coefficient of $t_G$ in the above two equations are the same by (3) of \cref{def:alpha-beta} and the coefficients of $t_F$ are the same by (4) of \cref{def:alpha-beta}.
%    In all cases, the fact that $\pi_{(\sigma \cup F)+G}(\pi_{\sigma+F}(\bm{t}))_H = \pi_{(\sigma \cup G)+F}(\pi_{\sigma+G}(\bm{t}))_H$ follows from the fact that $\bm\alpha$ and $\bm\beta$ are hereditary.
\end{proof}

For the rest of this section,  fix a commutative $\bm\alpha$ and $\bm\beta$, and $\bm\pi$ as defined in \cref{prop:pi-maps-from-alpha-beta}.

\begin{lemma}[Interaction of $\bm\pi$, $\bm\alpha$, $\bm\beta$] \label{lem:pi-alpha-beta-relations}
    Fix $\sigma = \{F_1,F_2,\ldots,F_{i-1},F_{i+1},\ldots,F_m\} \in X$ and $F_i \in X_\sigma(1)$ such that $F_1 < F_2 < \cdots < F_m$, where we denote $F_0 = \hat{0}$ and $F_{m+1} = \hat{1}$. Letting $K = F_{i-1}$, $F = F_i$, and $L = F_{i+1}$ we have
    \[
        \pi_{\sigma+F}\left(\alpha_K^L\right) = \alpha_F^L \qquad \text{and} \qquad \pi_{\sigma+F}\left(\beta_K^L\right) = \beta_K^F,
    \]
    where $\alpha_K^L$ and $\beta_K^L$ are considered to be $0$ outside of $(K,L)$ as discussed in \cref{def:alpha-beta}.
\end{lemma}
\begin{proof}
    For $H \in (K,F)$ we compute
    \[
        \pi_{\sigma+F}(\alpha_K^L)_H = \alpha_K^L(H) - \alpha_K^F(H) \cdot \alpha_K^L(F) \underset{\text{(1) of \cref{def:alpha-beta}}}{=} 0
    \]
    and
    \[
        \pi_{\sigma+F}(\beta_K^L)_H = \beta_K^L(H) - \alpha_K^F(H) \cdot \beta_K^L(F) \underset{\text{(4) of \cref{def:alpha-beta}}}{=} \beta_K^F(H),
    \]
    and for $H \in (F,L)$ we compute
    \[
        \pi_{\sigma+F}(\alpha_K^L)_H = \alpha_K^L(H) - \beta_F^L(H) \cdot \alpha_K^L(F) \underset{\text{(3) of \cref{def:alpha-beta}}}{=} \alpha_F^L(H)
    \]
    and
    \[
        \pi_{\sigma+F}(\beta_K^L)_H = \beta_K^L(H) - \beta_F^L(H) \cdot \beta_K^L(F) \underset{\text{(2) of \cref{def:alpha-beta}}}{=} 0.
    \]
    For $H \not\in (K,L)$ we compute
    \[
        \pi_{\sigma+F}(\alpha_K^L)_H = \alpha_K^L(H) = 0
    \]
    and
    \[
        \pi_{\sigma+F}(\beta_K^L)_H = \beta_K^L(H) = 0
    \]
    since we consider $\alpha_K^L$ and $\beta_K^L$ to be $0$ outside of $(K,L)$.
\end{proof}

\begin{corollary} \label{cor:alpha-beta-in-cone}
    If $\cC_\varnothing$ is non-empty, then the vectors $\alpha,\beta$ are elements of $\overline{\cC}_\varnothing$.
\end{corollary}
\begin{proof}
    By inductively applying \cref{lem:pi-alpha-beta-relations}, we have that $\pi_\sigma(\alpha), \pi_\sigma(\beta) \in \R^{X_\sigma(1)}_{\geq 0}$ for all $\sigma \in X$. Thus $\alpha$ and $\beta$ are $\bm\pi$-non-negative. Therefore $\alpha,\beta \in \overline{\cC}_\varnothing$ by (3) of \cref{prop:cones}.
\end{proof}

