\begin{definition}[Contiguous face]
    We say that $\sigma \in X$ is \textbf{contiguous} if there exist $i \leq j$ such that $\sigma \cap T_k \neq \varnothing$ if and only if $i \leq k \leq j$. Note in particular that $\varnothing$ is not contiguous. In such a case, we also say $\sigma$ is $[i,j]$-contiguous. 
\end{definition}

\begin{definition}[Contiguous link]
We say that $\sigma\in X$ of co-dimension (at least) 2 is \textbf{$[i,j]$-link-contiguous} if every facet $\tau\in X_\sigma$ is $[i,j]$-contiguous. 
\end{definition}

We now prove a version of and \cref{lem:quadratic-entries} applied to top-link path complexes. In particular this shows that to prove a  $p_\varnothing$ corresponding to a connected top-link path complex $(X,\mu)$ is $\cC_\varnothing$-Lorentzian it is enough to check Hessians of the contiguous links of co-dimension 2 have one positive eigenvalue. 

\begin{theorem}\label{thm:quadraticcheck}
    Suppose $(X,\mu)$ is a $d$-dimensional connected top-link path complex and $\cC_\varnothing$ is non-empty. Suppose for any $1 \leq i \leq d-1$ and any $[i,i+1]$-link-contiguous $\sigma\in X(d-2)$ the following holds:

    Let $A$ be the adjacency matrix of the 1-skeleton of $X_\sigma$ weighted according to $\mu$, i.e., $A(F,G)=\mu(\sigma\cup \{F,G\})$ and let $D$ be the diagonal matrix, given by 
    $$ D(H,H)=\begin{cases}-\sum_{G\in X_\sigma(1):H\prec G} \beta_H^{\sigma_{i+2}}(G) \cdot A(H,G) &\text{if } H\in T_i\cap X_\sigma(1)\\ -\sum_{F\in X_\sigma(1): F \prec H} \alpha_{\sigma_{i-1}}^H(F) \cdot A(F,H)&\text{if } H\in T_{i+1}\cap X_\sigma(1),\end{cases} $$
    where $\sigma_0 = \hat{0}$ and $\sigma_{d+1} = \hat{1}$.
    The matrix $A+D$ has at most one positive eigenvalue.
    %the Hessian of $p_\sigma$ has at most one positive eigenvalue for all contiguous $\sigma \in X(d-2)$, then $p_\sigma$ is $\cC_\sigma$-Lorentzian for all $\sigma \in X$.

    Then $p_\sigma$ is $\cC_\sigma$-Lorentzian for all $\sigma \in X$.
\end{theorem}
\begin{proof}
    Fix $1 \leq i \leq d-1$ and any $[i,i+1]$-link-contiguous $\sigma \in X(d-2)$. For any $F \prec G$ in $X_\sigma$, we have
    \[
        \partial_{t_F} \pi_{\sigma+F}(\bm{t})_G \underset{\text{\eqref{eq:pi-def-from-alpha-beta}}}{=} -\beta_F^{\sigma_{i+2}}(G) \qquad \text{and} \qquad \partial_{t_G} \pi_{\sigma+G}(\bm{t})_F \underset{\text{\eqref{eq:pi-def-from-alpha-beta}}}{=} -\alpha_{\sigma_{i-1}}^G(F).
    \]
    Thus by \cref{lem:quadratic-entries}, $A+D$ is equal to the Hessian of $p_\sigma$.

    Now by \cref{thm:conn+quad=Lor}, we only need to check the Hessians of $p_\sigma$ for $\sigma \in X(d-2)$ which are not link-contiguous. Fix such a $\sigma$, and let $i < j$ be such that $\sigma_i = \sigma_j = \varnothing$. Now given $\{F,G\} \in X_\sigma(2)$ such that $F < G$, we compute
    \begin{align*}
        % A(F,G) = \mu(\sigma\cup \{F,G\}) &= \P[\sigma\cup\{F,G\} | \sigma_{i+1}]\cdot \P[\sigma_{i+1}]\\
        % &\underset{\text{cond Indep}}{=}\P[\sigma_1,\dots,\sigma_{i-1},F | \sigma_{i+1}]\cdot \P[\sigma_{i+2},\dots,\sigma_{j-1},G,\sigma_{j+1},\dots,\sigma_d | \sigma_{i+1}]\cdot \P[\sigma_{i+1}]
        A(F,G) = \mu(\sigma\cup \{F,G\}) &= \P[\sigma\cup\{F,G\} | \sigma]\cdot \P[\sigma]\\
        &=\P[F,G | \sigma]\cdot \P[\sigma]\\
        &\underset{\text{cond Indep}}{=}\P[F | \sigma]\cdot \P[G | \sigma]\cdot \P[\sigma]
    \end{align*}
    The last equality uses that $\sigma$ is not link-contiguous which implies $j>i+1$. Now, let $v\in \R^{X_\sigma(1)\cap T_i}, w\in \R^{X_\sigma(1)\cap T_j}$, where $v_F=\P[F | \sigma]$ and $w_G=\P[G | \sigma]\cdot \P[\sigma]$. Then, by the above equation,
    $$ A=\begin{bmatrix} 0 & vw^\top \\ wv^\top & 0 \end{bmatrix}$$
    $A$ is a symmetric rank 2 matrix so it has two non-zero eigenvalues. Further, since it is adjacency matrix of a bipartite graph, \cref{lem:AB} implies it has one positive and one negative eigenvalue. 
    Finally, since all entries of $A$ are non-negative, and the $\bm{\alpha},\bm{\beta}$-vectors are non-negative the $D$-matrix defined in \cref{lem:quadratic-entries} has non-positive entries (in fact one can see $D=0$). Therefore, the Hessian of $p_\sigma$, i.e., $A+D$, has at most one positive eigenvalue.
\end{proof}


In the rest of this section, we prove two consequences of constructing $\cC$-Lorentzian polynomials: Namely we first give an eigenvalue bound on the induced subgraphs of the 1-skeleton of $p_\varnothing$, see \cref{cor:eig-bound-alpha-beta}; and then in \cref{cor:log-concavity-alpha-beta} we prove log-concavity inequalities for some sequences of numbers which we will eventually use in \cref{sec:coloredpathcomplexes} to re-derive Heron-Rota-Welsh conjecture and to prove generalizations of Stanley's theorem. 

\begin{definition} \label{def:mu-alpha-beta}
    We define a function $\mu_{\alpha,\beta}: \{\sigma \in X : \sigma \text{ contiguous}\} \to \R_{\geq 0}$ as follows.
    %If $\sigma \in X$ is not contiguous, then $\mu_{\alpha,\beta}(\sigma) := 0$. Otherwise
    For $[i,j]$-contiguous $\sigma$, we define
    \[ \mu_{\alpha,\beta}(\sigma) := \sum_{\tau\in X(d): \sigma\subseteq \tau}\left[\prod_{k=1}^{i-1} \beta^{\tau_{k+1}}(\tau_k)\right] \cdot \mu(\tau) \cdot \left[\prod_{k=j+1}^d \alpha_{\tau_{k-1}}(\tau_k)\right], \]
    where we recall that $\tau_k$ is defined to be $\tau \cap T_k$.
    % \[
    %     \mu_{\alpha,\beta}(\sigma) = \sum_{F_1,\ldots,F_{i-1},F_{k+m+1},\ldots,F_d} \left[\prod_{k=1}^{i-1} \beta^{F_{k+1}}(F_k)\right] \cdot \mu(\{F_1,\ldots,F_{i-1}\} \cup \sigma \cup \{F_{j+1},\ldots,F_d\}) \cdot \left[\prod_{k=j+1}^d \alpha_{F_{k-1}}(F_k)\right]
    % \]
    % where $F_i=\sigma\cap T_i$ and $F_j=\sigma\cap T_j$.
\end{definition}

\begin{lemma}[General mixed derivatives lemma] \label{lem:general-mixed-derivs-expression}
    % Define a function $\mu_{\alpha,\beta}: X \setminus \{\varnothing\} \to \R_{\geq 0}$ as follows. Given $0 \leq k \leq d-1$ and $\sigma = \{F_{i_1},F_{i_2},\ldots,F_{i_m}\} \in X \setminus \{\varnothing\}$ such that $k+1 = i_1 < i_2 < \cdots < i_m$ and $F_{i_j} \in T_{i_j}$ for all $j$, if $i_j = k+j$ for all $j$ then
    % \[
    %     \mu_{\alpha,\beta}(\sigma) = \sum_{\substack{F_1,\ldots,F_k,F_{k+m+1},\ldots,F_d \\ \cF = \{F_1,\ldots,F_d\} \in X(d)}} \left[\prod_{i=1}^k \beta^{F_{i+1}}(F_i)\right] \cdot \mu(\cF) \cdot \left[\prod_{i=k+m+1}^d \alpha_{F_{i-1}}(F_i)\right]
    % \]
    % and otherwise $f(\sigma) = 0$. Then for any $k$ and $\sigma$ as above, we have that $\nabla_{\beta}^k \nabla_{\alpha}^{d-k-m} \left[p_\sigma(\pi_\sigma(\bm{t}))\right] = f(\sigma)$.
    We have that
    \[
        \nabla_\beta^{i-1} \nabla_\alpha^{d-j} p_\sigma(\pi_\sigma(\bm{t})) = \begin{cases}
            \mu_{\alpha,\beta}(\sigma), & \text{if $\sigma$ is $[i,j]$-contiguous} \\
            0, & \text{otherwise}.
        \end{cases}
    \]
\end{lemma}
\begin{proof}Fix $\sigma\in X$ and $i,j \in [d]$. We compute $\nabla_\beta^{i-1} \nabla_\alpha^{d-j} p_\sigma(\pi_\sigma(\bm{t}))$ by induction on $\codim(\sigma)$.
    Let $a\in [d]$ be the smallest number such that $\sigma_a \neq \varnothing$, and let $b\in [d]$ be the largest number such that $\sigma_b \neq \varnothing$.
    % We prove this by induction on $d-m$.

    First, if $\codim(\sigma) = 0$ then $\sigma$ is a facet of $X$ which implies $a = 1$ and $b=d$, and the result immediately follows since $p_\sigma(\bm{t}) = \mu(\sigma)$.

    For the inductive step, assume that $\codim(\sigma) > 0$. For ease of notation, we denote $K = \sigma_a$ and $L = \sigma_b$. Suppose first that $d-j > 0$. Then we have
    \[
    \begin{split}
        \nabla_{\beta}^{i-1} \nabla_{\alpha}^{d-j} \left[p_\sigma(\pi_\sigma(\bm{t}))\right] &\underset{\text{\cref{lem:chain-rule}}}{=} \nabla_{\beta}^{i-1} \nabla_{\alpha}^{d-j-1} \left[\left[\nabla_{\pi_\sigma(\alpha)} p_\sigma\right](\pi_\sigma(\bm{t}))\right] \\
            &\underset{\text{\cref{lem:pi-alpha-beta-relations}}}{=} \nabla_{\beta}^{i-1} \nabla_{\alpha}^{d-j-1} \left[\left[\nabla_{\alpha_L} p_\sigma\right](\pi_\sigma(\bm{t}))\right] \\
            &\underset{\text{\cref{lem:derivs-expression}}}{=} \nabla_{\beta}^{i-1} \nabla_{\alpha}^{d-j-1} \left[\left[\sum_{H: L < H} \alpha_L(H) \cdot p_{\sigma \cup \{H\}}(\pi_{\sigma+H}(\cdot))\right](\pi_\sigma(\bm{t}))\right] \\
            &\underset{\text{commutativity of $\bm\pi$}}{=} \sum_{H: L < H} \alpha_L(H) \cdot \nabla_{\beta}^{i-1} \nabla_{\alpha}^{d-j-1} \left[p_{\sigma \cup \{H\}}(\pi_{\sigma \cup \{H\}}(\bm{t}))\right]
    \end{split}
    \]
    First, if $b = d$ (which implies $b > j$) then the above expression is $0$ as desired, since there is no $H$ such that $L < H$. Otherwise by induction, each term of the right-hand side can only be non-zero if $\sigma \cup \{H\}$ is $[i,j+1]$-contiguous. Thus either this expression is $0$, or else $\sigma$ is $[i,j]$-contiguous and $H \in T_{j+1}$ and by induction we have
    \[
    \begin{split}
        \nabla_{\beta}^{i-1} \nabla_{\alpha}^{d-j} \left[p_\sigma(\pi_\sigma(\bm{t}))\right] &\underset{\text{induction}}{=} \sum_{H: L \prec H} \alpha_L(H) \cdot \mu_{\alpha,\beta}(\sigma \cup \{H\}) \\
            &\underset{\text{\cref{def:mu-alpha-beta}}}{=} \sum_{H: L \prec H} \alpha_L(H) \sum_{\tau\in X(d): \sigma \cup \{H\}\subseteq \tau}\left[\prod_{k=1}^{i-1} \beta^{\tau_{k+1}}(\tau_k)\right] \cdot \mu(\tau) \cdot \left[\prod_{k=j+2}^d \alpha_{\tau_{k-1}}(\tau_k)\right] \\
            &= \sum_{\tau\in X(d): \sigma \subseteq \tau}\left[\prod_{k=1}^{i-1} \beta^{\tau_{k+1}}(\tau_k)\right] \cdot \mu(\tau) \cdot \left[\prod_{k=j+1}^d \alpha_{\tau_{k-1}}(\tau_k)\right] \\
            &\underset{\text{\cref{def:mu-alpha-beta}}}{=} \mu_{\alpha,\beta}(\sigma)
    \end{split}
    \]
    as desired.

    In the case that $i > 1$, essentially the same proof works by first applying the computation above to $\nabla_\beta$ instead of $\nabla_\alpha$. First we would obtain
    \[
        \nabla_{\beta}^{i-1} \nabla_{\alpha}^{d-j} \left[p_\sigma(\pi_\sigma(\bm{t}))\right] = \sum_{H: H < K} \beta^K(H) \cdot \nabla_{\beta}^{i-2} \nabla_{\alpha}^{d-j} \left[p_{\sigma \cup \{H\}}(\pi_{\sigma \cup \{H\}}(\bm{t}))\right].
    \]
    If $a = 1$ (which implies $a < i$) then the above expression is $0$ as above. Otherwise by induction, each term of the right-hand side can only be non-zero if $\sigma \cup \{H\}$ is $[i-1,j]$-contiguous. Thus either this expression is $0$, or else $\sigma$ is $[i,j]$-contiguous and $H \in T_{i-1}$ and a similar argument as given above gives
    \[
        \nabla_{\beta}^{i-1} \nabla_{\alpha}^{d-j} \left[p_\sigma(\pi_\sigma(\bm{t}))\right] = \mu_{\alpha,\beta}(\sigma)
    \]
    as desired.
\end{proof}

\begin{corollary}[Eigenvalue bound for the $\alpha$-$\beta$ Hessians] \label{cor:eig-bound-alpha-beta}
    Given $1 \leq k \leq d-1$, let $B_k$ be the bipartite graph on $T_k \cup T_{k+1}$ with edge weights given by $\mu_{\alpha,\beta}(\{F,G\})$ for $F \prec G$, let $A_k$ be the weighted adjacency matrix of $B_k$, and let $D_k$ be the diagonal weighted degree matrix of $B_k$. Further, let $M_k$ be the diagonal matrix with entries given by
    \[
        m_k(F,F) = \frac{\sum_{G:F \prec G} \beta_F(G) \cdot \mu_{\alpha,\beta}(\{F,G\})}{\sum_{G:F \prec G} \mu_{\alpha,\beta}(\{F,G\})} \qquad \text{for} \quad F \in T_k
    \]
    and
    \[
        m_k(G,G) = \frac{\sum_{F:F \prec G} \alpha^G(F) \cdot \mu_{\alpha,\beta}(\{F,G\})}{\sum_{F:F \prec G} \mu_{\alpha,\beta}(\{F,G\})} \qquad \text{for} \quad G \in T_{k+1}.
    \]
    % \[
    %     m_k(H,H) = \begin{cases}
    %         \sum_{G:H \prec G} \beta_H(G) \cdot f(\{H,G\}), & H \in T_k \\
    %         \sum_{F:F \prec H} \alpha^H(F) \cdot f(\{F,H\}), & H \in T_{k+1}.
    %     \end{cases}
    % \]
    If $\cC_\varnothing$ is non-empty and $p_\varnothing$ is $\cC_\varnothing$-Lorentzian, then
    \[
        D_k^{-1/2} A_k D_k^{-1/2} \preceq M_k + \bm{w}\bm{w}^\top
    \]
    for some real vector $\bm{w}$.
\end{corollary}
\begin{proof}
    Note first that for $\{F,G\} \in X(2)$ with $F < G$, by \cref{lem:derivs-expression} we have
    \[
        \partial_{t_F} \partial_{t_G} p_\varnothing(\bm{t}) = p_{\{F,G\}}(\pi_{\{F,G\}}(\bm{t})).
    \]
    By \cref{lem:general-mixed-derivs-expression}, we then have
    \[
        \nabla_{\beta}^{k-1} \nabla_{\alpha}^{d-k-1} \partial_{t_F} \partial_{t_G} p_\varnothing(\bm{t}) = \begin{cases}
            \mu_{\alpha,\beta}(\sigma) > 0, & F \in T_k, G \in T_{k+1} \\
            0, & \text{otherwise}.
        \end{cases}
    \]
    Next for any $H \in X(1)$ we compute
    \[
    \begin{split}
        \partial_{t_H}^2 p_\varnothing(\bm{t}) &\underset{\text{\cref{lem:derivs-expression}}}{=} \partial_{t_H} p_{\{H\}}(\pi_{\{H\}}(\bm{t})) \\
            &\underset{\text{\cref{lem:chain-rule}}}{=} \left[\nabla_{\pi_{\{H\}}(\bm{1}_H)} p_{\{H\}}\right](\pi_{\{H\}}(\bm{t})) \\
            &\underset{\text{\cref{eq:pi-def-from-alpha-beta}}}{=} -\sum_{F: F < H} \alpha^H(F) \cdot p_{\{F,H\}}(\pi_{\{F,H\}}(\bm{t})) - \sum_{G: H < G} \beta_H(G) \cdot p_{\{H,G\}}(\pi_{\{H,G\}}(\bm{t})),
    \end{split}
    \]
    and by \cref{lem:general-mixed-derivs-expression} we have
    \[
        \nabla_{\beta}^{k-1} \nabla_{\alpha}^{d-k-1} \partial_{t_H}^2 p_\varnothing(\bm{t}) = \begin{cases}
            -\sum_{G: H \prec G} \beta_H(F) \cdot \mu_{\alpha,\beta}(\{H,G\}), & H \in T_k \\
            -\sum_{F: F \prec H} \alpha^H(F) \cdot \mu_{\alpha,\beta}(\{F,H\}), & H \in T_{k+1} \\
            0, & \text{otherwise}
        \end{cases}.
    \]
    Thus the Hessian $\cH$ of $\nabla_{\beta}^{k-1} \nabla_{\alpha}^{d-k-1} p_\varnothing(\bm{t})$ is supported only on $T_k \cup T_{k+1}$, and $\cH = A_k - D_k^{1/2}M_kD_k^{1/2}$. Since $p_\varnothing$ is $\cC_\varnothing$-Lorentzian and $\alpha,\beta \in \overline{\cC}_\varnothing$ by \cref{cor:alpha-beta-in-cone}, we thus have
    \[
        A_k - D_k^{1/2}M_kD_k^{1/2} = \cH \preceq \bm{v}\bm{v}^\top
    \]
    by \cref{lem:main-purpose-lemma} for some real vector $\bm{v}$, and this implies the desired result.
\end{proof}

\begin{corollary}[Log-concavity for the $\alpha$-$\beta$ coefficients] \label{cor:log-concavity-alpha-beta}
    Given $1 \leq k \leq d-1$ we have
    \[
        \sum_{F \in T_k} \beta(F) \cdot \mu_{\alpha,\beta}(\{F\}) = \sum_{G \in T_{k+1}} \alpha(G) \cdot \mu_{\alpha,\beta}(\{G\}),
    \]
    and we denote this quantity by $c_k$. Further, define
    \[
        c_0 = \sum_{G \in T_1} \alpha(G) \cdot \mu_{\alpha,\beta}(\{G\}) \qquad \text{and} \qquad c_d = \sum_{F \in T_d} \beta(F) \cdot \mu_{\alpha,\beta}(\{F\}).
    \]
    If $\cC_\varnothing$ is non-empty and $p_\varnothing$ is $\cC_\varnothing$-Lorentzian, then $(c_0,c_1,\ldots,c_d)$ forms a log-concave sequence.
\end{corollary}
\begin{proof}
    For $1 \leq k \leq d$ we have
    \[
        \nabla_{\beta}^k \nabla_{\alpha}^{d-k} p_\varnothing(\bm{t}) \underset{\text{\cref{lem:derivs-expression}}}{=} \nabla_{\beta}^{k-1} \nabla_{\alpha}^{d-k} \sum_{F \in T_k} \beta(F) \cdot p_F(\pi_F(\bm{t})) \underset{\text{\cref{lem:general-mixed-derivs-expression}}}{=} \sum_{F \in T_k} \beta(F) \cdot \mu_{\alpha,\beta}(\{F\}),
    \]
    and for $0 \leq k \leq d-1$ we have
    \[
        \nabla_{\beta}^k \nabla_{\alpha}^{d-k} p_\varnothing(\bm{t}) \underset{\text{\cref{lem:derivs-expression}}}{=} \nabla_{\beta}^k \nabla_{\alpha}^{d-k-1} \sum_{G \in T_{k+1}} \alpha(G) \cdot p_G(\pi_G(\bm{t})) \underset{\text{\cref{lem:general-mixed-derivs-expression}}}{=} \sum_{G \in T_{k+1}} \alpha(G) \cdot \mu_{\alpha,\beta}(\{G\}).
    \]
    Thus we have
    \[
        d! \cdot p_\varnothing(\beta \cdot x + \alpha) = \sum_{k=0}^d \binom{d}{k} c_k \cdot x^k,
    \]
    and therefore $(c_0,c_1,\ldots,c_d)$ forms a log-concave sequence by \cref{cor:alpha-beta-in-cone} and \cref{lem:main-purpose-lemma}.
\end{proof}


