%     Notice the first two conditions are essentially immediate, and $(j+k) \cdot (i+j) - j \cdot (i+j+k) = i \cdot k$ is the key identity used for the last two conditions.
% \end{proof}

\begin{lemma} \label{lem:alpha-beta-gen}
    Let $\phi: X(2) \to \R_{>0}$ be such that for all $K < F < G < L$ in $X(1)$ we have
    \[
        \phi(K,G) \cdot \phi(F,L) - \phi(K,L) \cdot \phi(F,G) = \phi(K,F) \cdot \phi(G,L).
    \]
    If for $K < F < L$ in $X(1)$ we define
    \[
        % \alpha_K^L(F) = \frac{r_K^F}{r_K^L} \qquad \text{and} \qquad \beta_K^L(F) = \frac{r_F^L}{r_K^L},
        \alpha_K^L(F) = \frac{\phi(K,F)}{\phi(K,L)} \qquad \text{and} \qquad \beta_K^L(F) = \frac{\phi(F,L)}{\phi(K,L)},
    \]
    then $\bm\alpha$ and $\bm\beta$ are commutative and give rise to a commutative family of maps $\bm\pi$ and their associated polynomials $p_\sigma$ for $\sigma \in X$.
\end{lemma}
\begin{proof}
    By \cref{prop:pi-maps-from-alpha-beta}, we just need to show that the conditions of \cref{def:alpha-beta} hold for $\bm\alpha$ and $\bm\beta$. The first two conditions follow from
    \[
        % \alpha_K^G(F) \cdot \alpha_K^L(G) = \frac{r_K^F}{r_K^G} \cdot \frac{r_K^G}{r_K^L} = \frac{r_K^F}{r_K^L} = \alpha_K^L(F)
        \alpha_K^G(F) \cdot \alpha_K^L(G) = \frac{\phi(K,F)}{\phi(K,G)} \cdot \frac{\phi(K,G)}{\phi(K,L)} = \frac{\phi(K,F)}{\phi(K,L)} = \alpha_K^L(F)
    \]
    and
    \[
        \beta_F^L(G) \cdot \beta_K^L(F) = \frac{\phi(G,L)}{\phi(F,L)} \cdot \frac{\phi(F,L)}{\phi(K,L)} = \frac{\phi(G,L)}{\phi(K,L)} = \beta_K^L(G).
    \]
    The last two conditions then follow from
    \begin{align*}
        \alpha_K^L(G) - \alpha_F^L(G) &= \frac{\phi(K,G)}{\phi(K,L)} - \frac{\phi(F,G)}{\phi(F,L)} 
        = \frac{\phi(K,G) \cdot \phi(F,L) - \phi(F,G) \cdot \phi(K,L)}{\phi(K,L) \cdot \phi(F,L)} \\
        &\underset{\text{Lem's assumption}}{=} \frac{\phi(K,F) \cdot \phi(G,L)}{\phi(K,L) \cdot \phi(F,L)} = \beta_F^L(G) \cdot \alpha_K^L(F)
    \end{align*}
    and
    \begin{align*}
        \beta_K^L(F) - \beta_K^G(F) &= \frac{\phi(F,L)}{\phi(K,L)} - \frac{\phi(F,G)}{\phi(K,G)} 
        = \frac{\phi(F,L) \cdot \phi(K,G) - \phi(F,G) \cdot \phi(K,L)}{\phi(K,L) \cdot \phi(K,G)}\\
        &\underset{\text{Lem's assumption}}{=} \frac{\phi(K,F) \cdot \phi(G,L)}{\phi(K,L) \cdot \phi(K,G)} = \alpha_K^G(F) \cdot \beta_K^L(G).
    \end{align*}
    % Notice the first two conditions are essentially immediate, and $(j+k) \cdot (i+j) - j \cdot (i+j+k) = i \cdot k$ is the key identity used for the last two conditions.
\end{proof}

Defining $\phi(F,G) = \phi(G)-\phi(F)$ for $F < G$, we obtain the following.

\begin{corollary} \label{cor:alpha-beta-v1}
    If for $K < F < L$ in $X(1)$ we define
    \begin{equation}\label{eq:alphaphidef}
        % \alpha_K^L(F) = \frac{r_K^F}{r_K^L} \qquad \text{and} \qquad \beta_K^L(F) = \frac{r_F^L}{r_K^L},
        \alpha_K^L(F) = \frac{\phi(F)-\phi(K)}{\phi(L)-\phi(K)} \qquad \text{and} \qquad \beta_K^L(F) = \frac{\phi(L)-\phi(F)}{\phi(L)-\phi(K)},
    \end{equation}
    then $\bm\alpha$ and $\bm\beta$ are commutative and give rise to a commutative family of maps $\bm\pi$ and their associated polynomials $p_\sigma$ for $\sigma \in X$.
\end{corollary}

To utilize the results of the previous sections, we need to show that the cone of positive vectors is non-empty.

\begin{lemma} \label{lem:cone-non-empty-v1}
    The cone $\cC_\sigma$ is non-empty for all $\sigma \in X$.
\end{lemma}
\begin{proof}
    Given $\sigma = \{F_1,F_2,\ldots,F_k\} \in X$ where $F_1 < F_2 < \cdots < F_k$, let
    \[
        \bm{t}=(c_0 \cdot \alpha^{F_1} \cdot \beta^{F_1}) \oplus (c_1 \cdot \alpha_{F_1}^{F_2} \cdot \beta_{F_1}^{F_2}) \oplus (c_2 \cdot \alpha_{F_2}^{F_3} \cdot \beta_{F_2}^{F_3}) \oplus \cdots \oplus (c_k \cdot \alpha_{F_k} \cdot \beta_{F_k}) \in \cC_\sigma
    \] 
     In other words,  for any $F_i<H<F_{i+1}$ (where assume $F_0=\hat{0},F_{k+1}=\hat{1}$), $$t_H=c_i\cdot\alpha_{F_i}^{F_{i+1}}(H)\cdot\beta_{F_i}^{F_{i+1}}(H).$$
    We show that $\bm{t}\in C_\sigma$ for all $c_0,c_1,\ldots,c_k > 0$.

    To that end,  let $F \in X_\sigma(1)$ be such that $F_i < F < F_{i+1}$ (for some $0\leq i\leq k$). For ease of notation, let $K=F_i,L=F_{i+1}$. We will show that $\pi_{\sigma+F}(\alpha_K^L \cdot \beta_K^L) = (c \cdot \alpha_K^F \cdot \beta_K^F) \oplus (c' \cdot \alpha_F^L \cdot \beta_F^L)$ for some $c,c' > 0$. By induction on $|\sigma|$ and the fact that $\bm\pi$ is commutative, this will prove the vector given above lies in $\cC_\sigma$.

    For $H \in (K,F)$, we have %Using the fact that $\bm\alpha,\bm\beta$ are commutative we compute
    \[
    \begin{split}
        \pi_{\sigma+F}(\alpha_K^L \cdot \beta_K^L)_H &\underset{\eqref{eq:pi-def-from-alpha-beta}}{=} \alpha_K^L(H) \cdot \beta_K^L(H) - \alpha_K^F(H) \cdot \alpha_K^L(F) \cdot \beta_K^L(F) \\
            &\underset{\text{(1) of \cref{def:alpha-beta}}}{=} \alpha_K^L(H) \cdot \beta_K^L(H) - \alpha_K^L(H) \cdot \beta_K^L(F) \\
            &\underset{\eqref{eq:alphaphidef}}{=} \alpha_K^L(H) \cdot \left(\frac{\phi(L)-\phi(H)}{\phi(L)-\phi(K)} - \frac{\phi(L)-\phi(F)}{\phi(L)-\phi(K)}\right) \\
            &= \frac{\phi(H)-\phi(K)}{\phi(L)-\phi(K)} \cdot \frac{\phi(F)-\phi(H)}{\phi(L)-\phi(K)} \\
            &\underset{\eqref{eq:alphaphidef}}{=} \alpha_K^L(F)^2 \cdot \left[\alpha_K^F(H) \cdot \beta_K^F(H)\right].
    \end{split}
    \]
    Now, fix $H \in (F,L)$, and we can similarly write %and again using the fact that $\bm\alpha,\bm\beta$ are hereditary we compute
    \[
    \begin{split}
        \pi_{\sigma+F}(\alpha_K^L \cdot \beta_K^L)_H &\underset{\eqref{eq:pi-def-from-alpha-beta}}{=} \alpha_K^L(H) \cdot \beta_K^L(H) - \beta_F^L(H) \cdot \alpha_K^L(F) \cdot \beta_K^L(F) \\
                &\underset{\text{(2) of \cref{def:alpha-beta}}}{=} \alpha_K^L(H) \cdot \beta_K^L(H) - \beta_K^L(H) \cdot \alpha_K^L(F) \\
        &\underset{\eqref{eq:alphaphidef}}{=}\beta_K^L(H) \cdot \left(\frac{\phi(H)-\phi(K)}{\phi(L)-\phi(K)} - \frac{\phi(F)-\phi(K)}{\phi(L)-\phi(K)}\right) \\
            &= \frac{\phi(L)-\phi(H)}{\phi(L)-\phi(K)} \cdot \frac{\phi(H)-\phi(F)}{\phi(L)-\phi(K)} \\
      &\underset{\eqref{eq:alphaphidef}}{=} \beta_K^L(F)^2 \cdot \left[\alpha_F^L(H) \cdot \beta_F^L(H)\right].
    \end{split}
    \]
    %Note that at the end of each computation we used the explicit definition of the $\bm\alpha$ and $\bm\beta$ vectors, rather than only using the fact that they are hereditary.
\end{proof}

