To prove the Heron-Rota-Welsh conjecture, we will utilize a standard result on the lattices of flats of matroids.

\begin{lemma}[Weisner's theorem] \label{lem:Weisner}
    Given $K \prec F < L$ in $X(1)$, we have that
    \[
        \tilde\mu(K,L) = -\sum_{H: \left\{\substack{K < H \prec L \\ F \not< H}\right\}} \tilde\mu(K,H).
    \]
\end{lemma}

\begin{corollary} \label{cor:Weisner-cor}
    Given $K < L$ in $X(1)$, we have that
    \[
        \tilde\mu(K,L) = -\sum_{G: K < G \prec L} \frac{|L|-|G|}{|L|-|K|} \cdot \tilde\mu(K,G).
    \]
\end{corollary}
\begin{proof}
    Using Weisner's theorem for all $i \in L \setminus K$, we have
    \[
    % \begin{split}
    %     \tilde\mu(K,L) &= -\frac{1}{|L \setminus K|} \sum_{i \in L \setminus K} \sum_{\substack{G: K < G \prec L \\ i \not\in G}} \tilde\mu(K,G) \\
    %         &= -\sum_{G: K < G \prec L} \frac{|L \setminus G|}{|L \setminus K|} \cdot \tilde\mu(K,G) \\
    %         &= -\sum_{G: K < G \prec L} \beta_K^L(G) \cdot \tilde\mu(K,G).
    % \end{split}
        \tilde\mu(K,L) = -\frac{1}{|L \setminus K|} \sum_{i \in L \setminus K} \sum_{\substack{G: K < G \prec L \\ i \not\in G}} \tilde\mu(K,G) = -\sum_{G: K < G \prec L} \frac{|L|-|G|}{|L|-|K|} \cdot \tilde\mu(K,G).
    \]
\end{proof}

Note that these previous results imply the M\"obius function alternates in sign by induction.

Now we utilize the previous results to prove \cref{thm:Heron-Rota-Welsh}. To do this, compute the numbers $c_k$ from \cref{thm:log-concavity-colored-complex}. Let $\hat{0}$ denote the set of loops of $M$, and set $n_0 = |\hat{0}|$. We have
\[
\begin{split}
    c_k &= \frac{1}{n-n_0} \sum_{\tau \in X(d)} 1 \cdot \frac{\prod_{i=0}^d |\tau_{i+1} \setminus \tau_i|}{\prod_{i=1}^k (|\tau_i| - n_0) \prod_{i=k+1}^d (n - |\tau_i|)} \\
        % &= \sum_{\tau \in X(d)} \frac{|\tau_{k+1}|-|\tau_k|}{n-n_0} \prod_{i=0}^{k-1} \frac{|\tau_{i+1}|-|\tau_i|}{|\tau_{i+1}|-n_0} \prod_{i=k+1}^d \frac{|\tau_{i+1}|-|\tau_i|}{n-|\tau_i|} \\
        &= \sum_{\tau \in X(d)} \frac{n-|\tau_k|}{n-n_0} \prod_{i=0}^{k-1} \frac{|\tau_{i+1}|-|\tau_i|}{|\tau_{i+1}|-n_0} \prod_{i=k}^d \frac{|\tau_{i+1}|-|\tau_i|}{n-|\tau_i|} \\
        &= \sum_{\tau_k \in T_k} \frac{n-|\tau_k|}{n-n_0} \sum_{\substack{\tau_1,\ldots,\tau_{k-1} \in X(1) \\ \tau_1 \prec \cdots \tau_{k-1} \prec \tau_k}} \prod_{i=0}^{k-1} \frac{|\tau_{i+1}|-|\tau_i|}{|\tau_{i+1}|-n_0} \sum_{\substack{\tau_{k+1},\ldots,\tau_d \in X(1) \\ \tau_k \prec \tau_{k+1} \prec \cdots \prec \tau_d}} \prod_{i=k+1}^d \frac{|\tau_{i+1}|-|\tau_i|}{n-|\tau_i|}.
\end{split}
\]
Now for any fixed $\tau_k \in T_k$ we compute
\[
    \sum_{\substack{\tau_{k+1},\ldots,\tau_d \in X(1) \\ \tau_k \prec \tau_{k+1} \prec \cdots \prec \tau_d}} \prod_{i=k}^d \frac{|\tau_{i+1}|-|\tau_i|}{n-|\tau_i|} = \sum_{\tau_{k+1} \succ \tau_k} \frac{|\tau_{k+1}|-|\tau_k|}{n-|\tau_k|} \cdots \sum_{\tau_d \succ \tau_{d-1}} \frac{|\tau_d|-|\tau_{d-1}|}{n-|\tau_{d-1}|} = 1,
\]
by successively applying the matroid partition property. And for any fixed $\tau_k \in T_k$ we compute
\[
    \sum_{\substack{\tau_1,\ldots,\tau_{k-1} \in X(1) \\ \tau_1 \prec \cdots \tau_{k-1} \prec \tau_k}} \prod_{i=0}^{k-1} \frac{|\tau_{i+1}|-|\tau_i|}{|\tau_{i+1}|-n_0} = \sum_{\tau_{k-1} \prec \tau_k} \frac{|\tau_k|-|\tau_{k-1}|}{|\tau_k|-n_0} \cdots \sum_{\tau_1 \prec \tau_2} \frac{|\tau_2|-|\tau_1|}{|\tau_2|-n_0} = |\tilde\mu(\hat{0},\tau_k)|,
\]
by successively applying \cref{cor:Weisner-cor} (since the M\"obius function alternates in sign). Thus we have
\[
    c_k = \sum_{\tau_k \in T_k} \frac{n-|\tau_k|}{n-n_0} \cdot |\tilde\mu(\hat{0},\tau_k)|
\]
for all $0 \leq k \leq d$, where $\tau_0 = \hat{0}$.

\begin{proof}[Proof of \cref{thm:Heron-Rota-Welsh}]
    Let $\gamma_k$ denote the absolute value of the $x^k$ coefficient of $\overline\chi_M(x)$. For any non-loop $i \in [n]$, the fact that the M\"obius function alternates in sign implies
    \[
        \gamma_{d-k} = \sum_{\tau_k \in T_k: i \not\in \tau_k} |\tilde\mu(\hat{0},\tau_k)|,
    \]
    and thus
    \[
        \gamma_{d-k} = \frac{1}{n-n_0} \sum_{i \in \hat{1} \setminus \hat{0}} \sum_{\tau_k \in T_k: i \not\in \tau_k} |\tilde\mu(\hat{0},\tau_k)| = \sum_{\tau_k \in T_k} \frac{n-|\tau_k|}{n-n_0} \cdot |\tilde\mu(\hat{0},\tau_k)| = c_k.
    \]
    Therefore $(\gamma_0,\gamma_1,\ldots,\gamma_d)$ forms a log-concave sequence by \cref{thm:log-concavity-colored-complex}.
\end{proof}

