\subsection{Colorings of distributive lattices}

Let $P$ be a finite Poset with associated distributive lattice $\cL$ and path complex $X$. Given $F \in X(1)$, we will consider $F$ to be a set of elements of the ground set of $P$. Let $\phi: X(1) \to \R_{>0}$ be any strictly order-preserving map, and let $L(P)$ denote the set of all linear extensions of $P$. We will think of linear extensions of $P$ as functions $\ell: P \to [d+1]$, and we will denote $\ell_k := \ell^{-1}(k) \in P$.

With this, we define $\bm\alpha$, $\bm\beta$ as in \cref{cor:alpha-beta-v1}, and we let the probability distribution $\mu$ be uniform on the facets of $X$.


\subsubsection{Stanley's inequality}

% Any weight function $\phi: P \to \R_{>0}$ gives rise to a strictly order preserving map $\phi: X(1) \to \R_{>0}$ via:
% \[
%     \phi(F) = \sum_{i \in F} \phi(i).
% \]
% We note that the conditions of  hold in general in this case.

Given some $a \in P$, we define
\[
    \phi_M(i) = \begin{cases}
        M, & i = a \\
        1, & i \neq a
    \end{cases}
\]
for some large constant $M > 1$, and we let $\phi_M(F) = \sum_{i \in F} \phi_M(i)$. We now compute $c_k$ for $0 \leq k \leq d$ as defined in \cref{thm:log-concavity-colored-complex}. As $M \to \infty$, we have
\[
\begin{split}
    c_k &= \frac{1}{\phi_M(\hat{1}) - \phi_M(\hat{0})} \sum_{\tau \in X(d)} \mu(\tau) \cdot \frac{\prod_{i=0}^d (\phi_M(\tau_{i+1}) - \phi_M(\tau_i))}{\prod_{i=1}^k (\phi_M(\tau_i) - \phi_M(\tau_0)) \prod_{i=k+1}^d (\phi_M(\tau_{d+1}) - \phi_M(\tau_i))} \\
        &= \frac{1}{M + d} \sum_{\tau \in X(d)} \frac{M}{\prod_{i=1}^k (\phi_M(\tau_i) - \phi_M(\tau_0)) \prod_{i=k+1}^d (\phi_M(\tau_{d+1}) - \phi_M(\tau_i))} \\
        &\underset{M \to \infty}{\to} \sum_{\substack{\tau \in X(d) \\ \tau_{k+1} \setminus \tau_k = \{a\}}} \frac{1}{k!(d-k)!} \\
        &= \frac{|\{\tau \in X(d): \tau_{k+1} \setminus \tau_k = \{a\}\}|}{k!(d-k)!} \\
        &= \frac{|\{\ell \in L(P): \ell_{k+1} = a\}|}{k!(d-k)!}.
\end{split}
\]
Thus by applying \cref{lem:toplinkexpansioncolorlattice} and \cref{thm:log-concavity-colored-complex} we obtain a weak version of Stanley's inequality, which says that $(c_0,c_1,\ldots,c_d)$ forms a log-concave sequence.

To obtain the full Stanley's inequality, we now append chains of length $N$ below and above all elements of the Poset $P$ to obtain $P'$ and apply the above log-concavity statement. This implies $(c_N',c_{N+1}',\ldots,c_{N+d}')$ forms a log-concave sequence, where
\[
    c_{N+k}' = \frac{|\{\ell \in L(P') : \ell_{N+k+1} = a\}|}{(N+k)!(N+d-k)!} = \frac{|\{\ell \in L(P) : \ell_{k+1} = a\}|}{(N+k)!(N+d-k)!}.
\]
By multiplying by $N!(N+d)!$ and limiting $N \to \infty$, we obtain Stanley's inequality for the original Poset $P$.


