This leads to the main result of this section, which gives eigenvalue bounds on the random walk matrix associated to $X$ based on the machinery of the previous sections.

\begin{theorem} \label{thm:eig-bounds-main-v1}
    Fix $k \in [d-1]$, and let $G_{k,k+1}$ be the bipartite graph on $T_k \cup T_{k+1}$ with corresponding random walk matrix $P_{k,k+1}$ according to stationary distribution $\mu$. Let $A_k$ be the weighted adjacency matrix of $G_{k,k+1}$, let $D_k$ be the diagonal weighted degree matrix of $G_{k,k+1}$, and let $M_k$ be the diagonal matrix with entries given by $\frac{d-k}{d-k+1}$ for vertices in $T_k$ and $\frac{k}{k+1}$ for vertices in $T_{k+1}$. If $p_\varnothing$ is $\cC_\varnothing$-Lorentzian, then
    \[
        D_k^{-1/2} A_k D_k^{-1/2} \preceq M_k + \bm{w}\bm{w}^\top
    \]
    for some real vector $\bm{w}$. Moreover, the second eigenvalue of $P_{k,k+1}$ is at most $\sqrt{\frac{k(d-k)}{(k+1)(d-k+1)}}$.
\end{theorem}
\begin{proof}
    By \cref{cor:eig-bound-alpha-beta} and \cref{cor:alpha-beta-rank}, we have that
    \[
        D_k^{-1/2} A_k D_k^{-1/2} \preceq M_k + \bm{w}\bm{w}^\top
    \]
    where the entries of $A_k$ are given by
    \[
    \begin{split}
        \mu_{\alpha,\beta}(\{F,G\}) &= \sum_{\tau\in X(d): \{F,G\}\subseteq \tau}\left[\prod_{i=1}^{k-1} \beta^{\tau_{k+1}}(\tau_k)\right] \cdot \mu(\tau) \cdot \left[\prod_{i=k+2}^d \alpha_{\tau_{k-1}}(\tau_k)\right] \\
            &= \sum_{\tau\in X(d): \{F,G\}\subseteq \tau} \left[\prod_{i=1}^{k-1} \frac{1}{i+1}\right] \cdot \mu(\tau) \cdot \left[\prod_{i=k+2}^d \frac{1}{d-i+2}\right] \\
            &= \frac{\mu(\{F,G\})}{k!(d-k)!},
    \end{split}
    \]
    the entries of $D_k$ are given by the row sums of $A_k$, and the entries of $M_k$ are given by
    \[
        m_k(F,F) = \frac{\sum_{G:F \prec G} \beta_F(G) \cdot \mu_{\alpha,\beta}(\{F,G\})}{\sum_{G:F \prec G} \mu_{\alpha,\beta}(\{F,G\})} = \frac{d-k}{d-k+1} \qquad \text{for} \quad F \in T_k
    \]
    and
    \[
        m_k(G,G) = \frac{\sum_{F:F \prec G} \alpha^G(F) \cdot \mu_{\alpha,\beta}(\{F,G\})}{\sum_{F:F \prec G} \mu_{\alpha,\beta}(\{F,G\})} = \frac{k}{k+1} \qquad \text{for} \quad G \in T_{k+1}.
    \]
    Since the entries of $A_k$ are proportional to the edge weights of $G_{k,k+1}$ for given $k$, this implies the first desired result. The eigenvalue bound for $P_{k,k+1}$ then immediately follows from \cref{lem:eigenvaluebipartite}.
\end{proof}


