In this section we prove \cref{thm:main-s}. 
Recall the notation $[k]_s = \frac{s^k - s^{-k}}{s - s^{-1}}$ and notice $[k]_1=k$.
Throughout the remainder of this section, we fix a parameter $s \geq 1$. For $F<G$ with $F\in T_i,G\in T_j$, let $\phi(F,G) =[r_F^G]_s=[j-i]_s$. Invoking \cref{lem:alpha-beta-gen} we obtain: 

\begin{lemma} \label{lem:alpha-beta-v3}
    If for $K < F < L$ in $X(1)$ we define
    \[
        \alpha_K^L(F) = \frac{[r_K^F]_s}{[r_K^L]_s} \qquad \text{and} \qquad \beta_K^L(F) = \frac{[r_F^L]_s}{[r_K^L]_s},
    \]
    then $\bm\alpha$ and $\bm\beta$ are commutative and give rise to a commutative family of maps $\bm\pi$ and their associated polynomials $p_\sigma$ for $\sigma \in X$.
\end{lemma}
\begin{proof}
For $K<F<G<L$ in $X(1)$, let $i=r_K^F, j=r_F^G,k=r_G^L$; we have
    \begin{align*}
        &\phi(K,G)\cdot \phi(F,L)-\phi(K,L)\cdot \phi(F,G) \\
        &=[j+k]_s \cdot [i+j]_s - [j]_s \cdot [i+j+k]_s \\
            &= \frac{(s^{j+k}-s^{-j-k}) \cdot (s^{i+j}-s^{-i-j}) - (s^j-s^{-j}) \cdot (s^{i+j+k}-s^{-i-j-k})}{(s-s^{-1})^2} \\
            &= \frac{s^{i+k}+s^{-i-k}-s^{i-k}-s^{k-i}}{(s-s^{-1})^2} \\
            &= \frac{(s^i - s^{-i}) \cdot (s^k - s^{-k})}{(s-s^{-1})^2} \\
            &= [i]_s \cdot [k]_s = \phi(K,F)\cdot \phi(G,L).
    \end{align*}
    as desired.
    %hich is the analogous key identity needed for the last two conditions of \cref{def:alpha-beta}.
\end{proof}
Note that if we set $s=1$, then the definition of $\bm\alpha$ and $\bm\beta$ in \cref{lem:alpha-beta-v3} coincides with that of \cref{cor:alpha-beta-rank}. The value of the parameter $s$ then becomes useful in the way that it makes \cref{thm:eig-bounds-main-v1} more robust, as seen in \cref{thm:eig-bounds-main-v3} below.

One key difference here is that the proof of \cref{lem:cone-non-empty-v1} does not work, and so we will prove \cref{lem:cone-containment} instead which implies the cones $\cC_\sigma$ are non-empty as a corollary. First, we need a technical lemma.

\begin{lemma} \label{lem:k-n-s-decreasing}
    For all $0 \leq k \leq n$, we have that $\frac{[k]_s}{[n]_s}$ is decreasing as a function of $s \in [1,\infty)$.
\end{lemma}
\begin{proof}
    Since $s \geq 1$, we first compute
    \[
        \partial_s[k(s^n - s^{-n}) - n(s^k - s^{-k})]
            % = nk(s^{n-1}+s^{-n-1}-s^{k-1}-s^{-k-1})
            = nk(s^{k-1}-s^{-n-1}) (s^{n-k}-1)
            \geq 0,
    \]
    which implies $\frac{[k]_s}{[n]_s} \leq \frac{k}{n}$ for $0 \leq k \leq n$. Next we prove that $\partial_s \log\left(\frac{s^k-s^{-k}}{s^n-s^{-n}}\right) \leq 0$ for $s \geq 1$. We compute
    \[
        \partial_s \log\left(\frac{s^k-s^{-k}}{s^n-s^{-n}}\right) = \frac{k(s^k+s^{-k})(s^n-s^{-n}) - n(s^n+s^{-n})(s^k-s^{-k})}{s(s^k-s^{-k})(s^n-s^{-n})}.
    \]
    Thus for $s \geq 1$ we want to prove
    \[
    \begin{split}
        k(s^k+s^{-k})(s^n-s^{-n}) &\leq n(s^n+s^{-n})(s^k-s^{-k}) \\
            \iff \frac{k}{n} &\leq \frac{(s^n+s^{-n})(s^k-s^{-k})}{(s^k+s^{-k})(s^n-s^{-n})} = 1 - \frac{2(s^{n-k} - s^{k-n})}{(s^k+s^{-k})(s^n-s^{-n})} \\
            \iff \frac{n-k}{n} &\geq \frac{2}{s^k+s^{-k}} \cdot \frac{[n-k]_s}{[n]_s}.
    \end{split}
    \]
    Since $2 \leq s^k+s^{-k}$ and $\frac{[n-k]_s}{[n]_s} \leq \frac{n-k}{n}$ via the argument given above, we thus have that the above inequality holds. Therefore $\frac{s^k-s^{-k}}{s^n-s^{-n}}$ is decreasing for $s \geq 1$.
\end{proof}

\begin{lemma}[Cone containment for $s \geq 1$] \label{lem:cone-containment}
    Given $\sigma \in X$ and $1 \leq s \leq t$, we have that $\cC_\sigma^s \subseteq \cC_\sigma^t$.
    Moreover, $\cC_\sigma = \cC_\sigma^s \neq \varnothing$ for all $\sigma \in X$ and $s\geq 1$.
\end{lemma}
\begin{proof}
    The result follows if we can show for all $\bm{v} \in \cC_\sigma^s$ and $\tau \in X_\sigma$ that $\pi^s_{\sigma+\tau}(\bm{v}) \leq \pi_{\sigma+\tau}^t(\bm{v})$ entrywise. To this end, we first note that $\frac{[k]_s}{[n]_s}$ is decreasing in $s$ for $s \geq 1$ for all $0 \leq k \leq n$ by \cref{lem:k-n-s-decreasing}. Now for $F \in X_{\sigma \cup \tau}$, we have that
    \[
        \pi_{\sigma+\tau}(\bm{v})_F = v_F - \alpha_K^L(F) \cdot v_L - \beta_K^L(F) \cdot v_K
    \]
    for some $K,L \in \sigma \cup \tau \cup \{\hat{0},\hat{1}\}$ for which $F \in (K,L)$, where possibly $v_K = 0$ and/or $v_L = 0$ (if $K \in \sigma$ and/or $L \in \sigma$). With this we have
    \[
        \pi^s_{\sigma+\tau}(\bm{v})_F = v_F - \frac{[r_K^F]_s}{[r_K^L]_s} \cdot v_L - \frac{[r_F^L]_s}{[r_K^L]_s} \cdot v_K \leq v_F - \frac{[r_K^F]_t}{[r_K^L]_t} \cdot v_L - \frac{[r_F^L]_t}{[r_K^L]_t} \cdot v_K = \pi^t_{\sigma+\tau}(\bm{v})_F,
    \]
    and this completes the proof of the first assertion. The second assertion then follows from the fact that $\cC_\sigma^1\neq \varnothing$ by \cref{lem:cone-non-empty-v1}.
\end{proof}

% \begin{corollary} \label{cor:cone-non-empty-v3}
%     The cone $\cC_\sigma$ is non-empty for all $\sigma \in X$.
% \end{corollary} 

Beyond implying $\cC_\sigma\neq \varnothing$, %\cref{cor:cone-non-empty-v3}, 
the previous lemma also adds intuition to what is happening when the $s$ parameter deviates from $s=1$. Specifically, since $\cC_\sigma$ is expanding as $s$ increases, this implies the condition of being $\cC_\sigma$-Lorentzian is becoming stronger. This is why one can expect to obtain stronger eigenvalue bounds in this case.

This leads to the main result of this section, which gives eigenvalue bounds on the random walk matrix associated to $X$ based on the machinery of the previous sections.

\begin{theorem} \label{thm:eig-bounds-main-v3}
    Fix $k \in [d-1]$, and let $G_{k,k+1}$ be the bipartite graph on $T_k \cup T_{k+1}$ with corresponding random walk matrix $P_{k,k+1}$ according to stationary distribution $\mu$. Let $A_k$ be the weighted adjacency matrix of $G_{k,k+1}$, let $D_k$ be the diagonal weighted degree matrix of $G_{k,k+1}$, and let $M_k$ be the diagonal matrix with entries given by $\frac{[d-k]_s}{[d-k+1]_s}$ for vertices in $T_k$ and $\frac{[k]_s}{[k+1]_s}$ for vertices in $T_{k+1}$. If $p_\varnothing$ is $\cC_\varnothing$-Lorentzian, then
    \[
        D_k^{-1/2} A_k D_k^{-1/2} \preceq M_k + \bm{w}\bm{w}^\top
    \]
    for some real vector $\bm{w}$. Moreover, the second eigenvalue of $P_{k,k+1}$ is at most $\sqrt{\frac{[k]_s[d-k]_s}{[k+1]_s[d-k+1]_s}}$.
\end{theorem}
\begin{proof}
    By \cref{cor:eig-bound-alpha-beta} and \cref{lem:cone-containment}, we have that
    \[
        D_k^{-1/2} A_k D_k^{-1/2} \preceq M_k + \bm{w}\bm{w}^\top
    \]
    where the entries of $A_k$ are given by
    \[
    \begin{split}
        \mu_{\alpha,\beta}(\{F,G\}) &= \sum_{\tau\in X(d): \{F,G\}\subseteq \tau} \left[\prod_{i=1}^{k-1} \beta^{\tau_{i+1}}(\tau_i)\right] \cdot \mu(\tau) \cdot \left[\prod_{i=k+2}^d \alpha_{\tau_{i-1}}(\tau_i)\right] \\
            &= \sum_{\tau\in X(d): \{F,G\}\subseteq \tau} \left[\prod_{i=1}^{k-1} \frac{1}{[i+1]_s}\right] \cdot \mu(\tau) \cdot \left[\prod_{i=k+2}^d \frac{1}{[d-i+2]_s}\right] \\
            &= \frac{\mu(\{F,G\})}{[k]_s![d-k]_s!},
    \end{split}
    \]
    the entries of $D_k$ are given by the row sums of $A_k$, and the entries of $M_k$ are given by
    \[
        m_k(F,F) = \frac{\sum_{G:F \prec G} \beta_F(G) \cdot \mu_{\alpha,\beta}(\{F,G\})}{\sum_{G:F \prec G} \mu_{\alpha,\beta}(\{F,G\})} = \frac{[d-k]_s}{[d-k+1]_s} \qquad \text{for} \quad F \in T_k
    \]
    and
    \[
        m_k(G,G) = \frac{\sum_{F:F \prec G} \alpha^G(F) \cdot \mu_{\alpha,\beta}(\{F,G\})}{\sum_{F:F \prec G} \mu_{\alpha,\beta}(\{F,G\})} = \frac{[k]_s}{[k+1]_s} \qquad \text{for} \quad G \in T_{k+1}.
    \]
    Since the entries of $A_k$ are proportional to the edge weights of $G_{k,k+1}$ for given $k$, this implies the first desired result. The eigenvalue bound for $P_{k,k+1}$ then immediately follows from \cref{lem:eigenvaluebipartite}.
\end{proof}


\begin{proof}[Proof of \cref{thm:main-s}]
We prove the bounds for the case of $k=d$ (link of $\varnothing$). By similarity, the bound extends to the 1-skeleton of all links (of co-dimension at least 2) of $X$. In particular, note that any link of a top-link path complex is also a top-link path complex.

Let $G_\varnothing$ be the 1-skeleton of $X_\varnothing$,
 $G_{i,j}$ be the induced bipartite graph between parts $T_i,T_j$ and $P_{i,j}$ be the corresponding simple random walk.
 First, by \cref{thm:eig-bounds-main-v3}, we have that for any $k\in [d-1]$, 
 $$ \lambda_2(P_{k,k+1})\leq \sqrt{\frac{[k]_s[d-k]_s}{[k+1]_s[d-k+1]_s}}.$$
 Second, by \cref{lem:dpartiteeigproduct}, for any $1\leq i<j\leq d$ we have
 $$ \lambda_2(P_{i,j}) \leq \prod_{k=i}^{j-1} \sqrt{\frac{[k]_s[d-k]_s}{[k+1]_s[d-k+1]_s}} = \sqrt{\frac{[i]_s\cdot [d-j+1]_s\cdot }{[j]_s\cdot [d-i+1]_s}}$$
%The first bound then follows from \cref{lem:dpartiteeigenvalues}.

For $i < j$, let $M_{i,j}$ be a diagonal matrix with entries given by $m_i(j) := \frac{[d-j+1]_s}{[d-i+1]_s}$ for vertices in $T_i$ and $m_j(i):= \frac{[i]_s}{[j]_s}$ for vertices in $T_j$. Note that since $[.]_s$ is increasing function, $0\leq m_i(j),m_j(i)<1$. By \cref{lem:eigenvaluebipartite}, we get that $\lambda_2(P_{i,j} - M_{i, j}) \leq 0$ and therefore has at most one positive eigenvalue. 
Next we want to use \cref{lem:dpartiteeigenvalues} to bound $\lambda_2(P_\varnothing)$.
 For any fixed $i\in [d]$, we have 
 \begin{align*}
     \E_{j \in [d], j \neq i} m_i(j) &= \frac{1}{d-1} \left(\sum_{j=1}^{i-1} \frac{[j]_s}{[i]_s} +\sum_{j=i+1}^d \frac{[d-j+1]_s}{[d-i+1]_s} \right)\\
     &=\frac{1}{(d-1)(s-1)}\left(\frac{s^i-s}{s^i+1} + \frac{s^{d-i+1}-s}{s^{d-i+1}+1}\right) \\
     &= \frac{1}{(d-1)(s-1)}\left(2 - (s+1)\left(\frac{1}{s^i+1} + \frac{1}{s^{d-i+1}+1}\right)\right) \\
     &\leq \frac{2}{(d-1)(s-1)} \left(1 - \frac{s+1}{s^{\frac{d+1}{2}}+1}\right) \\
     &= \frac{2}{(d-1)(s^{\frac{d+1}{2}}+1)} \left(\frac{s^{\frac{d-1}{2}}-1}{s-1}\right) \leq \frac{2}{(d-1)(s-1)}
     %&=\frac{1}{d-1} \left(\frac{i-1}{2} +\frac{d-i}{2} \right)\\
     %&= \frac{1}{2}.
 \end{align*}
Note that the second to last inequality follows from the fact that $\frac{1}{s^i+1} + \frac{1}{s^{d-i+1}+1}$ is convex for $i\in [0,d+1]$ and minimized at $i = \frac{d+1}{2}$.
This finishes the first assertion of the theorem. 

