\section{Top-link Expander Path Complexes}
\label{sec:quadraticcheck}
Recall that if $\cL$ is a semimodular ranked lattice, then for any $F,G \in \cL$ we have $\rk(F) + \rk(G) \geq \rk(F \vee G) + \rk(F \wedge G)$. Note that all modular lattices are semimodular, and the lattice of flats of a matroid is semimodular. Thus \cref{cor:latticeconnected} applies to all lattices that we will consider in the following sections.

\begin{lemma} \label{lem:empty-set-connected}
    Let $\cL$ be a semimodular ranked lattice with $d+1=\rk(\hat{1}) \geq 3$, and let $X$ be the $d$-partite complex consisting of {\bf all} flags of flats in $\cL$. Then $G_\varnothing$ is  connected.
\end{lemma}
\begin{proof}
    %We show the $1$-skeleton of $X_\varnothing$ is connected. 
    Given $F,G \in X(1)$. We prove the claim by induction on $\rk(F)+\rk(G)$. 
    If $F \vee G \neq \hat{1}$ or $F \wedge G \neq \hat{0}$, then $F$ and $G$ are connected in the $1$-skeleton. 
    To see that, notice in the former case, $F$ is connected to $F\vee G$, i.e., $\{F,F \vee G\} \in X(2)$, as there is a flag of flats which contains $F, F\vee G$; similarly $G$ is connected to $F\vee G$. The other case can be shown similarly.

    Now, suppose $F\vee G=\hat{1}, F\wedge G=\hat{0}.$ Since
    $$ \rk(F)+\rk(G) \geq \rk(F\vee G) + \rk(F \wedge G)=\rk(\hat{1}) \geq 3$$
    it must be that $\max\{\rk(F), \rk(G)\}\geq 2$. 

    Say $\rk(G)\geq 2$, without loss of generality. Then there is a flat $H$ such that $H\prec G$ and $\{G,H\}\in X(2)$. Since $\rk(F)+\rk(H)<\rk(F)+\rk(G)$, by IH, $F$ is connected to $H$. Therefore,      $F$ is connected to $G$.
    %But then, $\rk(H\vee F)\leq 2$, so $F\vee H\neq \hat{1}$, and $F$ is also connected to $H$.  
\end{proof}

\begin{corollary}\label{cor:latticeconnected}
    Let $\cL$ be a semimodular ranked lattice, and let $X$ be the $d$-partite complex consisting of {\bf all} flags of flats in $\cL$. Then $G_\sigma$ is  connected for $\sigma \in X$ for which $\codim(\sigma) \geq 2$.
\end{corollary}
\begin{proof}
    % If $\sigma = \varnothing$, then $\codim(\varnothing) \geq 2$ implies $d+1 \geq 3$, an thus the desired result follows from \cref{lem:empty-set-connected}. Otherwise,
    Fix $F,G \in X_\sigma(1)$. If there exists $H \in \sigma$ such that $F < H < G$ or $G < H < F$, then there is a flag of flats in $\cL$ containing $\sigma$ and $F,G$. Thus $F$ and $G$ are connected in the $1$-skeleton of $X_\sigma$.

    Otherwise $F,G$ are incomparable, and thus there exists a minimal $L \in X_\sigma(1) \cup \{\hat{1}\}$ and a maximal $K \in X_\sigma(1) \cup \{\hat{0}\}$ such that $K < F < L$ and $K < G < L$. Note that $[K,L]$ is now a ranked lattice (where $(K,L) \subset X_\sigma(1)$), and thus if $\rk(L) - \rk(K) \geq 3$ then the desired result follows from \cref{lem:empty-set-connected} applied to $[K,L]$. For the case of $\rk(L) - \rk(K) = 2$, note that $\rk(F) = \rk(G)$ in this case. Since $\codim(\sigma) \geq 2$, there must be some $H \in X_\sigma(1)$ such that $\rk(H) \neq \rk(F)$. Therefore either $F \prec L < H$ and $G \prec L < H$, or else $H < K \prec F$ and $H < K \prec G$.
    Either way, there is a flag of flats in $\cL$ containing $\sigma$ and $F,H$ and a flag of flats in $\cL$ containing $\sigma$ and $G,H$.  Thus $F$ and $G$ are connected in the $1$-skeleton of $X_\sigma$.
\end{proof}

