\subsection{$1/2$-top link expansion of Typical Modular Lattices}
In this section we prove \cref{thm:modularlattice}.
\begin{definition}[Unique Neighbor Property]
    Let $G=(X,Y,E)$ be a bipartite graph. We say $G$ has the {\bf unique neighbor property} if
for any pair of vertices $x_i,x_j \in X$ they have exactly one common neighbor in $Y$ and any pair of vertices $y_i, y_j \in Y$ have exactly one common neighbor in $X$.
\end{definition}

\begin{lemma}\label{lem:uniqueneighbor}
    Let $\cL$ be a modular lattice with $\rk(\hat{1})=3$. Then, the bipartite graph defined by the rank 1 and rank 2 flats of $\cL$ has the unique neighbor property.
\end{lemma}
\begin{proof}
    The proof uses the modular property of the rank.
    For any two rank 1 flats $F,G\in \cL$ we have $F\wedge G=\hat{0}$, i.e., $\rk(F\wedge G)=0$. Therefore, we must have $rk(F\vee G)=2.$
    Conversely, consider two flats $F,G$ of rank 2. We have $F\vee G=\hat{1}$, i.e., $\rk(F\vee G)=3$. So, we must have $F\wedge G$ has rank 1.
\end{proof}

\begin{theorem}\label{thm:uniqueneighborgraphs}
    Let $G=(X,Y,E)$ be a bipartite graph with the unique neighbor property with adjacency matrix $A$ and the diagonal matrix $D$ of vertex degrees. Then, $-D/2+A$ has exactly one positive eigenvalue iff one of the following holds: 
