    \end{bmatrix}
\]
Here, the first row and column of $B$ corresponds to the large degree vertices in $X,Y$. Let $n+1=|X|=|Y|$.
Consider the matrix
\[
    B' = \begin{bmatrix}
        \frac{n-2}{2} & 1 & 1 & 1 & \cdots & 1 \\
        1 & 1 & 0 & 0 & \cdots & 0 \\
        1 & 0 & 1 & 0 & \cdots & 0 \\
        1 & 0 & 0 & 1 & \cdots & 0 \\
        \vdots & \vdots & \vdots & \vdots & \ddots & \vdots \\
        1 & 0 & 0 & 0 & \cdots & 1
    \end{bmatrix}.
\]
We have
\[
    B'(B')^\top = (B')^\top B' = \begin{bmatrix}
        \frac{n^2}{4} + 1 & \frac{n}{2} & \frac{n}{2} & \cdots & \frac{n}{2} \\
        \frac{n}{2} & 2 & 1 & \cdots & 1 \\
        \frac{n}{2} & 1 & 2 & \cdots & 1 \\
        \vdots & \vdots & \vdots & \ddots & \vdots \\
        \frac{n}{2} & 1 & 1 & \cdots & 2
    \end{bmatrix}
    = I + \left(\frac{n}{2} \bm{e}_1 + \sum_{i=2}^{n+1} \bm{e}_i\right) \left(\frac{n}{2} \bm{e}_1 + \sum_{i=2}^{n+1} \bm{e}_i\right)^\top,
\]
where $\bm{e}_i$ is the indicator vector of the $i$-th coordinate.
Thus $B'(B')^\top = (B')^\top B'$ has exactly $n$ eigenvalues equal to $1$ and exactly one eigenvalue greater than $1$. Let $A'=\begin{bmatrix} 0 & B'\\ {B'}^\top & 0\end{bmatrix}$. Therefore the matrix
\[
    (A')^2 = 
    \begin{bmatrix}
        B'(B')^\top & 0 \\ 0 & (B')^\top B'
    \end{bmatrix}
\]
has exactly $2n$ eigenvalues equal to $1$ and the other $2$ greater than $1$. Since $A'$ is the adjacency matrix of a bipartite graph, using \cref{lem:AB}, $A'$ has  $n$ many $+1$ eigenvalues, $n$  many $-1$ eigenvalues, one greater than $+1$ and one less than $-1$. Therefore,  $A' - I$ has exactly one positive eigenvalue. Since
\[
    -\frac12 D+A = A' - I - \frac{n-2}{2}(\bm{e}_1 + \bm{e}_{n+2})(\bm{e}_1 + \bm{e}_{n+2})^\top,
\]
this implies $-D/2+A$ has at most one positive eigenvalue. 
\end{proof}


\begin{lemma}\label{lem:projplane3rdprop}
   % Let $\cL$ be a rank 3 modular lattice with minimum/maximum element $\hat{0}/\hat{1}$. 
   Let $G=(X,Y,E)$ be a non-empty bipartite graph with the unique neighbor property 
    %${\cal F}_1, {\cal F}_2$ be the set of rank 1 and rank 2 flats of $\cL$ and let $G=({\cal F}_1,{\cal F}_2,E)$ be the bipartite coomparability graph between flats of rank 1 and 2. If 
    such that the minimum degree of $G$ is $\geq 3$. Then, there are 4 vertices $x_1,\dots,x_4\in X$ such that any $y\in Y$ is adjacent to at most two of them (similarly there are $4$ vertices in $Y$ that any vertex in $X$ is adjacent to at most two of them).
    %Then, for some $d\geq 3$, $G$ is $d+1$-regular and $|X|=|Y|=d^2+d+1$.
    %In fact, $\cL$ corresponds to a projective plane.
\end{lemma}
\begin{proof}
    Let $y_1,y_2\in Y$ be two distinct vertices (note that $|Y|\geq 3$ by lemma's assumption). Since degree of $y_1,y_2$ is at least 3, by the unique neighbor property, there are two vertices $x_1,x_2$ adjacent to $y_1$ and two vertices $x_3,x_4$ adjacent to $y_2$ such that $y_1$ is not connected to $x_3,x_4$ and $y_2$ is not connected to $x_1,x_2$. Now, we claim that any vertex $y\in Y$ is connected to at most two of $\{x_1,\dots,x_4\}$. For contradiction, suppose there is a vertex $y$ that is connected to, say wlog, $x_1,x_2,x_3$. Then, $y\neq y_1,y_2$ by the above assumption. But then $y$ has two common neighbors to $y_1$ and that is a contradiction with the unique neighbor property. 
\end{proof}

\begin{definition}[Projective Plane]A projective plane is an incidence structure of "points" and "lines" with the following properties.
\begin{itemize}
    \item 
Given any two distinct points, there is exactly one line incident with both of them.
\item 
Given any two distinct lines, there is exactly one point incident with both of them.
\item 
There are four points such that no line is incident with more than two of them.
\end{itemize}
\end{definition}
The above lemma implies that our bipartite graph with the unique neighbor property and min degree 3 corresponds to a projective plane.
\begin{lemma}\label{lem:projplane}
    Every point in a projective plane is incident with a constant $d + 1$ lines and every line is incident with $d + 1$ points. Such a projective plane has  $d^2 + d + 1$ points and lines.
\end{lemma}
We refer interested reader to \cite{BW11} for background on projective plane and proof of the above lemma. 

\begin{lemma}\label{lem:projeplanelorentzian}
    Given a $(d+1)$-regular bipartite graph $G=(X,Y,E)$ with $d\geq 1$, $|X|=|Y|=d^2+d+1$, and the unique neighbor property, $\frac{-\sqrt{d}}{d+1}D + A$ has one positive eigenvalue. Therefore, $-D/2+A$ also has one positive eigenvalue.
\end{lemma}
\begin{proof}
Since $G$ is $(d+1)$-regular  we have that $D = (d+1)I$. Furthermore, by the unique neighbor property and the $(d+1)$-regularity, we have
$$ A^2 = \begin{bmatrix}J+dI & 0 \\ 0 & J+dI\end{bmatrix}$$
This is because by the unique neighbor property for every pair of vertices $x,x'\in X$ there is exactly one path of length 2 from $x$ to $x'$ (and similarly for the $y$-vertices).
where $J$ is a $|X|\times |X|$ all-ones matrix. It follows that $A^2$ has two eigenvalues equal to $d^2+d+1+d=(d+1)^2$ and $2|X|-2$ many eigenvalues equal to $d$.
Therefore, since $G$ is a bipartite graph, by \cref{lem:AB}, $A$ has the following spectrum
\[
    \big(d+1, \underbrace{\sqrt{d}, \dots, \sqrt{d}}_{d^2+d\text{ many}}, \underbrace{-\sqrt{d}, \ldots, -\sqrt{d}}_{d^2+d\text{ many}}, -(d+1)\big).
\]
Therefore,
$$ \frac{-\sqrt{d}}{d+1}D + A = -\sqrt{d}I + A$$
has only one positive eigenvalue. Consequently, since $d\geq 1$, $-D/2+A$ has one positive eigenvalue since $-1/2\leq  \frac{-\sqrt{d}}{d+1}$.
\end{proof}

\begin{proof}[Proof of \cref{thm:uniqueneighborgraphs}]
If $G$ has a degree 1 vertex, then by \cref{lem:uniqueneighbordeg1} we are done.
Otherwise, if the minimum degree of $G$ is 2, then by \cref{lem:uniqueneighbordeg22} we are done.
Otherwise, the minimum degree of $G$ is at least 3. Then, by \cref{lem:projplane3rdprop} $G$ corresponds to a projective plane.
So, we are done by \cref{lem:projplane} and \cref{lem:projeplanelorentzian}.
\end{proof}

