\section{Targeted Attacks}\label{sec:TA}
\begin{algorithm}[H]
\caption{ Forced Strategy Change of Hubs}
\begin{algorithmic}
\Procedure{AttackHubs}{$attack\_magnitude$,$new\_startegy$}
    \State $Hubs \gets Sorted(agents, key \gets hub\_score)$
    \For{$i\gets 0, attack\_magnitude$}
        \State $s_{Hubs[i]} \gets new\_startegy$
    \EndFor
\EndProcedure
\end{algorithmic}
\end{algorithm}
\begin{algorithm}[H]
\caption{Car Users Come Together}
\begin{algorithmic}
\Procedure{ConnectDefectors}{$acceptance\_probability$}
    \ForAll{$ i \in |agents|$}
        \ForAll {$j \in social\_neighbourhood(i)$}
            \ForAll {$k \in social\_neighbourhood(j)$}
                \If{$s_i<0.5$ and $s_k<0.5$}
                    \If{$random()<acceptance\_probability$}
                        \State append $Edge(i,k)$ to $Edges(social\_network)$
                    \EndIf
                \EndIf
            \EndFor
        \EndFor
    \EndFor
\EndProcedure
\end{algorithmic}
\end{algorithm}
\clearpage
\section{Random Perturbations}\label{sec:RP}
\begin{algorithm}[H]
\caption{Broken Connections in the Social Network}
\begin{algorithmic}
\Procedure{ConnectionBreaks}{$perturbation\_magnitude$}
    \ForAll {$edge \in Edges(social\_network)$}
        \If{$random()<perturbation\_magnitude$}
            \State remove $edge$ from $Edges(social\_network)$
        \EndIf
    \EndFor
\EndProcedure
\end{algorithmic}
\end{algorithm}
\begin{algorithm}[H]
\caption{Agents Drop-out of the Social Network}
\begin{algorithmic}
\Procedure{AgentsDropOut}{$perturbation\_magnitude$}
    \ForAll{$ i \in |agents|$}
        \If{$random()<perturbation\_magnitude$}
            \State $\emph{E} \gets \{e \in Edges(social\_network)$ with i=source or i=destination $\}$
            \State remove $\emph{E}$ from $Edges(social\_network)$
        \EndIf  
    \EndFor
\EndProcedure
\end{algorithmic}
\end{algorithm}
\section{Interventions}\label{sec:Interventions}
\begin{algorithm}[H]
\caption{Vanilla CPI}
\begin{algorithmic}
\Procedure{Intervention1}{$acceptance\_probability$}
    \ForAll{$ i \in |agents|$}
        \ForAll {$j \in social\_neighbourhood(i)$}
            \ForAll {$k \in social\_neighbourhood(j)$}
                \If{$s_i>0.5$ and $s_j>0.5$ and $s_k>0.5$}
                    \If{$random()<acceptance\_probability$}
                        \State append $Edge(i,k)$ to $Edges(social\_network)$
                    \EndIf
                \EndIf
            \EndFor
        \EndFor
    \EndFor
\EndProcedure
\end{algorithmic}
\end{algorithm}
\begin{algorithm}[H]
\caption{Stable CPI}
\begin{algorithmic}
\Procedure{Intervention2}{$acceptance\_probability$}
    \ForAll{$ i \in |agents|$}
        \ForAll {$j \in social\_neighbourhood(i)$}
            \ForAll {$k \in social\_neighbourhood(j)$}
                \If{$s_i , s_j, s_k >0.5$ and $Edge(i,k) \notin Edges(social\_network)$}
                    \State$\Delta_{stability}\gets$
                    \begin{align*}
                        (L_2(s_i,s_i^{opt})+L_2(s_k,s_k^{opt}))-\\(L_2(s_i,s_i^{opt}(including Edge(i,k)))+L_2(s_k,s_k^{opt}(including Edge(i,k))))
                    \end{align*}
                    \If{$random()<acceptance\_probability$ and $\Delta_{stability}>0$}
                        \State append $Edge(i,k)$ to $Edges(social\_network)$
                    \EndIf
                \EndIf
            \EndFor
        \EndFor
    \EndFor
\EndProcedure
\end{algorithmic}
\end{algorithm}
\section{Theorems}\label{sec:proofs}
\begin{theorem}
    Centroid Minimizes the Sum of Squared Euclidean Distances
\end{theorem}
\begin{proof}
Let $(x_n, y_n)$ be $n$ points. We aim to minimize:
\begin{align*}
    f &= \sum_{i=1}^n (x - x_i)^2 + (y - y_i)^2 \\
    \frac{\partial f}{\partial x} &= \sum_{i=1}^n \frac{\partial}{\partial x} \left[ (x - x_i)^2 + (y - y_i)^2 \right] \\
    &= \sum_{i=1}^n 2(x - x_i)
\end{align*}
Setting the derivative to zero:
\begin{align*}
    \frac{\partial f}{\partial x} = 0 &\Rightarrow \sum_{i=1}^n 2(x_{\min} - x_i) = 0 \\
    &\Rightarrow \sum_{i=1}^n (x_{\min} - x_i) = 0 \\
    &\Rightarrow n \cdot x_{\min} = \sum_{i=1}^n x_i \\
    &\Rightarrow x_{\min} = \frac{1}{n} \sum_{i=1}^n x_i
\end{align*}
Similarly,
\[
    y_{\min} = \frac{1}{n} \sum_{i=1}^n y_i
\]
\end{proof}
