\subfigure[]{\includegraphics[width=0.45\textwidth]{figures/bar_example.pdf}}
\subfigure[]{\includegraphics[width=0.45\textwidth]{figures/bar_nODE.pdf}}
\caption{The distribution of probabilities of going to the bar for the standard (a) and neural ODE (b) version of the \textit{El Farol Bar problem}. In the standard version, the distribution of probabilities converges towards the crowding threshold of $c=0.9$ (blue). The neural ODE (b) is trained to align with the observed attendance rates, where the mean is indicated in red. The density histograms show the normalized distributions at turn 15.}
\vspace{-3mm}
\label{fig:efb}
