\begin{algorithm}[t]
  \caption{LingoLoop Attack}
  \label{alg:lingoloop}
  \begin{algorithmic}[1]
    \Require 
      Original image $\mathbf{x}$, prompt $c_{in}$, Perturbation budget $\epsilon$, step size $\eta$, Momentum factor $m$, iterations $T$, \texttt{max\_new\_tokens} $N_{max}$

    \State \textbf{Preprocessing:}
      % \State 1. Estimate $\bar{P}_{EOS}(t) = \mathbb{E}[f^{EOS}|t]$ via MLLM inference on image corpus
      \State 1. Estimate $\bar{P}_{EOS}(t) = \mathbb{E}[f^{EOS}|t]$ \Comment{Build POS-EOS mapping}

      \State 2. Define $w(t) = \phi(\bar{P}_{EOS}(t);\theta)$ \Comment{$\theta$: scaling params}


    \State \textbf{Attack Initialization:}
    \State $\mathbf{x'_0} \gets \mathbf{x} + \text{Uniform}(-\epsilon, +\epsilon)$ \Comment{Perturbation initialization}
    \State $g_0 \gets 0$ \Comment{Momentum buffer}

    \For{$t = 1$ \textbf{to} $T$}
        \State \textbf{Forward Pass:}
        \State $(\mathbf{y}, \{\mathbf{z}_j\}, \{h_j^{(l)}\}) \gets \text{MLLM}(\mathbf{x'_{t-1}}, c_{in})$ \Comment{Get output sequences, logits and hiddenstates}

        \State \textbf{$N_{out} \gets |\mathbf{y}|$} \Comment{Get generated token count}

        \State \textbf{if $N_{out} \geq N_{max}$: break} \Comment{Early termination}




        \State \textbf{POS-Aware Delay Mechanism:}
        \For{$i = 1$ \textbf{to} $N_{out}$}
            \State $t_{i-1} \gets \text{POS}(\mathbf{y}_{i-1})$ \Comment{Predecessor POS tagging}
            \State $w_i \gets w(t_{i-1})$ \Comment{Retrieve suppression weight}
            \State $f^{EOS}_i \gets \text{softmax}(\mathbf{z}_i)_{\text{EOS}}$
        \EndFor
        \State $\mathcal{L}_{LPS} \gets \frac{1}{N_{out}}\sum w_i f^{EOS}_i$ 

        \State \textbf{Generative Path Pruning Mechanism:} 
        \State $\bar{r}_k \gets \frac{1}{L}\sum_{l=1}^L \|h_k^{(l)}\|_2,\; \forall k\in[1,N_{out}]$
        \State $\mathcal{L}_{Rep} \gets \frac{\lambda}{N_{out}}\sum \bar{r}_k$ 

        \State \textbf{Dynamic Adaptation:}
        \State $\lambda(t) \gets \frac{\|\mathcal{L}_{LPS}\|}{\|\mathcal{L}_{Rep}\|} \big/ (a\ln t + b)$ \Comment{Temporal decay}
        \State $\mathcal{L}_{Total} \gets \alpha\mathcal{L}_{LPS} + \lambda(t)\mathcal{L}_{Rep}$ 

        \State \textbf{Parameter Update:}
        \State $g_t \gets m \cdot g_{t-1} + \nabla_{x'}\mathcal{L}_{Total}$ \Comment{Momentum gradient}
        \State $\mathbf{x'_{t}} \gets \text{Clip}_{\epsilon}(\mathbf{x'_{t-1}} - \eta \cdot \text{sign}(g_t))$ \Comment{Projected update}
    \EndFor

    \Ensure Perturbed image $\mathbf{x'_{T}}$ with looping induction effect
  \end{algorithmic}
\end{algorithm}




