\subsubsection{Achievable Data Rate Region With TDMA}
Under the TDMA scheme, the two users are allocated orthogonal time slots. The pinching beamformer is independently optimized for each time slot. According to the optimal antenna positioning in \eqref{Per_User_Channel_Gain_Maximization}, during the time slot allocated to user $k$, the pinching beamformer is set to ${\mathbf{q}}_k^{\diamond}$. Therefore, the corresponding TDMA achievable rate region is given by
\begin{equation}\label{TDMA_Uplink_Multiple_Pinch_Region_Expression}
\begin{split}
{\mathcal{R}}_{{\rm{M}},{\rm{T}}}^{\rm{U}}\triangleq\bigcup\nolimits_{\rho_{\rm{T}}\in[0,1]}&\{(R_1^{\rm{U}},R_2^{\rm{U}}):0\leq R_1^{\rm{U}}\leq\rho_{\rm{T}}r_1^{\rm{U}}({\mathbf{q}}_1^{\diamond}),\\
&0\leq R_2^{\rm{U}}\leq(1-\rho_{\rm{T}})r_2^{\rm{U}}({\mathbf{q}}_2^{\diamond})\},
\end{split}
\end{equation}
where $r_k^{\rm{U}}({\mathbf{q}}_k^{\diamond})=\log_2( P_k\lvert h_k({\mathbf{q}}_k^{\diamond})\rvert^2/\sigma^2)$ for $k\in{\mathcal{K}}$.
\subsubsection{Achievable Data Rate Region With FDMA}\label{Section:Uplink:Multiple_Pinch:Achievable Rate Region With FDMA}
Under FDMA, both users transmit simultaneously over orthogonal frequency bands. For any given $\mathbf{q}$, the FDMA achievable region is given by ${\mathcal{R}}_{{\rm{M}},{\rm{F}}}^{\rm{U}}(\mathbf{q})\triangleq\bigcup\nolimits_{\rho_{\rm{F}}\in[0,1]}\{(R_1^{\rm{U}},R_2^{\rm{U}}):0\leq R_k^{\rm{U}}\leq R_{k}^{\rho_{\rm{F}}}(\mathbf{q}),\forall k\in{\mathcal{K}}\}$, where $R_{1}^{\rho_{\rm{F}}}(\mathbf{q})\triangleq\rho_{\rm{F}}\log_2\left(1+\frac{P_1\lvert h_{1}(\mathbf{q})\rvert^2}{\rho_{\rm{F}}{\sigma^2}}\right)$ and $R_{2}^{\rho_{\rm{F}}}(\mathbf{q})\triangleq({1-\rho_{\rm{F}}})\log_2\left(1+\frac{P_2\lvert h_{2}(\mathbf{q})\rvert^2}{(1-\rho_{\rm{F}}){\sigma^2}}\right)$. After \emph{time sharing} among different $\mathbf{q}$'s, the overall FDMA achievable rate region becomes ${\mathcal{R}}_{{\rm{M}},{\rm{F}}}^{\rm{U}}\triangleq{\rm{Conv}}\left(\bigcup\nolimits_{{\mathbf{q}}\in{\mathcal{P}}}{\mathcal{R}}_{{\rm{M}},{\rm{F}}}^{\rm{U}}(\mathbf{q})\right)$. This region can be characterized via a \emph{rate-profile} approach, similar to the derivation of ${\mathcal{R}}_{{\rm{S}},{\rm{F}}}^{\rm{U}}$ in Section \ref{Section: Single_Pinch: Achievable Rate Region With FDMA}. Given a rate-profile factor $\alpha_{\rm{F}}\in[0,1]$, we solve the following problem:
\begin{subequations}\label{Rate_Profile_Uplink_Multiple_Pinch_FDMA}
\begin{align}
\max_{{\mathbf{q}},R}~R~{\rm{s.t.}}~&{\mathbf{q}}\in{\mathcal{P}},R\geq0,\\
&R_{1}^{\rho_{\rm{F}}}(\mathbf{q})\geq \alpha_{\rm{F}} R,R_{2}^{\rho_{\rm{F}}}(\mathbf{q})\geq (1-{\alpha}_{\rm{F}}) R.
\end{align}
\end{subequations}
A suboptimal solution to this problem can be found using an element-wise alternating optimization method, similar to that used for problem \eqref{Rate_Profile_Uplink_General}. For brevity, the details are omitted. Based on this, an inner bound of ${\mathcal{R}}_{{\rm{M}},{\rm{F}}}^{\rm{U}}$, denoted as ${\mathcal{R}}_{{\rm{M}},{\rm{F}},{\rm{IB}}}^{\rm{U}}$, can be similarly obtained as ${\mathcal{C}}_{{\rm{M}},{\rm{IB}}}^{\rm{U}}$ (see \eqref{Uplink_Channel_Capacity_Region_Inner_Bound_Rate_Profile_Basic}). 
\subsubsection{Comparison and Further Discussion}
For any given ${\mathbf{q}}$, it holds that ${\mathcal{R}}_{{\rm{M}},{\rm{F}}}^{\rm{U}}(\mathbf{q})\subseteq{\mathcal{C}}^{\rm{U}}(\mathbf{q})$ \cite{el2011network}, which implies that ${\mathcal{R}}_{{\rm{M}},{\rm{F}}}^{\rm{U}}\subseteq{\mathcal{C}}_{\rm{M}}^{\rm{U}}$. Following a similar approach to the proof of Theorem \ref{Theorem_Comparision_TDMA_FDMA}, it can be shown that, under the multiple-pinch case, the TDMA region is nested in the FDMA region, i.e., ${\mathcal{R}}_{{\rm{M}},{\rm{T}}}^{\rm{U}}\subseteq{\mathcal{R}}_{{\rm{M}},{\rm{F}}}^{\rm{U}}$. Hence, the following inclusion chain holds: 
\begin{align}\label{Region_Uplink_Multiple_Relationship}
{\mathcal{R}}_{{\rm{M}},{\rm{T}}}^{\rm{U}}\subseteq{\mathcal{R}}_{{\rm{M}},{\rm{F}}}^{\rm{U}}\subseteq{\mathcal{C}}_{\rm{M}}^{\rm{U}}\subseteq{\mathcal{C}}_{{\rm{M}},{\rm{OB}}}^{\rm{U}}.
\end{align}

For ease of reference, we summarize in Table \ref{Table: PASS_Uplink_Capacity_Region} our main results on the uplink capacity/rate region characterization.

We now analyze how the number of activated pinching antennas, $N$, influences the capacity region of the PASS-enabled uplink channel. While it may seem intuitive that increasing 
$N$ should monotonically enlarge the capacity region---owing to enhanced spatial degrees of freedom---this is not always the case, as demonstrated below.

Let us examine the effective array gain of user $k$, which is expressed as follows:
\begin{subequations}\label{Array_Gain_Upper_Bound_Maximization_Pre}
\begin{align}
{\lvert h_k({\mathbf{q}})\rvert^2}&=\frac{\eta}{N}\left\lvert\sum\nolimits_{n=1}^{N}\frac{{\rm{e}}^{-{\rm{j}}\phi_{n}}}{\sqrt{d_k^2+(q_n-x_k)^2}}\right\rvert^2\\
&\leq\frac{\eta}{N}\left\lvert\sum\nolimits_{n=1}^{N}\frac{1}{\sqrt{d_k^2+(q_n-x_k)^2}}\right\rvert^2.
\end{align}
\end{subequations}
It follows that
\begin{align}\label{Array_Gain_Upper_Bound_Maximization}
{\lvert h_k({\mathbf{q}}_k^{\diamond})\rvert^2}\leq\max_{{\mathbf{q}}\in{\mathcal{P}}}\frac{\eta}{N}\left\lvert\sum_{n=1}^{N}\frac{1}{\sqrt{d_k^2+(q_n-x_k)^2}}\right\rvert^2
\triangleq A_{k}^{\triangleleft},
\end{align}
where ${\mathbf{q}}_k^{\diamond}=\argmax\nolimits_{{\mathbf{q}}\in{\mathcal{P}}}\lvert h_k({\mathbf{q}})\rvert^2$ as per \eqref{Per_User_Channel_Gain_Maximization}. The behavior of this upper bound $A_{k}^{\triangleleft}$ as a function of $N$ is characterized by the following lemma.
\vspace{-5pt}
\begin{lemma}\label{Lemma_Array_Gain_Upper_Limitation}
Given a fixed user position ${\mathbf{u}}_k$ and and a minimum inter-antenna spacing $\Delta$, the upper bound on the array gain scales as $A_{k}^{\triangleleft}\simeq{\mathcal{O}}\left({(\ln{N})^2}/{N}\right)$ when $N\rightarrow\infty$.
\end{lemma}
\vspace{-5pt}
\begin{IEEEproof}
See Appendix \ref{Proof_Lemma_Array_Gain_Upper_Limitation} for more details.
\end{IEEEproof}
The result in Lemma \ref{Lemma_Array_Gain_Upper_Limitation} implies that 
\begin{align}
\lim\nolimits_{N\rightarrow\infty}A_{k}^{\triangleleft}=\lim\nolimits_{N\rightarrow\infty}{\mathcal{O}}\left({(\ln{N})^2}/{N}\right)=0,
\end{align}
Combining this with the bounds in \eqref{Array_Gain_Upper_Bound_Maximization_Pre} and \eqref{Array_Gain_Upper_Bound_Maximization} and applying the \emph{Sandwich Theorem}, we obtain
\begin{align}
0\leq\lim_{N\rightarrow\infty}{\lvert h_k({\mathbf{q}})\rvert^2}
\leq\lim_{N\rightarrow\infty}{\lvert h_k({\mathbf{q}}_k^{\diamond})\rvert^2}\leq
\lim_{N\rightarrow\infty}A_{k}^{\triangleleft}=0.
\end{align}
Substituting this result into the individual and sum-rate expressions in \eqref{PASS_Uplink_Capacity_Region_Constraint1} and \eqref{PASS_Uplink_Capacity_Region_Constraint2} gives
\begin{subequations}
\begin{align}
\lim_{N\rightarrow\infty}r_k^{\rm{U}}({\mathbf{q}})&\leq \lim_{N\rightarrow\infty}r_k^{\rm{U}}({\mathbf{q}}_k^{\diamond})=0,\forall k\in{\mathcal{K}},\label{per_user_rate_bound}\\
\lim_{N\rightarrow\infty}r_{1,2}^{\rm{U}}({\mathbf{q}})&\leq\lim_{N\rightarrow\infty}\log_2(1+(P_1A_{1}^{\triangleleft}
+P_2A_{2}^{\triangleleft})/\sigma^2)\\&=\log_2(1+0/\sigma^2)=0.\label{sum_rate_upper_bound}
\end{align}
\end{subequations}
Therefore, the capacity region of any fixed beamformer ${\mathbf{q}}\in{\mathcal{P}}$ satisfies $\lim_{N\rightarrow\infty}{\mathcal{C}}^{\rm{U}}({\mathbf{q}})=\{(0,0)\}$.

Recalling the full capacity region is defined by the convex hull over all feasible beamformers (see \eqref{PASS_Uplink_Capacity_Region_General_Exhausitive}), it follows that
\begin{align}
\lim_{N\rightarrow\infty}{\mathcal{C}}_{\rm{M}}^{\rm{U}}={\rm{Conv}}\Big(\bigcup\nolimits_{{\mathbf{q}}\in{\mathcal{P}}}\{(0,0)\}\Big)=\{(0,0)\},
\end{align}
which, together with \eqref{Region_Uplink_Multiple_Relationship}, yields
\begin{align}\label{Asymptotic_Rate_Capacity_Region_Uplink_Multiple}
\lim_{N\rightarrow\infty}{\mathcal{R}}_{{\rm{M}},{\rm{T}}}^{\rm{U}}=\lim_{N\rightarrow\infty}{\mathcal{R}}_{{\rm{M}},{\rm{F}}}^{\rm{U}}
=\lim_{N\rightarrow\infty}{\mathcal{C}}_{\rm{M}}^{\rm{U}}=\{(0,0)\}.
\end{align}
The results in \eqref{Asymptotic_Rate_Capacity_Region_Uplink_Multiple} can be interpreted as follows. 
\vspace{-5pt}
\begin{remark}\label{remark_uplink_interpretation}
As $N$ increases, the aggregate noise power increases \emph{linearly} as $N\sigma^2$, while the total received signal power grows only \emph{sub-linearly} due to increasing average distance and severe path loss associated with farther positioned pinching elements. Thus, the per-user effective SNR degrades to zero, rendering both individual and sum-rate expressions negligible.
\end{remark}
