\subsection{Proof of Theorem \ref{Theorem_Comparision_TDMA_FDMA}}\label{Proof_Theorem_Comparision_TDMA_FDMA}
Given $\{x_1,x_2\}$, the Pareto boundary of the TDMA achievable rate region ${\mathcal{R}}_{{\rm{S}},{\rm{T}}}^{\rm{U}}$ corresponds to a line segment connecting the points $(0,{\mathcal{R}}_{{\rm{S}},2}^{\rm{U}})$ and $({\mathcal{R}}_{{\rm{S}},1}^{\rm{U}},0)$, where $\log_2\left(1+\frac{P_k\eta}{d_k^2{\sigma^2}}\right)\triangleq{\mathcal{R}}_{{\rm{S}},k}^{\rm{U}}$ for $k\in\{1,2\}$, as shown in {\figurename} {\ref{Figure_TDMA_FDMA_Region_AWGN}}. Furthermore, the FDMA rate regions ${\mathcal{R}}_{{\rm{S}},{\rm{F}}}^{\rm{U}}(x_1)$ and ${\mathcal{R}}_{{\rm{S}},{\rm{F}}}^{\rm{U}}(x_2)$ are convex sets, which satisfies $r_{2}^{0}(x_1)\leq{\mathcal{R}}_{{\rm{S}},2}^{\rm{U}}$ and $r_{1}^{1}(x_2)\leq{\mathcal{R}}_{{\rm{S}},1}^{\rm{U}}$. Due to the curved Pareto boundaries of ${\mathcal{R}}_{{\rm{S}},{\rm{F}}}^{\rm{U}}(x_1)$ and ${\mathcal{R}}_{{\rm{S}},{\rm{F}}}^{\rm{U}}(x_2)$, it is straightforward to show that \emph{time sharing} between these two FDMA regions suffices to fully cover the TDMA region, as depicted in {\figurename} {\ref{Figure_TDMA_FDMA_Region_AWGN}}. Therefore, we conclude that
\begin{align}
{\mathcal{R}}_{{\rm{S}},{\rm{T}}}^{\rm{U}}\subseteq{\rm{Conv}}\Big({\mathcal{R}}_{{\rm{S}},{\rm{F}}}^{\rm{U}}(x_1)\bigcup{\mathcal{R}}_{{\rm{S}},{\rm{F}}}^{\rm{U}}(x_2)\Big)\subseteq{\mathcal{R}}_{{\rm{S}},{\rm{F}}}^{\rm{U}}.
\end{align}
This concludes the proof.
\subsection{Proof of Lemma \ref{Lemma_Array_Gain_Upper_Limitation}}\label{Proof_Lemma_Array_Gain_Upper_Limitation}
According to \cite{xu2024rate,ouyang2025array}, the maximization of the right-hand side of \eqref{Array_Gain_Upper_Bound_Maximization} is attained by uniformly placing the $N$ antennas with an inter-element spacing $\Delta$ and setting the center of the array aperture spanned by these antennas aligned with the projection of user $k$ along the waveguide, which yields
\begin{align}
q_n=(n-1)\Delta+q_1,\forall n>1,q_{N}+q_{1}=2x_k.
\end{align}
For notational simplicity, $N$ is assumed to be an even integer. In this case, we have 
\begin{subequations}
\begin{align}
A_{k}^{\triangleleft}&=\frac{\eta}{N}
\left\lvert\sum\nolimits_{n=1}^{{N}/{2}}\frac{2}{d_k\sqrt{1+(\Delta/2+(n-1)\Delta)^2/d_k^2}}\right\rvert^2\\
&=\frac{\eta}{N\Delta^2}
\left\lvert\sum\nolimits_{n=1}^{{N}/{2}}\frac{2\Delta/d_k}{\sqrt{1+((n-1/2)(\Delta/d_k))^2}}\right\rvert^2.\label{Array_Gain_Upper_Bound_Intermideate}
\end{align}
\end{subequations}
Since $\frac{\Delta}{d_k}\ll 1$, the summation in \eqref{Array_Gain_Upper_Bound_Intermideate} can be accurately approximated using a definite integral as follows:
\begin{subequations}
\begin{align}
A_{k}^{\triangleleft}&\approx\frac{\eta}{N\Delta^2}\bigg( \int_{0}^{{N\Delta}/{(2d_k)}}\frac{2}{\sqrt{1+x^2}}{\rm{d}}x\bigg)^2\\
&=\frac{4\eta\left(\ln\left(\sqrt{1+(\frac{N\Delta}{2d_k})^2}+\frac{N\Delta}{2d_k}\right)\right)^2}{N\Delta^2}.\label{Array_Gain_Upper_Bound_Later}
\end{align}
\end{subequations}
It follows from \eqref{Array_Gain_Upper_Bound_Later} that $A_{k}^{\triangleleft}\simeq{\mathcal{O}}\left({(\ln{N})^2}/{N}\right)$ as $N\rightarrow\infty$. This concludes the proof.
