\begin{example}\label{ex:1}
Consider  the LFSR  with characteristic polynomial $p_1(x)=1+x+x^3$ and initial state $\{1 1 1\}$.
The corresponding PN-sequence is: $\{a_i\}=\{ 1   1   1   0   0   1   0\}$.
Consider now
$\{a_{i+3}\}=\{ 0   0   1   0   1   1   1\}$, which is the same PN-sequence $\{a_i\}$ starting in position $k=3$. 
The sequence
$\{a_i+a_{i+3}\}=\{1   1   0   0   1   0   1\}$
is the same PN-sequence $\{a_i\}$ starting at position $\ensuremath{\mathcal{Z}}_{\alpha}(3)=1$ (see Example~\ref{ex:zech}).
\end{example}

 \begin{corollary}\label{cor:2}
Let $p(x)\in\mathbb{F}_2[x]$ be a primitive polynomial of degree $L$ and   $\{a_i\}$ the corresponding PN-sequence.
If we sum two different shifted versions  $\{a_{i+k_1}\}$   and $\{a_{i+k_2}\}$ of $\{a_i\}$, the resultant sequence $\{a_{i+k_1}+a_{i+k_2}\}$ is a shifted version of $\{a_i\}$  starting at position $k=\ensuremath{\mathcal{Z}}_{\alpha}(k_2-k_1)+k_1$.
\end{corollary}

\begin{proof}
 If we denote $\{u_i\}=\{a_{i+k_1}\}$, then $\{u_{i+k_2-k_1}\}=\{a_{i+k_2}\}$.
 Therefore, according to Theorem~\ref{lem:2}, $\{u_{i+k_2-k_1}\}$ is a shifted version of $\{u_i\}$ with a shift $k'=\zech{\alpha}{k_2-k_1}$.
 Now,  $\{u_i\}$ is a shifted version of $\{a_i\}$ with a shift $k_1$.
 Finally, $\{u_{i+k_2-k_1}\}$ is a shifted version of $\{a_i\}$ with a shift   $k=k'+k_1=\zech{\alpha}{k_2-k_1}+k_1.$
\end{proof} 

Now, we are ready to examine the configuration of the CAs responsible for generating interleaving sequences.
First, it is important to note that 102-CAs also generate  individual PN-sequences. 

\begin{theorem}\cite[Theorem 3.3]{Cardell2019bk}
      There exists a regular, cyclic 102-CA of length $\sfrac{\left(2^L-1\right)}{\gcd\left(\zech{\alpha}{1},2^L-1\right)}$,
 that generates the same PN-sequence as that produced by a primitive polynomial $p(x)$ of degree~$L$.
\end{theorem}

\subsubsection{Generating 2-interleaving sequences}\label{sec:102:2}
We start with the study of the generation of 2-interleaving sequences.
 This means that we are interleaving a PN-sequence of period $T=2^L-1$ and linear complexity $L$ with a shifted version of itself.
We consider only the 2-interleaving with maximum period and maximum linear complexity, that is,  $2T$ and $2L$, respectively.
Although sequences with non-maximum linear complexity and period can still be generated by a cellular automata, we will not consider this case, as it is of limited relevance to cryptographic applications.
 From now on, 
 $\alpha$ is the root of the characteristic polynomial of the corresponding PN-sequence.

The next result states the structure of the 102-CA that generates such a sequence. 

 \begin{theorem}\label{thm:102-2}
 Consider a $2$-interleaving sequence with maximum $LC$ (that is $2L)$.
 There exists a 102-CA (60-CA) of length 
 $$\frac{ 2T}{\gcd(T,D)}$$
 that generates the interleaving sequence in the 0-th column,
where $T$ is the period of the PN-sequence and $D=\ensuremath{\mathcal{Z}}_{\alpha}(1)$.
 \end{theorem}
   \begin{proof}
   Consider the PN-sequence $\{a_i\}$ and the shifted version
   $\{a_{i+k}\}$.
   The corresponding 2-interleaving sequence has the form:
   $$
   \{v_j^{(0)}\}=\{a_0,a_k,a_1,a_{k+1}, a_2, a_{k+2} \ldots \} 
   $$
   Assume we write this sequence in the 0-th column of the 102-CA.
  We   claim that the sequences in the columns with even index, that is, $\{v_j^{(2m)}\}$, with $m=0,1\ldots$ are shifted versions of $ \{v_j^{(0)}\}$.

   According to the general form of this 102-CA (see Table~\ref{tab:gen:102CAa} in Appendix 1), the sequence in 
   the first column is 
 $$
   \{v_j^{(1)}\}
   =\{v_0^{(0)}+v_1^{(0)},v_1^{(0)}+v_2^{(0)}, v_2^{(0)}+v_3^{(0)}, \ldots \} 
   =\{a_0+a_k, a_k+a_1,a_1+a_{k+1},a_{k+1}+a_2, \ldots \} 
   $$
  and  the 2-nd column has the form
   $$\{v_j^{(2)}\}
   =\{v_0^{(1)}+v_1^{(1)},v_1^{(1)}+v_2^{(1)}, v_2^{(1)}+v_3^{(1)}, \ldots \} 
   =\{a_0+a_1,a_k+a_{k+1},a_1+a_2, a_{k+1}+ a_{k+2} \ldots \}$$
   that is, $\{v_j^{(2)}\}$ is a 2-interleaving sequence composed of   
   $\{a_i+a_{i+1}\}$ and $\{a_{i+k}+a_{i+k+1}\}$.
   Notice that, according to Theorem~\ref{lem:2},
   $\{a_i+a_{i+1}\}$ is a shifted version of $\{a_i\}$ and  $\{a_{i+k}+a_{i+k+1}\}$ is a shifted version of $\{a_{i+k}\}$ both with a  shift $D=\zech{\alpha}{1}$.
     This means that $\{v_j^{(2)}\}$ is a shifted version of $ \{v_j^{(0)}\}$ with a shift $2 D$.

   Using the same argument, we can assure that the sequence in the 4-th  column, $\{v_j^{(4)}\}$, is a shifted version of $\{v_j^{(2)}\}$ with a shift $2D$, that is,  a shifted version of $\{v_j^{(0)}\}$, with a shift $4D$.
   Therefore, the sequence in the $2m$-th column is a shifted version of $\{v_j^{(0)}\}$ with a shift $2mD$.

Now, since $2T$ is the period of the 2-interleaving sequence $\{v_j^{(0)}\}$, we know that the column $\{v_j^{(\ell)}\}$, with $\ell= 2 T$ is the same as $ \{v_j^{(0)}\}$, and the shift in this case is $2TD$.
  Therefore, there exists a 102-CA of length $2T$ that generates $\{v_j^{(0)}\}$. 
  However, if $d=\gcd(T,D)\not =1$, the CA can be shorter, since the sequence $ \{v_j^{(0)}\}$ appears in a column prior to the $2T$-th.
  In this case, the column in position
$\frac{ 2T}{\gcd(T,D)}$  is the same as  $ \{v_j^{(0)}\}$
  and the corresponding shift  is $\frac{2TD}{d}$, which is a multiple of~$2T$.
   \end{proof}

      \begin{remark}
       If we observe the sequences in  the odd columns, we check that they are also shifted versions of the same sequence with the same shifts. 
        This means that there are shifted versions of two different sequences (one of them is the given 2-interleaving sequence) that appear several times along the CA.
      \end{remark}


